-- =========================================================================
-- STANDALONE SQL IMPORT FOR CCA-F: Claude Certified Architect — Foundations
-- Total questions: 134 questions
-- Default status: is_disabled = false
-- =========================================================================

BEGIN;

-- 1. Ensure custom_certificates table has is_disabled & badge column
ALTER TABLE public.custom_certificates ADD COLUMN IF NOT EXISTS is_disabled BOOLEAN DEFAULT false;
ALTER TABLE public.custom_certificates ADD COLUMN IF NOT EXISTS badge TEXT DEFAULT 'none';

-- 2. Upsert Certificate metadata
INSERT INTO public.custom_certificates (
  id, name, code, description, difficulty, estimated_hours, color_class, icon_name, is_vip, is_disabled, badge
) VALUES (
  'cca-f',
  'Claude Certified Architect — Foundations',
  'CCA-F',
  'Chinh phục chứng chỉ Kiến trúc sư Claude (Foundations) ủy quyền bởi Anthropic. Bao quát thiết kế prompt, kiến trúc tác nhân, MCP (Model Context Protocol), và rào chắn an toàn.',
  'Trung cấp',
  '12-18 Giờ',
  'bg-gradient-to-br from-amber-600 via-orange-700 to-amber-950 text-white',
  'Trophy',
  false,
  false,
  'verified'
) ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  code = EXCLUDED.code,
  description = EXCLUDED.description,
  difficulty = EXCLUDED.difficulty,
  estimated_hours = EXCLUDED.estimated_hours,
  color_class = EXCLUDED.color_class,
  icon_name = EXCLUDED.icon_name,
  badge = EXCLUDED.badge;

-- 3. Upsert Questions
INSERT INTO public.questions (
  id, cert_id, question_number, text, options,
  correct_answers, explanation, category, tags, image_url, status
) VALUES
  ('cca-1', 'cca-f', 1, 'Your `send_notification` tool invokes third-party messaging APIs. If these services time out during delivery, you cannot tell whether the message was actually sent. At present, the tool returns `is_error: true` with a generic “Notification failed” message for every timeout. Production monitoring shows that agents automatically retry these failures, often causing users to receive duplicate notifications. How should you change the error response?', '[{"key":"A","text":"Return is_error: true with a structured field retry_safe: true for timeouts, distinguishing them from permanent failures that should not be retried."},{"key":"B","text":"Return is_error: true with a message communicating uncertainty: “Timeout – status unknown. Message may have been sent. Avoid retry.”"},{"key":"C","text":"Return is_error: true with a message encouraging retry: “Delivery service temporarily unavailable. Please retry the notification.”"},{"key":"D","text":"Return is_error: true with the original message content echoed back."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Thời gian chờ sau khi yêu cầu gửi sẽ tạo ra tình trạng không xác định được kết quả thay vì xác nhận gửi không thành công. Vì thông báo có thể đã được gửi nên việc thử lại tự động có thể tạo ra một bản sao; lỗi phải nêu rõ rằng trạng thái không xác định và khuyên bạn không nên thử lại.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-2', 'cca-f', 2, 'You configured the system so that all four subagents can access the full set of 18 tools. During testing, agents often invoke tools outside their specialization—the synthesis agent performs web searches, and the report generator attempts document analysis. What is the main cause of this poor tool-selection behavior?', '[{"key":"A","text":"Choosing from 18 tools instead of 4-5 relevant ones increases decision complexity beyond reliable selection thresholds."},{"key":"B","text":"The tool definitions consume too much context window space, leaving insufficient room for task content."},{"key":"C","text":"The agents’ role descriptions in their system prompts conflict with having access to tools outside that role."},{"key":"D","text":"The coordinator cannot track which capabilities each subagent has, leading to misrouted tasks."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Cấp cho mọi tác nhân chuyên biệt quyền truy cập vào tất cả 18 công cụ sẽ mở rộng không gian ra quyết định với nhiều lựa chọn không liên quan. Sự phức tạp trong lựa chọn ngày càng tăng này làm cho việc lựa chọn công cụ đáng tin cậy trở nên khó khăn hơn và khiến các tác nhân sử dụng các khả năng nằm ngoài chuyên môn dự định của họ.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-3', 'cca-f', 3, 'You’re implementing escalation logic for when the agent should invoke `escalate_to_human`. Your team has proposed four different ways to trigger escalation. Which approach will most reliably identify cases that truly need human intervention?', '[{"key":"A","text":"Implement sentiment analysis that monitors for frustration indicators (negative language, repeated questions, exclamation marks) and trigger escalation when the frustration score exceeds a configured threshold."},{"key":"B","text":"Configure the agent to escalate after three consecutive tool calls that fail to resolve the customer’s stated issue, ensuring a reasonable attempt before involving a human."},{"key":"C","text":"Instruct the agent to escalate when the customer requests a human, when the issue requires policy exceptions, or when the agent cannot make meaningful progress."},{"key":"D","text":"Build a rules engine that maps specific issue types, customer segments, and product categories to escalation decisions, removing the need for model judgment calls."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc chuyển cấp con người là đáng tin cậy nhất khi nó được kích hoạt bởi các điều kiện rõ ràng, liên quan đến nhiệm vụ: khách hàng yêu cầu một cách rõ ràng về con người, giải pháp cần thiết liên quan đến ngoại lệ chính sách hoặc tổng đài viên không thể đạt được tiến bộ đáng kể. Những điều kiện này phản ánh trực tiếp nhu cầu đánh giá hoặc hỗ trợ của con người, không giống như ngưỡng cảm tính, số lần thử lại cố định hoặc ánh xạ danh mục cứng nhắc.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-4', 'cca-f', 4, 'Production reviews show that uncertainty is handled inconsistently in final reports. At times, conflicting subagent findings are combined into one confident statement, losing nuance; at other times, reports use so many qualifications that they become unhelpful. When the web-search agent reports “industry analysts estimate $50B market size (methodology varies)” and the document-analysis agent reports “peer-reviewed study estimates $35B (±$7B, 95% CI),” the coordinator either arbitrarily selects one or produces vague wording such as “the market may be $35B-$50B depending on factors.” What systematic approach best resolves this?', '[{"key":"A","text":"Configure subagents to only report findings meeting a high-confidence threshold, filtering uncertain information before it reaches the coordinator."},{"key":"B","text":"Add a verification subagent that cross-references findings across sources, only passing claims to synthesis that are corroborated by at least two independent sources."},{"key":"C","text":"Instruct the synthesis agent to structure reports with explicit sections distinguishing well-established findings from contested ones, preserving original source characterizations and methodological context."},{"key":"D","text":"Implement a confidence calibration layer that normalizes subagent uncertainty expressions to standardized probability scores (0.0-1.0), then weight-average findings by their calibrated confidence."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Báo cáo phải phân biệt các kết luận được xác lập rõ ràng với những kết luận vẫn còn gây tranh cãi, đồng thời duy trì tính không chắc chắn, phương pháp và đặc điểm bằng chứng đã nêu của mỗi nguồn. Điều này thể hiện sự bất đồng thực sự mà không tùy tiện chọn kết quả, san bằng sự không chắc chắn thành một con số duy nhất hoặc che khuất bối cảnh hữu ích bằng phòng ngừa rủi ro chung.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-5', 'cca-f', 5, 'Your multi-agent research pipeline crashed after processing 12 of 28 documents. The web-search agent had identified relevant sources, the document analyzer had partly completed extraction, and the synthesizer had started identifying patterns.  
  
You need to resume processing without duplicating work or losing fidelity from earlier findings. Which state-management approach best balances information fidelity and context efficiency when restoring agent state?', '[{"key":"A","text":"Have each agent persist a structured export to a known location. On resume, the coordinator loads the manifest and injects relevant state into agent prompts."},{"key":"B","text":"Index all agent outputs in a shared vector store. When resuming, each agent queries the store using semantic search to retrieve relevant prior findings."},{"key":"C","text":"Have each agent maintain its own persistent state file and reload it independently at the start of each session."},{"key":"D","text":"Persist the coordinator’s conversation log containing all task delegations and responses, providing this to agents when resuming."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc xuất tác nhân có cấu trúc và bền vững sẽ giữ lại các kết quả trung gian chính xác, trong khi bảng kê khai điều phối viên ghi lại những gì đã hoàn thành và thành phần lạ nào thuộc về từng nhiệm vụ. Khi khôi phục, điều phối viên chỉ có thể khôi phục trạng thái liên quan vào bối cảnh làm việc của từng tổng đài viên, tránh xử lý trùng lặp cũng như tình trạng cồng kềnh và mơ hồ khi phát lại nhật ký hội thoại hoàn chỉnh.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-6', 'cca-f', 6, 'After the web-search agent locates 25 sources (120K tokens of raw content), the document-analysis agent identifies key insights (15K tokens), and the synthesis agent creates a coherent narrative draft (3K tokens), the coordinator must provide context to the report-generation agent for the final output with proper source citations. Which context-passing strategy best balances completeness and efficiency?', '[{"key":"A","text":"Pass the full accumulated context from all prior agents."},{"key":"B","text":"Pass the synthesis draft along with a structured source index that maps key claims to their source URLs and relevant excerpts."},{"key":"C","text":"Pass only the synthesis draft and have a separate post-processing pipeline match claims to sources and insert citations after the report is generated."},{"key":"D","text":"Pass a condensed summary of all prior stages that preserves the main findings and attributes them to sources by name only."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Bản nháp tổng hợp cung cấp cho trình tạo báo cáo bản tường thuật vốn đã mạch lạc, trong khi chỉ mục nguồn có cấu trúc liên kết các tuyên bố quan trọng với các URL hỗ trợ chính xác và các đoạn trích có liên quan. Điều này giữ lại nguồn gốc trích dẫn có thể kiểm chứng mà không chuyển toàn bộ bối cảnh nghiên cứu thô hoặc yêu cầu bước tái tạo trích dẫn không đáng tin cậy sau khi tạo.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-7', 'cca-f', 7, 'Your `control_device` tool controls smart-home devices through external APIs. If a device fails to respond within the timeout period, the tool returns an error. Production logs indicate that the agent only tells users, “the device is not responding,” without providing useful next steps. Which error-response structure would best allow the agent to provide helpful follow-up?', '[{"key":"A","text":"Set is_error: true with a structured technical error containing the device ID, timeout duration, and raw API response code for debugging purposes."},{"key":"B","text":"Set is_error: true with a brief “Device offline” message and provide a separate tool the agent can call to retrieve context-specific troubleshooting suggestions."},{"key":"C","text":"Set is_error: false with an optimistic message indicating the command was dispatched successfully but device acknowledgment is still pending."},{"key":"D","text":"Set is_error: true with a message explaining the likely cause and suggesting troubleshooting steps the agent can offer the user."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Phản hồi lỗi phải báo hiệu chính xác thời gian chờ đồng thời cung cấp bối cảnh hữu ích và phù hợp với người dùng. Việc bao gồm nguyên nhân có thể xảy ra và các bước khắc phục sự cố được đề xuất sẽ cung cấp cho tổng đài viên thông tin có thể ngay lập tức biến thành hướng dẫn tiếp theo hữu ích.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-8', 'cca-f', 8, 'The synthesis agent receives summarized findings from the web-search and document-analysis agents, then sends a consolidated summary to the report generator. During testing, you find that generated reports make factual claims without proper citations—the report generator cannot trace statements to their original sources because metadata was lost during summarization. What is the most effective approach for ensuring proper source attribution in the final reports?', '[{"key":"A","text":"Have the report generator query the web search agent to re-locate sources for claims in the final report."},{"key":"B","text":"Have each agent output structured data separating content summaries from source metadata (URLs, document names, page numbers)."},{"key":"C","text":"Skip summarization and pass full raw outputs from web search and document analysis directly to the report generator."},{"key":"D","text":"Instruct the synthesis agent to embed source references inline within its summary text using a consistent citation format."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Kết quả đầu ra có cấu trúc giúp tách biệt các bản tóm tắt nội dung với siêu dữ liệu xuất xứ—chẳng hạn như URL, tên tài liệu và số trang—duy trì khả năng truy nguyên qua các giai đoạn tóm tắt. Sau đó, trình tạo báo cáo có thể liên kết các tuyên bố thực tế với các nguồn ban đầu của chúng và tạo ra các trích dẫn chính xác.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-9', 'cca-f', 9, 'The agent confirms customer identity through a multi-step process before resetting passwords. During testing, after the customer answers the third verification question, the agent asks for their name again, as though the earlier exchange never occurred. What is the most likely reason for this behavior?', '[{"key":"A","text":"The verification tool is clearing the agent’s internal state after each successful validation step."},{"key":"B","text":"Claude’s memory retention is limited to two conversational turns by default, requiring explicit configuration to extend it."},{"key":"C","text":"The conversation history isn’t being passed in subsequent API requests."},{"key":"D","text":"The prompt lacks instructions telling Claude to remember information across multiple exchanges."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }API Tin nhắn Claude yêu cầu ứng dụng cung cấp tin nhắn trợ lý và người dùng có liên quan trước đó với mỗi yêu cầu mới để duy trì bối cảnh hội thoại. Khi các yêu cầu tiếp theo bỏ qua lịch sử cuộc trò chuyện, Claude có quyền truy cập no vào thông tin được thiết lập trong các lần trao đổi trước đó và có thể yêu cầu lại thông tin đó.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-10', 'cca-f', 10, 'In production, final reports often include claims that lack proper source attribution. An investigation finds that web-search and document-analysis agents correctly attach citations to their outputs, but the synthesis agent loses track of which sources support each conclusion when it combines findings. What is the most effective architectural change?', '[{"key":"A","text":"Require all subagents to output structured claim-source mappings that the synthesis agent must preserve and merge when combining findings from multiple sources."},{"key":"B","text":"Maintain complete transcripts of all subagent interactions and add a citation-resolution agent to analyze logs and determine attributions before report generation."},{"key":"C","text":"Add a verification step where the report generator uses semantic similarity matching against original sources to reconstruct which claims came from which documents."},{"key":"D","text":"Have the coordinator inject source identifier prefixes into text before each handoff, then parse these prefixes at report generation to reconstruct citations."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Ánh xạ xác nhận quyền sở hữu tới nguồn có cấu trúc rõ ràng bảo toàn nguồn gốc trích dẫn thông qua quá trình tổng hợp và cho phép báo cáo kết hợp giữ lại các nguồn hỗ trợ chính xác cho mọi kết luận. Việc cố gắng suy ra sự ghi công sau đó từ bản ghi, độ tương tự về ngữ nghĩa hoặc tiền tố văn bản sẽ kém tin cậy hơn so với việc mang xuất xứ dưới dạng siêu dữ liệu có cấu trúc hạng nhất.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-11', 'cca-f', 11, 'A customer comes back **4 hours** after the original session about the same billing dispute. The prior **32-turn** session includes `lookup_order` results stating: “Status: PENDING, Expected resolution: 24-48 hours.” During testing, you find that, when sessions with stale tool results are resumed, the agent frequently cites the outdated information in its responses (for example, “I see your refund is still being processed”) even after later fresh tool calls return different details. What approach most reliably supports returning customers?', '[{"key":"A","text":"Start a new session, inject a structured summary of the previous interaction (issue type, actions taken, resolution status), then make fresh tool calls before engaging."},{"key":"B","text":"Resume with full history but filter out previous tool_result messages before resuming, keeping only the human/assistant turns so the agent must re-fetch needed data."},{"key":"C","text":"Resume with full history and configure the agent to automatically re-call all previously-used tools at session start to ensure data freshness."},{"key":"D","text":"Resume with full history and add a system prompt instruction telling the agent to always prefer the most recent tool results when multiple calls to the same tool exist in context."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Bắt đầu một phiên mới bằng bản tóm tắt có cấu trúc sẽ duy trì bối cảnh lâu dài như vấn đề, hành động đã hoàn thành và trạng thái giải pháp trước đó mà không giữ lại các quan sát cũ của công cụ. Việc thực hiện lệnh gọi công cụ mới trước khi phản hồi sẽ làm cho trạng thái bên ngoài hiện tại trở thành dữ liệu hoạt động duy nhất có sẵn cho tổng đài viên, tránh xung đột với các kết quả cũ hơn và các xác nhận trước đó không được hỗ trợ.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-12', 'cca-f', 12, 'During a billing-dispute resolution, your agent successfully retrieves customer information through `get_customer` and order details through `lookup_order`, but receives a timeout error when it attempts to call `process_refund`. The agent has sufficient information to explain the charges and confirm refund eligibility, but cannot process the refund because of the backend failure. What approach best balances first-contact resolution with appropriate error handling?', '[{"key":"A","text":"Explain the billing confirm refund eligibility, acknowledge the system issue preventing immediate processing, and offer escalation or retry later"},{"key":"B","text":"Confirm the refund will be processed and close the conversation, since the system has all necessary information to complete it automatically"},{"key":"C","text":"Implement automatic retries with exponential backoff for process_refund, keeping the conversation open until the refund is successfully processed"},{"key":"D","text":"Escalate immediately to a human agent since the refund action cannot be completed"}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Khi lỗi phụ trợ ngăn cản việc thực hiện khoản tiền hoàn lại đủ điều kiện, nhân viên hỗ trợ phải giải thích thông tin thanh toán có sẵn và kết quả đủ điều kiện, nêu rõ rằng sự cố hệ thống ngăn cản việc xử lý ngay lập tức và cung cấp tùy chọn tiếp theo như chuyển lên cấp cao hơn hoặc thử lại sau. Điều này duy trì tính minh bạch và nâng cao khả năng giải quyết của khách hàng mà không xác nhận sai rằng khoản hoàn trả chưa hoàn tất đã được xử lý.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-13', 'cca-f', 13, 'Your content-curation agent finds articles, evaluates each one for relevance, and then adds chosen articles to themed collections. Using separate `discover_articles(topic)`, `analyze_article(id)`, and `add_to_collection(article_id, collection_id)` tools, you observe 18+ sequential tool calls per request, creating latency problems. The agent must make editorial decisions about which articles match a collection’s theme—this requires viewing all candidates and their analysis scores at the same time to choose a cohesive set. Which tool composition best improves efficiency while retaining editorial judgment?', '[{"key":"A","text":"Keep all tools separate but implement response caching for analyze_article calls."},{"key":"B","text":"Create a curate_collection(topic, collection_id) tool that handles discovery, analysis, and selection internally using configurable quality thresholds."},{"key":"C","text":"Create a discover_and_analyze(topic) composite tool that returns all candidates with their analysis scores, keeping add_to_collection separate for selective calls."},{"key":"D","text":"Add a preview_curation(topic, collection_id) tool that shows what would be added based on predefined rules, with an approve_curation() tool to confirm."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Hoạt động khám phá và phân tích tổng hợp có thể thu thập và chấm điểm tất cả các bài viết phù hợp trong một quy trình làm việc, giảm chi phí gọi công cụ trong khi cung cấp cho tổng đài viên bộ so sánh hoàn chỉnh cần thiết để đưa ra lựa chọn biên tập gắn kết. Việc giữ riêng biệt thao tác thêm sẽ duy trì khả năng của tổng đài viên trong việc chọn chính xác ứng viên đã ghi điểm nào được thêm vào thay vì ủy quyền lựa chọn cho các ngưỡng cố định hoặc quy tắc được xác định trước.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-14', 'cca-f', 14, 'Production monitoring indicates that follow-up queries such as “summarize what we learned about market trends” consistently require more than 40 seconds. Investigation shows that the coordinator launches the synthesis subagent for every summarization request and passes it 80K+ tokens of accumulated findings. The coordinator already retains these findings in its context from coordinating the research. What is the most effective approach to improve response time for these follow-up summaries?', '[{"key":"A","text":"Enable prompt caching on the synthesis subagent to reduce the overhead of repeatedly transferring the same research findings."},{"key":"B","text":"Have the coordinator handle straightforward summarization requests directly using its existing context, reserving subagent spawning for complex analysis."},{"key":"C","text":"Pre-generate and cache summaries at multiple granularities whenever new findings accumulate."},{"key":"D","text":"Spawn the synthesis subagent with reduced context and have it request specific findings from the coordinator on-demand."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc xử lý tóm tắt thông thường trong điều phối viên sẽ tránh được độ trễ và chi phí xử lý mã thông báo khi tạo ra tác nhân phụ tổng hợp và truyền lại hơn 80K mã thông báo mà điều phối viên đã có trong ngữ cảnh. Việc tạo ra tác nhân phụ có thể được dành riêng cho các nhiệm vụ cần phân tích bổ sung hoặc phức tạp.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-15', 'cca-f', 15, 'After the web-search agent and document-analysis agent complete their tasks, the coordinator invokes the synthesis agent. However, the synthesis agent reports that it cannot complete the task because no research findings were supplied. What is the most likely cause of this problem?', '[{"key":"A","text":"The subagents need to share a single API connection to enable automatic context sharing between invocations."},{"key":"B","text":"The synthesis agent needs tools that can fetch results directly from the other agents’ conversation histories."},{"key":"C","text":"The coordinator did not include the outputs from the previous agents in the synthesis agent’s prompt."},{"key":"D","text":"The synthesis agent’s context window is not large enough to hold the combined outputs from both previous agents."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Đầu ra của tác nhân không tự động được đưa vào lệnh gọi mô hình riêng biệt. Điều phối viên phải cung cấp những phát hiện của tác nhân trước đó làm bối cảnh đầu vào cho tác nhân tổng hợp; mặt khác, nó có tài liệu nghiên cứu no để tổng hợp.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-16', 'cca-f', 16, 'A document-extraction tool uses ML models to extract invoice fields (vendor, amount, date). The models return confidence scores (0.0–1.0) for each extracted field. In production, you observe:  
  
1. The agent proceeds with low-confidence extractions that are incorrect 23% of the time.  
2. The agent requests unnecessary human review for 31% of extractions that were actually correct.  
  
How should the tool’s output be restructured?', '[{"key":"A","text":"Return fields with their raw confidence scores and add detailed few-shot examples to your system prompt demonstrating how to interpret different confidence ranges and when to request human review."},{"key":"B","text":"Return fields with confidence scores, plus a request_review boolean computed using your tested confidence thresholds, along with a review_reasons array explaining which fields triggered review."},{"key":"C","text":"Compute an aggregate extraction_quality score across all fields and return it alongside the extracted values. Include a text summary describing the overall extraction reliability."},{"key":"D","text":"Return fields organized into verified and needs_verification objects based on confidence thresholds."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các ngưỡng tin cậy đã kiểm tra phải được mã hóa dưới dạng quyết định xem xét rõ ràng để hành vi tiếp theo không phụ thuộc vào việc tác nhân diễn giải điểm số thô một cách không nhất quán. Việc trả về điểm tin cậy, một boolean `request_review` và các lý do đánh giá theo từng trường cụ thể sẽ duy trì khả năng kiểm tra trong khi chỉ định tuyến một cách đáng tin cậy các trích xuất kích hoạt ngưỡng để con người xem xét.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-17', 'cca-f', 17, 'Once the web-search and document-analysis subagents have finished their tasks, the coordinator must spawn a synthesis subagent to combine the findings. What is the correct way to give the synthesis subagent the information it requires?', '[{"key":"A","text":"Spawn the subagent with only a brief task description, relying on automatic context inheritance from the coordinator"},{"key":"B","text":"Provide the subagent with tool definitions that allow it to request outputs from other subagents via callbacks"},{"key":"C","text":"Pass reference identifiers and configure the subagent with read access to a shared memory store where other subagents deposited their results"},{"key":"D","text":"Include the complete findings from both subagents directly in the synthesis subagent’s prompt"}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Một tác nhân con tổng hợp được tạo ra cần các kết quả nghiên cứu có liên quan được cung cấp rõ ràng trong ngữ cảnh nhiệm vụ của nó. Việc bao gồm các phát hiện đầy đủ từ các tác nhân phụ tìm kiếm trên web và phân tích tài liệu trong dấu nhắc của nó sẽ cung cấp cho nó tất cả bằng chứng cần thiết để tổng hợp chúng; bối cảnh từ điều phối viên không được kế thừa đầy đủ.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-18', 'cca-f', 18, 'An expense-reimbursement agent processes employee requests through a `process_reimbursement` tool. Company policy requires manager approval before funds are disbursed for reimbursements above $500. The agent handles hundreds of requests each day, and the threshold enforcement must be tamper-proof regardless of how the agent is prompted.  
  
Which design ensures that the $500 approval threshold cannot be bypassed?', '[{"key":"A","text":"The process_reimbursement tool accepts amount and details, and internally enforces the threshold: amounts <$500 are auto-disbursed and the tool returns a success confirmation; amounts >$500 cause the tool to create a pending approval request and return a status indicating manager review is pending."},{"key":"B","text":"The process_reimbursement tool accepts an approved_by_manager: boolean parameter. The system prompt instructs the agent to only set this to true after confirming that a manager has approved the request. A nightly audit script reviews all reimbursements where approved_by_manager was set to true."},{"key":"C","text":"Provide two tools: auto_reimburse (hard-coded limit of $500) and request_manager_approval. Include detailed system prompt instructions telling the agent to check the amount and call the appropriate tool. Add a PostToolUse hook that logs which tool was called for auditing."},{"key":"D","text":"Implement the threshold check in a PreToolUse hook that inspects the amount parameter before process_reimbursement executes. If the amount exceeds $500, the hook modifies the tool call to add a requires_approval: true flag, which the tool checks before disbursing."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Một công cụ hoàn trả đáng tin cậy phải tự thực thi quy tắc ủy quyền trước khi giải ngân tiền. Bằng cách chuyển đổi bất kỳ khoản hoàn trả nào trên 500 đô la thành yêu cầu phê duyệt của người quản lý đang chờ xử lý thay vì giải ngân, quy tắc vẫn có hiệu lực ngay cả khi đại lý bị buộc phải đưa ra lệnh gọi công cụ không an toàn. Lời nhắc về mô hình, trường phê duyệt do mô hình cung cấp, hướng dẫn lựa chọn công cụ và nhật ký kiểm tra không cung cấp cùng một ranh giới thực thi. Tài liệu API của OpenAI cũng hướng dẫn người triển khai xác thực các đối số hàm được tạo trong mã ứng dụng trước khi gọi hàm.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-19', 'cca-f', 19, 'Your `post_content` tool needs user confirmation before publishing. The current workflow shows “Ready to post to social media. Confirm?”, and analytics indicate that users approve 98% of requests within 2 seconds. Post-mortems identify incidents in which posts were sent to incorrect accounts, scheduled for incorrect times, or contained errors—all approved by users who did not notice the mistakes. How should the confirmation workflow be redesigned?', '[{"key":"A","text":"Auto-approve routine posts and only require explicit confirmation for unusual patterns like posting to new accounts or large audiences"},{"key":"B","text":"Require users to type a confirmation phrase instead of clicking a button"},{"key":"C","text":"Add a mandatory waiting period before the confirm option becomes available"},{"key":"D","text":"Include the complete post text, target account, scheduled time, and platform in the confirmation request"}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Một xác nhận có ý nghĩa phải trình bày các tham số quan trọng của hành động để người dùng có thể xác minh chúng trước khi phê duyệt: toàn bộ nội dung bài đăng, tài khoản mục tiêu, thời gian đã lên lịch và nền tảng. Điều này làm cho việc xác nhận trở thành một sự xem xét có hiểu biết về hành động không thể đảo ngược hoặc do hậu quả hơn là một sự thừa nhận mang tính phản ánh.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-20', 'cca-f', 20, 'The `update_user_profile` tool accepts a required `user_id` and an optional `fields_to_update` object. During testing, Claude often leaves out `user_id` or supplies improperly structured data. What is most important to help Claude understand which parameter values it should provide?', '[{"key":"A","text":"Strict JSON Schema type constraints marking user_id as required and defining fields_to_update as an object type"},{"key":"B","text":"Verbose parameter names encoding format hints, such as user_id_string_uuid_format"},{"key":"C","text":"Detailed error responses explaining why invalid parameter values were rejected"},{"key":"D","text":"Clear parameter descriptions explaining expected format, such as “user_id: UUID of the user to update (required)”"}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Mô tả tham số chi tiết cung cấp cho Claude bối cảnh ngữ nghĩa cần thiết để cung cấp mã định danh cần thiết và định dạng chính xác. Hướng dẫn sử dụng công cụ của Anthropic xác định các mô tả chi tiết là yếu tố quan trọng nhất đối với hiệu suất của công cụ và đề xuất giải thích ý nghĩa của từng tham số cũng như cách nó ảnh hưởng đến hoạt động của công cụ.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-21', 'cca-f', 21, 'An agent is managing a billing dispute. After calling `get_customer` and `lookup_order`, it determines that the dispute concerns a promotional-pricing error that requires manager approval—beyond the agent’s authorization level. How should the workflow manage this mid-process escalation?', '[{"key":"A","text":"Compile a structured handoff with customer details, order info, and the identified issue before calling escalate_to_human."},{"key":"B","text":"Persist the complete conversation and tool response history to a database, then call escalate_to_human with a reference ID."},{"key":"C","text":"Call escalate_to_human passing only the customer’s original message."},{"key":"D","text":"Attempt the refund with process_refund anyway, escalating only if the system rejects the transaction."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc leo thang ở ranh giới ủy quyền phải cung cấp cho người đánh giá một bản chuyển giao có cấu trúc, hữu ích bao gồm thông tin chi tiết về khách hàng, thông tin đặt hàng và vấn đề đã xác định. Điều này duy trì bối cảnh cần thiết để người quản lý đánh giá và giải quyết ngoại lệ về giá khuyến mãi mà không cần đại lý thực hiện hành động hoàn tiền trái phép.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-22', 'cca-f', 22, 'A web search agent has collected several relevant sources for a research topic. The document analysis agent must now review those sources. How does information usually flow between these two specialized subagents?', '[{"key":"A","text":"The agents communicate through an event-driven message queue, with the document analysis agent subscribing to web search completion events."},{"key":"B","text":"The web search agent directly invokes the document analysis agent, passing the discovered sources as parameters."},{"key":"C","text":"The coordinator agent receives the web search agent’s output and includes relevant findings in the prompt when invoking the document analysis agent."},{"key":"D","text":"Both agents access a shared memory store where the web search agent writes findings and the document analysis agent reads them."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Trong quy trình làm việc đa tác nhân dựa trên điều phối viên, điều phối viên quản lý từng lệnh gọi tác nhân chuyên biệt. Nó lấy kết quả của tác nhân tìm kiếm trên web và đặt các phát hiện có liên quan vào bối cảnh đầu vào của tác nhân phân tích tài liệu để tác nhân có thể kiểm tra chúng.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-23', 'cca-f', 23, 'Users report that final reports occasionally lack depth on particular subtopics. Investigation reveals that the document-analysis agent often identifies gaps—for example, noting, “the retrieved sources discuss API authentication but lack details on token refresh patterns”—but in the current strict pipeline, this insight cannot be acted on because search has already finished. What is the most effective architectural change?', '[{"key":"A","text":"Add a research planning agent before the search phase that decomposes topics into specific sub-questions."},{"key":"B","text":"Have the analysis agent report specific gaps to the coordinator, which triggers targeted searches and re-invokes analysis until sufficient."},{"key":"C","text":"Have the coordinator review analysis output for gap indicators and re-invoke search with gap-informed queries when gaps are detected."},{"key":"D","text":"Have the synthesis agent attach confidence scores to each section and flag areas with insufficient coverage for manual review."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Vòng phản hồi lặp lại cho phép tác nhân phân tích gửi các khoảng trống phạm vi được xác định rõ ràng của mình cho điều phối viên, điều phối viên này có thể khởi chạy các tìm kiếm tiếp theo được nhắm mục tiêu và chạy lại phân tích cho đến khi đạt được độ sâu cần thiết. Điều này chuyển đổi việc phát hiện khoảng trống sau truy xuất thành việc thu thập bằng chứng bổ sung có trọng tâm.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-24', 'cca-f', 24, 'The document analysis agent has one `analyze_documnet` tool that accepts a document and a free-text instruction parameter. During evaluation, requests such as “extract the key financial metrics” frequently produce narrative summaries, whereas “summarize the methodology” occasionally produces raw data tables. The synthesis agent reports that 35% of analysis results need re-requests with clarified instructions. What is the most effective way to improve reliability?', '[{"key":"A","text":"Have the coordinator pre-classify each analysis request before passing instructions to the document analysis agent"},{"key":"B","text":"Keep the single tool but add an analyze_type enum parameter requiring explicit selection between extraction, summarization, and verification modes"},{"key":"C","text":"Enhance the tool description with detailed examples showing how different instruction phrasings should map to different output formats"},{"key":"D","text":"Split the generic tool into purpose-specific tools – extract_data_points, summarize_content, verify_claim_against_source – each with defined input/output contracts"}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các công cụ dành riêng cho mục đích làm cho hoạt động dự định trở nên rõ ràng và cung cấp các hợp đồng đầu vào/đầu ra riêng biệt để trích xuất, tóm tắt và xác minh. Điều này loại bỏ sự mơ hồ vốn có trong việc suy ra các chế độ đầu ra riêng biệt từ các hướng dẫn văn bản tự do và làm cho kết quả xuôi dòng dễ dự đoán hơn.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-25', 'cca-f', 25, 'A customer brings up three distinct issues in one session: a refund inquiry (turns 1–15), a subscription question (turns 16–30), and a payment-method update (turns 31–45). At turn 48, the customer asks, “What happened with my refund?” The conversation is nearing context limits. Which strategy best preserves the agent’s ability to handle all issues during the session?', '[{"key":"A","text":"Extract and persist structured issue data (order IDs, amounts, statuses) into a separate context layer."},{"key":"B","text":"Summarize earlier turns into a narrative description, preserving full message history only for the active issue."},{"key":"C","text":"Rely on MCP tools to re-fetch relevant information on demand when the customer references earlier issues."},{"key":"D","text":"Implement sliding window context that retains the most recent 30 turns."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Một lớp ngữ cảnh có cấu trúc riêng biệt bảo tồn trạng thái chính xác và thông tin quan trọng cho mọi vấn đề, bao gồm ID đơn đặt hàng, số tiền và trạng thái, ngay cả khi lịch sử hội thoại phải được nén hoặc cắt bớt. Điều này cho phép truy xuất chính xác các chi tiết hoàn tiền trước đó khi vấn đề đó được nêu ra lần nữa.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-26', 'cca-f', 26, 'Your conversational assistant often produces several clarifying questions when users submit ambiguous requests. When a user asks, “Can you help me with the report?”, the assistant replies: “I’d be happy to help! Could you tell me: 1) Which report? 2) What kind of help – drafting, reviewing, or formatting? 3) What’s your deadline?”  
  
User analytics indicate a 40% conversation-abandonment rate after these multi-question replies. What is the most effective way to reduce friction while still handling ambiguity appropriately?', '[{"key":"A","text":"Limit the assistant to one clarifying question per turn, using conversation history to accumulate answers over multiple exchanges rather than requesting everything upfront."},{"key":"B","text":"Add a preprocessing step using a smaller model to classify request ambiguity on a 1-5 scale, routing high-ambiguity requests to a clarification dialog and low-ambiguity requests directly to the assistant."},{"key":"C","text":"Modify the system prompt to instruct the assistant to make reasonable assumptions from available context, state those assumptions explicitly, and offer to adjust if the interpretation is wrong."},{"key":"D","text":"Create a lookup table of common request patterns with predefined default interpretations, having the assistant respond with those defaults without stating the assumptions made."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Đối với các yêu cầu không rõ ràng nhưng có mức độ rủi ro thấp, trợ lý phải đưa ra cách diễn giải hợp lý dựa trên ngữ cảnh có sẵn, tiết lộ cách diễn giải đó và đề nghị chỉnh sửa. Điều này cho phép người dùng nhận được trợ giúp ngay lập tức trong khi vẫn duy trì quyền kiểm soát nếu mục đích giả định không chính xác, tránh việc bỏ qua do bảng câu hỏi trả trước gây ra.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-27', 'cca-f', 27, 'After the agent calls `lookup_order` and receives order details indicating that the item was bought 45 days ago, how does the agentic loop decide whether to next call `process_refund` or `escalate_to_human`?', '[{"key":"A","text":"The orchestration layer automatically routes to the next tool based on the order’s status field."},{"key":"B","text":"The order details are added to the conversation and the model reasons about which action to take."},{"key":"C","text":"The agent executes the remaining steps in a tool sequence planned at the start of the request."},{"key":"D","text":"The agent follows a pre-configured decision tree mapping order attributes to specific tool calls."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Đầu ra của công cụ được tích hợp vào bối cảnh mô hình đang diễn ra, cho phép mô hình suy luận về các chi tiết đơn hàng được trả về cũng như các hướng dẫn hoặc biện pháp bảo vệ có thể áp dụng trước khi chọn hành động tiếp theo. Vòng lặp tác nhân tự động chọn các công cụ theo trạng thái hiện tại của quy trình làm việc thay vì yêu cầu một trình tự cố định hoặc cây quyết định được cấu hình sẵn.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-28', 'cca-f', 28, 'Production logs show inconsistent error handling: when `lookup_order` fails, the agent sometimes retries 5+ times (wasteful when the order ID does not exist), sometimes escalates immediately (premature for temporary network issues), and sometimes asks users for clarification (inappropriate when the issue is a backend permission error). Investigation shows that your MCP tool returns uniform error responses: `\{"isError": true, "content": [\{"type": "text", "text": "Operation failed"\}]\}`. The agent cannot differentiate among error types. What is the most effective improvement?', '[{"key":"A","text":"Create an analyze_error MCP tool the agent calls after any failure to determine the error category and recommended action."},{"key":"B","text":"Add few-shot examples to the system prompt demonstrating how to interpret error message patterns and select appropriate responses for each."},{"key":"C","text":"Enhance error responses with structured metadata: include errorCategory (transient/validation/permission), isRetryable boolean, and a description of what caused the failure."},{"key":"D","text":"Implement retry logic with exponential backoff in your MCP server for all errors, returning to the agent only after retries are exhausted."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Lỗi thực thi công cụ MCP sẽ cung cấp phản hồi hữu ích cho mô hình ngôn ngữ. Siêu dữ liệu có cấu trúc xác định danh mục lỗi, liệu nó có thể thử lại hay không và nguyên nhân của nó cho phép xử lý nhất quán: thử lại các lỗi tạm thời, tránh thử lại các lỗi xác thực như ID đơn đặt hàng không tồn tại và các vấn đề về quyền hiển thị thông qua đường dẫn báo cáo thích hợp.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-29', 'cca-f', 29, 'After 30+ turns, your conversational assistant has noticeably slower responses and sometimes produces less coherent outputs. Investigation shows:  
  
1. Average conversations reach 50,000 tokens by turn 35.  
2. Production logs show that 94% of user messages reference only the preceding 3–5 exchanges.  
3. The 6% of queries that reference earlier context generally ask about information the user could easily re-state.  
  
Your goal is to improve response speed and quality while preserving a good user experience. What is the most effective approach?', '[{"key":"A","text":"Enable prompt caching and continue sending the complete conversation history, using cached prefixes to reduce per-request costs while preserving all context."},{"key":"B","text":"Build a retrieval system that stores all conversation turns and uses semantic search to pull in relevant historical context only when the current query appears to reference past information."},{"key":"C","text":"Implement a summarization layer that progressively compresses older conversation turns into a running summary while keeping the most recent 5-6 turns verbatim, maintaining full historical context in condensed form."},{"key":"D","text":"Implement a sliding window keeping only the system prompt and last 8-10 turns. When users reference earlier context, acknowledge the limitation and ask them to re-state the relevant information."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Cửa sổ ngữ cảnh trượt giúp lời nhắc tập trung vào các trao đổi gần đây mà gần như tất cả các yêu cầu thực sự cần, giảm đáng kể độ trễ suy luận và hạn chế bối cảnh lịch sử không liên quan có thể làm giảm tính mạch lạc. Vì các yêu cầu theo ngữ cảnh trước đó không phổ biến liên quan đến các chi tiết mà người dùng có thể dễ dàng lặp lại, nên chỉ yêu cầu thông tin đó khi cần sẽ là sự cân bằng giữa tốc độ và chất lượng tốt hơn so với việc liên tục giữ lại, tóm tắt hoặc truy xuất toàn bộ lịch sử cuộc trò chuyện.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-30', 'cca-f', 30, 'Your order management system needs tools for three distinct operations: issuing refunds (requiring an amount and reason), canceling orders (requiring a reason), and requesting reshipments (requiring a shipping address). Every operation shares an `order_id` parameter but has different additional requirements. During testing, you observe that the agent often omits required parameters or supplies irrelevant ones with the current unified-tool design. Which design change would most effectively improve parameter accuracy?', '[{"key":"A","text":"Keep one unified tool with a nested operation_details object parameter whose internal structure varies by operation type, documented in the tool description."},{"key":"B","text":"Keep one unified tool but add JSON Schema if-then-else conditionals to enforce that parameters like amount are required only when the operation type is “refund”."},{"key":"C","text":"Split into three separate tools (issue_refund, cancel_order, request_reshipment), each defining only the parameters required for that specific operation."},{"key":"D","text":"Keep one unified tool with all parameters marked optional, but add detailed few-shot examples in the system prompt showing correct parameter combinations for each operation type."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các công cụ riêng biệt, dành riêng cho hoạt động cung cấp sơ đồ hẹp cho từng hành động: khoản tiền hoàn lại yêu cầu `order_id`, số tiền và lý do; việc hủy bỏ yêu cầu `order_id` và lý do; việc gửi lại yêu cầu `order_id` và địa chỉ giao hàng. Việc xóa các trường có điều kiện và không liên quan khỏi mỗi định nghĩa công cụ sẽ làm giảm sự mơ hồ và làm cho các tham số bắt buộc trở nên rõ ràng cho thao tác đã chọn.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-31', 'cca-f', 31, 'The synthesis agent finishes its initial pass but identifies that three key research questions are still unanswered because the web-search and document-analysis agents did not locate relevant information on those specific subtopics. The coordinator currently moves directly to report generation, resulting in reports with incomplete coverage. Which change would most effectively improve research completeness?', '[{"key":"A","text":"Have the report generation agent note which research questions couldn’t be answered, so users understand the limitations of the final output."},{"key":"B","text":"Increase the initial breadth of queries sent to web search and document analysis to reduce the probability of missing relevant information."},{"key":"C","text":"Have the coordinator evaluate synthesis output for gaps, then re-delegate to web search and document analysis with targeted queries before invoking synthesis again."},{"key":"D","text":"Give the synthesis agent direct access to web search tools so it can autonomously fill knowledge gaps without returning control to the coordinator."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Tính hoàn chỉnh của nghiên cứu được cải thiện bằng cách sử dụng vòng phản hồi: điều phối viên xem xét kết quả tổng hợp cho những khoảng trống chưa được giải quyết, chỉ định các tìm kiếm tiếp theo được nhắm mục tiêu và phân tích tài liệu cho những khoảng trống đó và chạy lại tổng hợp trước khi tạo báo cáo. Điều này duy trì sự điều phối tập trung trong khi đảm bảo các câu hỏi chưa được trả lời đã được xác định nhận được nghiên cứu tập trung.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-32', 'cca-f', 32, 'Your `get_portfolio_value` tool returns the overall value of a user’s investment portfolio. You are choosing between returning a structured JSON object with explicit fields or returning the information as a formatted text string. What is the main advantage of using structured output with defined fields?', '[{"key":"A","text":"JSON schemas automatically validate that the underlying API returned correct data before the agent processes it."},{"key":"B","text":"Structured JSON consumes significantly fewer tokens than natural language, substantially reducing API costs."},{"key":"C","text":"Structured JSON is processed deterministically by the model, significantly improving accuracy when extracting values."},{"key":"D","text":"The agent can reliably extract specific values without parsing free-form text, reducing errors in subsequent operations."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các trường được xác định sẽ tạo ra một hợp đồng dữ liệu có thể dự đoán được, cho phép tác nhân hoặc mã xuôi dòng truy xuất trực tiếp một giá trị danh mục cụ thể thay vì phân tích cú pháp chuỗi được định dạng tự do. Điều này làm giảm sai sót trích xuất trong các hoạt động sau này. Đầu ra có cấu trúc được thiết kế để làm cho dữ liệu được tạo tuân theo lược đồ được cung cấp, thay vì xác thực tính chính xác thực tế của phản hồi API cơ bản.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-33', 'cca-f', 33, 'A customer says: “I’ve been going back and forth on this return for days. I just want to speak to someone who can actually help me.” The agent has confirmed through `lookup_order` that the return is straightforward—within policy and eligible for immediate processing. What should the agent do?', '[{"key":"A","text":"Process the refund via process_refund to resolve the underlying issue, then inform them it’s complete"},{"key":"B","text":"Acknowledge frustration, inform them this is resolvable now, and offer to complete it or escalate"},{"key":"C","text":"Call escalate_to_human immediately to honor the customer’s request"},{"key":"D","text":"Ask what specifically hasn’t worked in previous attempts before deciding whether to escalate or resolve automatically"}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Khách hàng đã yêu cầu một cách rõ ràng về con người và đại diện đã biết rằng việc trả lại có thể được giải quyết ngay lập tức. Động thái đúng đắn kết hợp sự đồng cảm, minh bạch và kiểm soát khách hàng: thừa nhận sự thất vọng, chia sẻ thông tin mới rằng việc hoàn trả nằm trong chính sách và có thể được hoàn thành ngay bây giờ, đồng thời để khách hàng lựa chọn giữa giải quyết ngay lập tức và leo thang. Việc đơn phương xử lý khoản hoàn trả sẽ thực hiện một hành động mang tính hệ quả mà không có sự đồng ý của khách hàng và bỏ qua yêu cầu đã nêu của họ, đồng thời leo thang ngay lập tức che giấu thực tế là có giải pháp nhanh nhất và thêm một biện pháp xử lý khác - chính sự chậm trễ dẫn đến sự thất vọng. Yêu cầu khách hàng kể lại những gì đã thất bại trong những lần thử trước đó sẽ gây thêm xích mích mà không thay đổi những gì nhân viên nên làm. Việc đưa ra lựa chọn tôn trọng yêu cầu leo ​​thang đồng thời mang lại cho khách hàng con đường nhanh nhất để đạt được điều họ thực sự muốn.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-34', 'cca-f', 34, 'Your product-search tool queries an external catalog API and returns matching items. In production, the agent often retries searches immediately after receiving zero results, treating “no matches found” as a failure that requires a retry. The external API returns HTTP 200 with an empty results array—a valid response. How should you reorganize the tool’s result so the agent correctly interprets empty result sets?', '[{"key":"A","text":"Add a suggestions field containing alternative search strategies when results are empty, helping guide the agent toward more productive follow-up queries."},{"key":"B","text":"Return a natural language string describing the outcome, allowing the agent to interpret the result contextually based on the message content."},{"key":"C","text":"Return a result object with isError: true and a message explaining no products matched."},{"key":"D","text":"Return a structured result with a success boolean and results array, reserving isError: true for actual execution failures only."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Yêu cầu danh mục thành công có thể trả lại hợp lệ các sản phẩm phù hợp no. Phản hồi có cấu trúc chứa boolean thành công và mảng kết quả thể hiện rõ ràng kết quả đó là thành công với dữ liệu trống, trong khi `isError: true` chỉ nên biểu thị các lỗi thực thi công cụ thực tế.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-35', 'cca-f', 35, 'The coordinator gives the web-search subagent detailed, step-by-step directions, including exact search queries, source priorities, and date filters. Production monitoring identifies three problems:  
  
1. When the pre-specified searches fail, the subagent reports “insufficient results” instead of attempting alternatives.  
2. Research quality declines for emerging topics that do not fit expected patterns.  
3. The subagent seldom identifies valuable tangential sources.  
  
What is the most effective way to improve the subagent’s adaptability?', '[{"key":"A","text":"Implement a topic classification step where the coordinator categorizes requests as “well-defined” or “exploratory” and uses different instruction styles for each category."},{"key":"B","text":"Add explicit fallback directives to the detailed instructions: “If specified searches yield fewer than N results, attempt alternative query formulations before reporting failure.”"},{"key":"C","text":"Remove procedural details entirely, delegating with simple goals like “research X thoroughly” and relying on the subagent’s general capabilities."},{"key":"D","text":"Specify research goals and quality criteria (coverage breadth, source diversity, recency) rather than procedural steps, letting the subagent determine its search strategy."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc ủy ​​quyền các mục tiêu nghiên cứu và tiêu chí chất lượng có thể đo lường—chẳng hạn như phạm vi bao phủ, tính đa dạng của nguồn và mức độ gần đây—đặt ra kết quả cần thiết mà không khóa tác nhân phụ vào một quy trình cố định. Do đó, tác nhân phụ có thể định dạng lại các tìm kiếm, điều chỉnh theo các chủ đề không quen thuộc và theo đuổi bằng chứng tiếp tuyến có liên quan trong khi vẫn được đánh giá theo các tiêu chuẩn rõ ràng.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-36', 'cca-f', 36, 'An MCP server provides `archive_file(file_id)` and `delete_file(file_id)` tools. Production logs indicate that the agent invokes `delete_file` when users request to “remove old backups,” yet company policy requires backup files to be archived. Both tools presently have minimal descriptions: “Archives a file” and “Deletes a file.” Which change most directly improves tool selection in this scenario?', '[{"key":"A","text":"Expand tool descriptions to clarify use cases, adding guidance like “Do not use for backup files” to delete_file."},{"key":"B","text":"Add a confirmation step that requires users to type “CONFIRM DELETE” before delete_file executes."},{"key":"C","text":"Implement server-side validation that rejects delete_file calls for files tagged as backups, returning an error message suggesting archive_file."},{"key":"D","text":"Add few-shot examples to the system prompt demonstrating that requests involving “backup” or “old” should use archive_file."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Mô tả công cụ được trình bày cho mô hình dưới dạng hướng dẫn mà con người có thể đọc được và có thể đóng vai trò là gợi ý giúp mô hình nâng cao hiểu biết về từng công cụ có sẵn. Việc tuyên bố rõ ràng rằng không được sử dụng `delete_file` cho các tệp sao lưu sẽ phân biệt các công cụ tại thời điểm lựa chọn, chuyển các yêu cầu liên quan đến sao lưu tới `archive_file`.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-37', 'cca-f', 37, 'A customer says: “This is frustrating. I’ve explained my issue twice and nothing is being resolved. I want to talk to a real person NOW.” The agent has not yet used any tools to investigate the customer’s account. What should the agent do?', '[{"key":"A","text":"Immediately call escalate_to_human with the conversation history."},{"key":"B","text":"Briefly explain what the agent can help with and offer to resolve the issue quickly, escalating only if the customer repeats their request."},{"key":"C","text":"First call get_customer and lookup_order to gather account context, then escalate to a human agent."},{"key":"D","text":"Acknowledge the frustration and ask one targeted question to understand the specific issue before escalating."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Yêu cầu rõ ràng đối với một nhân viên hỗ trợ, đặc biệt là sau nhiều lần cố gắng không được giải quyết và thấy rõ sự thất vọng, cần được chuyển lên cấp cao hơn ngay lập tức. Trì hoãn báo cáo để thu thập ngữ cảnh, giải thích khả năng hoặc đặt một câu hỏi khác là coi thường yêu cầu đã nêu của khách hàng.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-38', 'cca-f', 38, 'Your agent has invoked `lookup_order` several times while investigating a customer’s return requests. Each response contains 40+ fields (items, shipping details, payment info, status history). Tool outputs now make up most of the conversation context. The customer mentions two additional orders they want to discuss. What is the most effective approach before performing more lookups?', '[{"key":"A","text":"Move all tool responses to a vector database with semantic indexing, retrieving relevant portions as the conversation continues"},{"key":"B","text":"Proceed with additional lookups without modifying the existing tool output context"},{"key":"C","text":"Have the model generate a natural language summary of each order’s key details, replacing structured responses with prose descriptions"},{"key":"D","text":"Extract only the return-relevant fields (items, purchase date, return window, status) from each existing order response, removing verbose details"}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc trích xuất các trường có cấu trúc liên quan đến việc trả lại hàng—mặt hàng, ngày mua, thời hạn trả lại hàng và trạng thái—giữ lại dữ liệu thực tế cần thiết để đánh giá việc trả lại hàng trong khi loại bỏ kết quả dài dòng không liên quan khỏi ngữ cảnh của mô hình. Điều này kiểm soát sự phát triển của bối cảnh mà không làm mất đi độ chính xác cần thiết cho nhiệm vụ.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-39', 'cca-f', 39, 'After investigating a billing dispute for more than 25 turns, you have determined that duplicate charges resulted from a payment-gateway timeout that triggered retry logic. The required refund ($847) is above your $500 authorization limit. You need to call `escalate_to_human`, and the human agent will not have access to your conversation transcript. What context should you provide to enable an effective resolution?', '[{"key":"A","text":"A structured summary: customer ID, root cause, refund amount, and recommended action."},{"key":"B","text":"Your diagnosis and the refund amount only."},{"key":"C","text":"The customer’s original complaint verbatim plus the tool result excerpts showing duplicate transactions."},{"key":"D","text":"The complete conversation transcript with all tool results."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Bàn giao leo thang phải cung cấp cho đại lý nhận thông tin cần thiết để xác định khách hàng, hiểu nguyên nhân cốt lõi đã được xác nhận, biết số tiền tài chính liên quan và thực hiện hành động thích hợp tiếp theo. Bản tóm tắt có cấu trúc bao gồm ID khách hàng, nguyên nhân cốt lõi, số tiền hoàn lại $847 và hành động được đề xuất sẽ hoàn chỉnh và hiệu quả khi không có bản ghi.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-40', 'cca-f', 40, 'An agent uses three tools: `get_property_details(property_id)`, which returns data including a street address; `get_price_history(property_id)`, which returns historical pricing; and `get_neighborhood_info(address)`, which returns area statistics.  
  
You observe that `get_neighborhood_info` always requires `get_property_details` to run first solely to extract the address, even when users identify the property by ID. This introduces unnecessary latency and failure coupling—if the first call fails, the neighborhood request fails as well. What tool-design change best resolves this?', '[{"key":"A","text":"Create a lookup_address(property_id) helper tool for retrieving addresses."},{"key":"B","text":"Add retry logic and timeout handling to get_property_details."},{"key":"C","text":"Change get_neighborhood_info to accept property_id, resolving the address internally."},{"key":"D","text":"Consolidate into a single get_property_with_neighborhood(property_id) tool returning both datasets."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }`get_neighborhood_info` phải chấp nhận `property_id` và thực hiện mọi giải pháp địa chỉ cần thiết trong nội bộ. Điều này cho phép người gọi sử dụng mã định danh mà họ đã có, loại bỏ sự phụ thuộc vào công cụ được điều phối bên ngoài không cần thiết và ngăn chặn việc gọi chi tiết địa chỉ không chặn việc tra cứu vùng lân cận.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-41', 'cca-f', 41, 'The `process_refund` tool returns two error categories: transient technical errors (`503 Service Unavailable`, `Connection timeout`) affecting 5% of calls, and permanent business errors (`Order exceeds 30 day return window`, `Item already refunded`) affecting 12% of calls. Monitoring shows that the agent wastes 3–4 turns retrying business errors that can never succeed. At present, both error types return only a plain-text message to Claude.  
  
What is the most effective way to reduce wasted retries while improving the quality of customer-facing responses?', '[{"key":"A","text":"Implement automatic retry logic at the tool level for technical errors only, passing business errors to Claude without retries."},{"key":"B","text":"Add few-shot examples showing how to distinguish retriable from non-retriable errors by parsing error message text."},{"key":"C","text":"Return structured error responses with retriable: false for business errors and a customer-friendly explanation for Claude to use."},{"key":"D","text":"Add a check_refund_eligibility tool that must be called before process_refund to prevent business rule violations."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Phản hồi lỗi có cấu trúc có thể chỉ ra rõ ràng rằng các lỗi trong quy tắc kinh doanh không thể truy xuất được, ngăn chặn các vòng lặp thử lại vô ích. Bao gồm lời giải thích thân thiện với khách hàng cũng mang lại cho đại lý ngôn ngữ phù hợp để truyền đạt kết quả lâu dài cho khách hàng.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-42', 'cca-f', 42, 'The `track_shipment(tracking_id)` tool calls an external logistics API that can occasionally fail—the API may be temporarily unavailable, the tracking ID may be malformed, or the shipment may not exist. The tool currently raises a Python exception when an error occurs. Users report that the agent gives unhelpful replies such as “I’m having trouble with that request,” rather than suggesting alternatives like checking the tracking-number format or looking up the shipment by order number. How should errors in tool results be handled?', '[{"key":"A","text":"Return a generic error response (e.g., {\"success\": false, \"error\": \"lookup_failed\"}) for all failure cases to maintain a consistent schema and avoid exposing internal error details."},{"key":"B","text":"Return structured error information as normal tool output including error type, recoverability status, and actionable context for the user."},{"key":"C","text":"Create dedicated error-recovery tools (retry_tracking_lookup, search_by_order_number) that the model can invoke after the primary tracking tool returns a failure indicator."},{"key":"D","text":"Implement retry logic with exponential backoff inside the tool implementation so transient errors are automatically handled and only return a result after all retry attempts are exhausted."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Đầu ra lỗi có cấu trúc cho phép tác nhân phân biệt lỗi dịch vụ tạm thời với ID theo dõi không hợp lệ và lô hàng bị thiếu, xác định xem có thể khôi phục hay không và cung cấp cho người dùng bước tiếp theo thích hợp. Việc bao gồm danh mục lỗi, chỉ báo khả năng khôi phục và ngữ cảnh có thể thực hiện sẽ lưu giữ thông tin hữu ích mà không cần dựa vào các ngoại lệ như giao diện đối mặt với tác nhân.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-43', 'cca-f', 43, 'The coordinator agent has `AgentDefinitions` configured for each of the four specialized subagents, with suitable descriptions, prompts, and tool restrictions. During testing, the coordinator correctly identifies when delegation is needed—it produces messages such as “I’ll ask the web search agent to find sources on this topic”—but no subagent execution ever takes place. The coordinator then acts as though delegation occurred and continues using incomplete information. Logs show no errors. What is the most likely cause?', '[{"key":"A","text":"The coordinator’s max_tokens setting is too low, causing the Task tool invocation to be truncated before the subagent type parameter can be specified."},{"key":"B","text":"The coordinator’s allowedTools configuration doesn’t include “Task”, so while it can reason about delegation, it cannot invoke the tool required to spawn subagents."},{"key":"C","text":"The AgentDefinitions are configured correctly, but the coordinator’s system prompt doesn’t explicitly list the available subagent types, preventing the model from knowing they can be invoked."},{"key":"D","text":"Subagent context isolation means task descriptions from the coordinator don’t automatically reach subagents; you need to configure explicit context forwarding in ClaudeAgentOptions."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }`AgentDefinitions` cung cấp các loại tác nhân phụ để định cấu hình nhưng việc ủy ​​quyền yêu cầu điều phối viên gọi công cụ `Task`. Khi `Task` không được bao gồm trong cấu hình công cụ được phép của điều phối viên, nó không thể gửi công việc đến tác nhân phụ ngay cả khi lý do của nó xác định rằng việc ủy ​​quyền là phù hợp. Quyền của công cụ kiểm soát liệu một công cụ được định cấu hình có thể được gọi hay không.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-44', 'cca-f', 44, 'While implementing the `lookup_order` MCP tool, the backend occasionally returns errors (for example, “Order not found” or temporary database failures). What is the correct pattern for communicating these errors to the agent?', '[{"key":"A","text":"Throw an exception from the tool handler so the agent framework can catch and log it"},{"key":"B","text":"Return the error message in the tool result content with the isError flag set to true"},{"key":"C","text":"Log the error server-side and return an empty result to avoid confusing the model"},{"key":"D","text":"Return a success response with a “status” field indicating the error type"}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các lỗi thực thi công cụ MCP, bao gồm lỗi API và lỗi logic nghiệp vụ chẳng hạn như thiếu đơn hàng, phải được trả về trong `content` của kết quả công cụ với `isError: true`. Điều này hiển thị phản hồi có thể thực hiện được cho tổng đài viên để họ có thể phản hồi phù hợp hoặc thử lại.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-45', 'cca-f', 45, 'Compliance requires that refunds exceeding $500 automatically escalate to a human agent; this rule cannot be left to model discretion. Despite clear system-prompt instructions, production logs show that the agent occasionally processes high-value refunds directly, with a 3% failure rate. How can guaranteed compliance be achieved?', '[{"key":"A","text":"Modify the refund tool to return an error with message “Amount exceeds policy limit – please escalate” when threshold is exceeded."},{"key":"B","text":"Add few-shot examples to the prompt showing correct escalation behavior at various refund amounts ($400, $500, $600)."},{"key":"C","text":"Implement a hook to intercept tool calls; when the refund process amount exceeds $500, block it and invoke human escalation."},{"key":"D","text":"Strengthen the system prompt with emphatic language: “CRITICAL POLICY: Refunds over $500 MUST trigger human escalation. NEVER process these directly.”"}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Một hook trước khi thực thi mang tính xác định sẽ thực thi chính sách ngoài phạm vi quyền quyết định của mô hình: nó có thể kiểm tra số tiền hoàn lại được yêu cầu, chặn bất kỳ số tiền nào trên 500 USD và gọi đường dẫn báo cáo con người bắt buộc. Từ ngữ và ví dụ nhanh chóng không thể đảm bảo vì hành vi của mô hình không phải là ranh giới ủy quyền cứng.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-46', 'cca-f', 46, 'An MCP server implements a `check_availability` tool that queries an external calendar API. During testing, three error conditions occur:  
  
1. The tool is invoked with a malformed request that lacks the required `user_email` parameter.  
2. The calendar API returns a 404 because the specified user does not exist in the calendar system.  
3. The calendar API returns a 503 because the service is temporarily unavailable.  
  
How should each error be reported under MCP’s error-handling design?', '[{"key":"A","text":"Report all three as tool results with isError: true."},{"key":"B","text":"Report errors 1 and 2 as JSON-RPC protocol errors; report error 3 as a tool result with isError: true."},{"key":"C","text":"Report error 1 as a JSON-RPC protocol error; report errors 2 and 3 as tool results with isError: true."},{"key":"D","text":"Report all three as JSON-RPC protocol errors."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Theo đặc tả MCP hiện tại, các lỗi giao thức JSON-RPC được dành riêng cho các vấn đề với chính yêu cầu ở cấp giao thức: các công cụ không xác định, các yêu cầu không thực hiện được lược đồ CallToolRequest và lỗi máy chủ. Mọi vấn đề xảy ra khi xử lý một công cụ/lệnh gọi đúng định dạng đều là lỗi thực thi công cụ được trả về trong kết quả với `isError: true`. Điều đó rõ ràng bao gồm các lỗi xác thực đầu vào, chẳng hạn như thiếu đối số bắt buộc đối với inputSchema của công cụ và các lỗi API, chẳng hạn như 404 đối với người dùng không xác định hoặc 503 từ dịch vụ không khả dụng. Việc trả về cả ba dưới dạng kết quả công cụ cho phép mô hình đọc thông báo và tự sửa, chẳng hạn như bằng cách cung cấp user_email hoặc thử lại sau.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-47', 'cca-f', 47, 'Your team''s CLAUDE.md includes a rule: "Use 4-space indentation and always run Prettier formatting." Despite this, code reviews reveal that roughly 30% of files Claude Code generates use inconsistent formatting — sometimes 2-space indentation, sometimes missing trailing commas.  
  
Adding emphasis ("IMPORTANT: You MUST use Prettier formatting") reduces violations to about 15%, but doesn''t eliminate them.  
  
What is the most effective way to ensure all generated code is consistently formatted?', '[{"key":"A","text":"Configure a PostToolUse hook with an Edit|Write matcher that automatically runs Prettier on each file Claude modifies."},{"key":"B","text":"Split the formatting rules into path-scoped .claude/rules/files that load when Claude works on matching file types."},{"key":"C","text":"Extract the formatting rules into a dedicated skill that Claude loads automatically when generating code, with more detailed examples of correct formatting."},{"key":"D","text":"Add a Stop hook with a prompt-based check that evaluates whether generated code follows formatting standards and prompts Claude to fix violations."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Một hook PostToolUse được định cấu hình bằng trình so khớp Edit|Write chạy tự động và xác định sau khi Claude ghi hoặc chỉnh sửa bất kỳ tệp nào, gọi trực tiếp một trình định dạng như Prettier trên đường dẫn tệp thông qua lệnh shell. Bởi vì việc thực thi này diễn ra bên ngoài quá trình tạo mô hình ngôn ngữ nên nó đảm bảo định dạng nhất quán 100% bất kể mô hình tạo ra gì, không giống như các hướng dẫn dựa trên lời nhắc (quy tắc CLAUDE.md, nhấn mạnh, tệp quy tắc hoặc kỹ năng) chỉ ảnh hưởng đến việc tạo một cách xác suất và vẫn có thể bị bỏ qua. Móc dừng có kiểm tra dựa trên lời nhắc cũng không đáng tin cậy vì nó vẫn phụ thuộc vào bước đánh giá và hiệu chỉnh LLM thay vì gọi công cụ xác định.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-48', 'cca-f', 48, 'You are building developer productivity tools using the Claude Agent SDK. The agent helps engineers explore unfamiliar codebases, understand legacy systems, generate boilerplate code, and automate repetitive tasks. It relies on the built-in tools (Read, Write, Bash, Grep, Glob) and integrates with Model Context Protocol (MCP) servers.  
  
Your code review assistant must analyze pull requests and provide feedback on three aspects:  
  
- Code style compliance  
- Potential security issues  
- Documentation completeness  
  
Each aspect requires reading files, running analysis tools, and generating a report section. The review process follows this same three-step workflow for every PR.  
  
Which task decomposition pattern is most appropriate for this workflow?', '[{"key":"A","text":"Routing – classify each PR by type (feature, bugfix, refactor) first, then route to different review prompts optimized for that category."},{"key":"B","text":"Prompt chaining – break the review into sequential steps where each aspect (style, security, documentation) is analyzed separately, with outputs combined in a final synthesis step."},{"key":"C","text":"Single comprehensive prompt – include all instructions in one prompt and let the model handle all three aspects simultaneously."},{"key":"D","text":"Orchestrator-workers – have a central LLM analyze each PR to dynamically determine which checks are needed, then delegate to specialized worker LLMs for each identified subtask."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Quy trình làm việc này luôn thực hiện ba khía cạnh đánh giá giống nhau theo cùng một thứ tự cố định cho mọi yêu cầu kéo, với quá trình phân tích của từng khía cạnh (đọc tệp, chạy công cụ, tạo một phần) tiến hành độc lập trước khi kết quả được hợp nhất vào báo cáo cuối cùng. Đây là đặc điểm xác định của mẫu chuỗi nhắc nhở: phân tách một nhiệm vụ thành một chuỗi các bước gọi LLM cố định (tùy chọn có kiểm tra theo chương trình giữa chúng) khi nhiệm vụ phân tách rõ ràng thành các nhiệm vụ phụ ổn định, có thể dự đoán được. Bởi vì các nhiệm vụ phụ ở đây (kiểu, bảo mật, tài liệu) đều được biết trước và nhất quán trong mọi PR, nên no cần có sự ủy quyền năng động, dựa trên đầu vào — đây là điểm phân biệt người điều phối-nhân viên, trong đó LLM trung tâm phải tự động xác định các nhiệm vụ phụ không thể đoán trước trên mỗi đầu vào. Chuỗi nhắc nhở cũng cho phép xác thực đầu ra của từng bước phân tích và sau đó kết hợp trong bước tổng hợp cuối cùng, khớp với quy trình làm việc được mô tả của các phần riêng biệt mà cuối cùng được hợp nhất thành báo cáo đánh giá.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-49', 'cca-f', 49, 'A critical bug is affecting production users. The error logs show exceptions occurring in the OrderProcessing module, with a clear stack trace pointing to a specific function. You have not previously worked with this module. What is the most effective approach to take?', '[{"key":"A","text":"Start with direct execution to gather initial information, then switch to plan mode to design a comprehensive solution before implementing any changes."},{"key":"B","text":"Enter plan mode to explore the module’s architecture and dependencies before attempting any fixes."},{"key":"C","text":"Use plan mode to analyze the error in context of the module’s design, enumerate potential root causes, and prioritize fixes systematically."},{"key":"D","text":"Use direct execution to examine the stack trace, read the relevant code, and implement a fix once you identify the root cause."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Khi xử lý lỗi nghiêm trọng trong quá trình sản xuất trong một mô-đun không quen thuộc, chiến lược hiệu quả nhất là sử dụng chế độ lập kế hoạch để giải thích lỗi trong bối cảnh thiết kế của mô-đun, xác định và liệt kê nhiều nguyên nhân gốc rễ tiềm ẩn, sau đó ưu tiên các biện pháp khắc phục cần theo đuổi một cách có hệ thống. Điều này tránh việc khắc phục sớm ở cấp độ triệu chứng mà phương pháp thực thi trực tiếp có thể tạo ra khi kỹ sư chưa quen với kiến ​​trúc rộng hơn, các phần phụ thuộc và các trường hợp biên của mô-đun — giảm nguy cơ khắc phục không đầy đủ hoặc không chính xác trong sự cố sản xuất có nguy cơ cao.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-50', 'cca-f', 50, 'Your team is configuring MCP servers in Claude Code. You want to add a shared venue lookup server that all team members should have access to, and you personally want to add an experimental music playlist server that only you are testing.  
  
Which configuration approach correctly applies MCP server scopes?', '[{"key":"A","text":"Add both servers to your local ~/.claude.json"},{"key":"B","text":"Add venue server to ~/.claude.json and playlist server to .mcp.json"},{"key":"C","text":"Add venue server to .mcp.json and playlist server to ~/.claude.json."},{"key":"D","text":"Add both servers to the project-level .mcp.json file"}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Phạm vi dự án của Claude Code lưu trữ các định nghĩa máy chủ MCP trong tệp.mcp.json nhằm kiểm tra phiên bản và chia sẻ với toàn bộ nhóm, biến nó thành vị trí chính xác cho máy chủ mà mọi người đều có thể sử dụng, chẳng hạn như máy chủ tra cứu địa điểm dùng chung. Ngược lại, các máy chủ cục bộ/trong phạm vi người dùng được lưu trữ trong tệp ~/.claude.json của cá nhân và vẫn ở chế độ riêng tư đối với người dùng đó trong các dự án của riêng họ. Đây là nơi thích hợp cho máy chủ cá nhân, thử nghiệm như máy chủ danh sách phát nhạc mà chỉ một người đang thử nghiệm và không được chuyển cho đồng đội thông qua cấu hình dự án chung.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-51', 'cca-f', 51, 'You are building developer productivity tools using the Claude Agent SDK. The agent assists engineers with exploring unfamiliar codebases, understanding legacy systems, generating boilerplate code, and automating repetitive tasks. It relies on the built-in tools (Read, Write, Bash, Grep, Glob) and integrates with Model Context Protocol (MCP) servers.  
  
An engineer submits two requests:  
  
- Request A: "Rename the `getUserData` function to `fetchUserProfile` everywhere it''s used."  
- Request B: "Improve error handling throughout the data processing module — add try/catch blocks, meaningful error messages, and ensure failures don''t silently corrupt data."  
  
For which request does specifying an explicit multi-phase workflow (such as analyze → propose → implement with review) most improve the quality of the outcome?', '[{"key":"A","text":"Neither request benefits significantly"},{"key":"B","text":"Request A, the function rename task"},{"key":"C","text":"Both requests benefit equally"},{"key":"D","text":"Request B, the error handling task"}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Tác vụ đổi tên mang tính cơ học và có kết quả có thể xác minh rõ ràng: tìm mọi cách sử dụng ký hiệu và cập nhật nó một cách nhất quán, công cụ tìm kiếm tích hợp sẵn (Grep/Glob) xử lý tốt mà không cần quy trình phức tạp theo giai đoạn. Ngược lại, việc cải thiện việc xử lý lỗi trên một mô-đun đòi hỏi nhiều phán đoán và có phạm vi rộng — nó yêu cầu phân tích các điểm lỗi và luồng dữ liệu hiện có, quyết định lỗi nào quan trọng, điều gì cấu thành thông báo ''có ý nghĩa'' và cách tránh âm thầm làm hỏng dữ liệu, sau đó đề xuất chiến lược đó trước khi áp dụng các chỉnh sửa trên diện rộng. Quy trình phân tích rõ ràng → đề xuất → triển khai cùng với đánh giá sẽ đưa ra kế hoạch và giả định của tác nhân để con người xác thực trước khi thực hiện các thay đổi mã rộng, giảm nguy cơ xử lý ngoại lệ không nhất quán hoặc quá rộng và đảm bảo các bản sửa lỗi thực sự giải quyết được các chế độ lỗi thực sự của mô-đun. Đây là lý do tại sao quy trình làm việc nhiều giai đoạn rõ ràng mang lại sự cải thiện chất lượng lớn nhất cho yêu cầu xử lý lỗi thay vì đổi tên đơn giản.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-52', 'cca-f', 52, 'You are building developer productivity tools with the Claude Agent SDK. The agent helps engineers explore unfamiliar codebases, understand legacy systems, generate boilerplate code, and automate repetitive tasks. It relies on the built-in tools (Read, Write, Bash, Grep, Glob) and integrates with Model Context Protocol (MCP) servers.  
  
Yesterday, an engineer used the agent to analyze a legacy authentication module and identified two distinct refactoring approaches:  
  
- Extracting a microservice  
- Refactoring in-place  
  
Today, the engineer wants to explore both approaches in depth — having the agent propose specific code changes for each — before deciding which one to implement.  
  
What is the most effective way to structure this exploration?', '[{"key":"A","text":"Start two fresh sessions, manually providing a summary of yesterday’s analysis findings to establish context."},{"key":"B","text":"Resume yesterday’s session and explore both approaches sequentially within the same conversation thread."},{"key":"C","text":"Resume yesterday’s session to explore the first approach, then start a new session for the second, manually recreating the original context."},{"key":"D","text":"Use fork_session to create two branches from yesterday’s analysis, exploring one approach in each fork."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }SDK tác nhân Claude cung cấp khả năng fork_session, kết hợp với việc tiếp tục phiên trước đó, tạo ra các nhánh phiên độc lập mới kế thừa toàn bộ bản ghi/ngữ cảnh của phiên ban đầu cho đến điểm tiếp tục, trong khi vẫn giữ nguyên phiên ban đầu. Điều này cho phép kỹ sư duy trì phân tích mô-đun xác thực của ngày hôm qua dưới dạng ngữ cảnh được chia sẻ, sau đó khám phá phương pháp trích xuất vi dịch vụ và phương pháp tái cấu trúc tại chỗ trong hai nhánh phân nhánh độc lập, riêng biệt — tránh lây nhiễm chéo giữa hai dữ liệu khám phá (không giống như tiếp tục tuần tự trong một chuỗi) và tránh tình trạng thiếu hiệu quả và mất độ trung thực khi thiết lập lại bối cảnh theo cách thủ công trong các phiên mới.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-53', 'cca-f', 53, 'Your team frequently migrates React components to Vue, and you have written a step-by-step workflow for Claude Code to follow during each migration. You want every developer on the team to be able to invoke this workflow by typing `/migrate-component`, and you want the workflow to stay in sync as the team continues to iterate on it.  
  
Where should you place the skill file?', '[{"key":"A","text":"In ~/.claude/skills/migrate-component/SKILL.md on each developer’s machine"},{"key":"B","text":"In .claude/skills/migrate-component/SKILL.md at the project root, committed to version control"},{"key":"C","text":"In the project’s.claude/settings.json using a skillOverrides entry to register and define the workflow"},{"key":"D","text":"As a detailed instruction block in the project’s root CLAUDE.md file"}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các kỹ năng Claude Code được xác định trong tệp `SKILL.md` bên trong thư mục được đặt tên theo kỹ năng và tên thư mục của kỹ năng trở thành tên lệnh gạch chéo của nó (ví dụ: một kỹ năng trong `migrate-component/SKILL.md` được gọi bằng `/migrate-component`). Việc đặt kỹ năng trong thư mục `.claude/skills/` của dự án ở thư mục gốc của dự án và đưa nó vào kiểm soát phiên bản sẽ đảm bảo rằng kỹ năng đó là kỹ năng cấp dự án (không phải cá nhân): mọi nhà phát triển sao chép hoặc kéo kho lưu trữ sẽ tự động nhận được kỹ năng tương tự và mọi cập nhật do đồng đội thực hiện đều được chọn vào lần tiếp theo họ kéo, giữ cho quy trình làm việc được đồng bộ hóa trong toàn nhóm. Các kỹ năng cá nhân trong `~/.claude/skills/` là cục bộ trên máy của một nhà phát triển và không được chia sẻ, `settings.json` không hỗ trợ xác định các kỹ năng thông qua trường `skillOverrides` và CLAUDE.md nhằm mục đích hướng dẫn dự án theo ngữ cảnh liên tục thay vì để xác định quy trình làm việc lệnh gạch chéo không thể viện dẫn.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-54', 'cca-f', 54, 'You are building developer productivity tools with the Claude Agent SDK. The agent assists engineers in exploring unfamiliar codebases, understanding legacy systems, generating boilerplate code, and automating repetitive tasks. It relies on the built-in tools (Read, Write, Bash, Grep, Glob) and integrates with Model Context Protocol (MCP) servers.  
  
Suppose your agent has already analyzed a complex service module by:  
  
- Reading 23 source files  
- Tracing request flows  
- Identifying error handling patterns  
  
A developer now wants to compare two different testing strategies before committing to one:  
  
1. End-to-end tests with mocked external services  
2. Snapshot tests capturing expected outputs  
  
They need to develop both approaches independently so they can evaluate the trade-offs between them.  
  
How should you manage the sessions in this case?', '[{"key":"A","text":"Start two fresh sessions, having each re-read the relevant source files before beginning."},{"key":"B","text":"Resume the analysis session with fork_session enabled, creating a separate branch for each testing strategy."},{"key":"C","text":"Export the analysis session''s key findings to a file, then create two new sessions that reference this file."},{"key":"D","text":"Continue in the original session, developing end-to-end tests first, then snapshot tests sequentially."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc phân tách phiên trong SDK tác nhân Claude (sử dụng sơ yếu lý lịch với fork_session=True hoặc trình trợ giúp fork_session()) sẽ tạo một phiên mới bắt đầu với lịch sử thông báo đầy đủ của phiên phân tích gốc nhưng sau đó sẽ phân tách độc lập từ thời điểm đó trở đi. Điều này cho phép bạn duy trì và sử dụng lại quá trình điều tra trả trước tốn kém (đọc 23 tệp, theo dõi luồng, xác định mẫu lỗi) trong khi tạo hai nhánh riêng biệt — một nhánh cho mỗi chiến lược thử nghiệm — để nhà phát triển có thể đánh giá song song cả hai phương pháp tiếp cận mà không cần khám phá hoặc quyết định của nhánh nào ảnh hưởng đến nhánh kia cũng như không cần chạy lại bản phân tích hoặc thiết lập lại bối cảnh theo cách thủ công thông qua các ghi chú đã xuất.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-55', 'cca-f', 55, '$38', '[{"key":"A","text":"Enable the tool search tool with defer_loading on the six new tools, keeping the original four always loaded, so the agent dynamically discovers specialized tools only when needed."},{"key":"B","text":"Split the tools across two sub-agents – a “financial resolution” agent with process_refund , issue_credit ,and apply_promo_code , and a “delivery operations” agent with the remaining delivery tools – with a coordinator routing between them."},{"key":"C","text":"Add few-shot examples to the system prompt demonstrating correct selection for each ambiguous tool pair, such as showing when issue_credit applies versus when process_refund is appropriate."},{"key":"D","text":"Consolidate semantically overlapping tools – merge issue_credit and process_refund into a single resolve_compensation tool with an action parameter, and fold check_delivery_status into lookup_order with an optional include_tracking flag."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Lỗi xuất phát từ việc có nhiều công cụ riêng biệt có thể xử lý cùng một hành động cơ bản một cách hợp lý, buộc tác nhân phải đoán giữa chúng. Việc bật tải công cụ trì hoãn, phân tách công cụ trên các tác nhân phụ hoặc thêm các ví dụ few-shot đều giải quyết được sự mơ hồ này mà không xóa nó - các công cụ chồng chéo vẫn tồn tại dưới dạng các tùy chọn cạnh tranh, riêng biệt bất cứ khi nào chúng hiển thị với mô hình. Việc hợp nhất issue_credit và process_refund vào một công cụ Resolve_compensation duy nhất (với một tham số hành động) và gộp check_delivery_status vào lookup_order (thông qua cờ include_tracking) sẽ loại bỏ hoàn toàn các định nghĩa công cụ dư thừa, do đó, no có nhiều lựa chọn hơn để thực hiện giữa hai công cụ tương tự — tác nhân chọn một công cụ và thể hiện ý định thông qua các tham số. Điều này trực tiếp đề cập đến phương pháp thực hành tốt nhất được ghi lại cho thiết kế công cụ tác nhân nhằm hợp nhất chức năng chồng chéo nhằm giảm sự mơ hồ trong lựa chọn công cụ, thay vì bù đắp cho điều đó thông qua định tuyến, kiểm soát khả năng hiển thị hoặc nhắc nhở.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-56', 'cca-f', 56, 'While testing an agent, you notice that when a customer states, "I need a refund for my recent purchase," the agent immediately invokes process_refund — but supplies the required order_id parameter with a plausible-looking value that it made up, rather than first calling lookup_order to retrieve the actual order ID. As a result, the refund call fails because the invented order ID does not correspond to any real order.  
  
Which change would directly address the root cause of the agent inventing the order_id value?', '[{"key":"A","text":"Switch tool_choice from “auto” to “any” to force the agent to make a tool call on every turn."},{"key":"B","text":"Update the process_refund tool description to explicitly state that order_id must be obtained from a prior lookup_order call and must never be assumed or invented."},{"key":"C","text":"Pre-parse incoming customer messages to extract any order IDs mentioned, and inject them into the conversation context before passing to Claude."},{"key":"D","text":"Add server-side validation that checks whether the order_id exists in your database before executing the refund, returning an error to the agent if not found."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Theo hướng dẫn chính thức của Anthropic về việc xác định công cụ cho Claude, mô tả công cụ là cơ chế chính để mô hình tìm hiểu chức năng của công cụ, thời điểm sử dụng và cách điền từng tham số — bao gồm mọi phần phụ thuộc vào các công cụ khác. Nếu mô tả của công cụ process_refund không nêu rõ rằng order_id phải được truy xuất thông qua lệnh gọi lookup_order trước đó và không bao giờ được giả định, đoán hoặc bịa đặt, thì mô hình có cơ sở no để tránh điền tham số bắt buộc bằng một giá trị được phát minh. Việc cập nhật mô tả để nêu rõ ràng buộc rõ ràng này trực tiếp nhắm vào quá trình suy luận dẫn đến việc bịa đặt, trong khi buộc tool use ở mọi lượt, trích xuất trước ID từ văn bản người dùng hoặc xác thực phía máy chủ ID không giải quyết được lý do tại sao mô hình phát minh ra giá trị ngay từ đầu hoặc chỉ phát hiện được sự cố sau khi sự cố đã xảy ra.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-57', 'cca-f', 57, 'Anthropic''s tool use documentation advises: "Write instructive error messages. Instead of generic errors like ''failed'', include what went wrong and what Claude should try next."  
  
A billing dispute agent uses a `lookup_order` tool that catches all exceptions and always returns a tool result with `is_error: true` and the message "Tool execution failed". Monitoring reveals two distinct failure patterns:  
  
- The agent repeatedly retries the identical call until it hits the turn limit.  
- The agent immediately calls `escalate_to_human` without attempting any alternative tool.  
  
Which change follows the documented recommendation and gives Claude the information it needs to choose the correct recovery action for each type of error?', '[{"key":"A","text":"Implement retry logic with exponential backoff inside each tool implementation so transient errors are resolved transparently within the tool before any failure result is surfaced to Claude in the agentic loop."},{"key":"B","text":"Add an error classification step in the agentic loop that intercepts tool errors before Claude sees them, tags each as “retry,” “try_alternative,” or “escalate,” and appends that recommendation to the tool result."},{"key":"C","text":"Remove is_error: true and return the error details as normal tool content, so Claude reasons about the response as data rather than treating it as a flagged failure condition that biases retry behavior."},{"key":"D","text":"Return error-type-specific messages with is_error: true, e.g., “Order not found-try get_customer to search by phone” for data errors and “Database timeout (transient)-retry should succeed” for infrastructure errors."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Tài liệu của Anthropic về cách xử lý lỗi công cụ hướng dẫn cụ thể các nhà phát triển viết các thông báo lỗi mang tính hướng dẫn, khác biệt thay vì các thông báo lỗi chung chung vì Claude hoàn toàn dựa vào văn bản trong nội dung tool_result để quyết định cách khôi phục — no có thông tin chi tiết khác về lý do cuộc gọi không thành công. Một chuỗi chung duy nhất như "Thực thi công cụ không thành công" thu gọn các danh mục lỗi riêng biệt (thứ tự không tồn tại so với thời gian chờ cơ sở dữ liệu tạm thời) thành một tín hiệu không thể phân biệt được, do đó, Claude thử lại một thao tác không bao giờ có thể thành công (lỗi không tìm thấy dữ liệu) hoặc từ bỏ và báo cáo lỗi tạm thời mà lẽ ra việc thử lại có thể giải quyết được. Bằng cách trả về các thông báo dành riêng cho loại lỗi, vừa giải thích sự cố vừa nêu những gì cần thử tiếp theo (ví dụ: trỏ tới `get_customer` để biết lỗi không tìm thấy hoặc chỉ ra rằng thời gian chờ là nhất thời và đáng để thử lại), trong khi vẫn đặt `is_error: true` để Claude nhận ra chính xác kết quả là điều kiện lỗi, công cụ này sẽ cung cấp cho Claude chính xác bối cảnh có thể hành động mà tài liệu yêu cầu, cho phép nó chọn thử lại, try-an-alternative-tool hoặc chuyển lên cấp cao hơn cho phù hợp với từng loại lỗi.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-58', 'cca-f', 58, 'A customer reaches out about a warranty claim on a power drill. Resolving the request requires multiple sequential tool calls: `get_customer` to look up their account, `lookup_order` to find the purchase details, and then either `process_refund` or `escalate_to_human` depending on warranty eligibility.  
  
You are implementing the agentic loop that orchestrates these steps using the Claude API. What is the primary mechanism your application uses to determine whether to continue the loop or stop?', '[{"key":"A","text":"You manually set the tool_choice parameter to “none” after the final expected tool call to force Claude to stop requesting tools."},{"key":"B","text":"You check whether Claude''s response contains a text content block – if text is present, the agent has produced its final answer and the loop should exit."},{"key":"C","text":"You track the number of tool calls made and exit the loop once a preconfigured maximum is reached."},{"key":"D","text":"You check the stop_reason field in each API response – the loop continues while it equals “tool_use” and exits when it changes to “end_turn” or another terminal value."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Trong mẫu sử dụng công cụ (vòng lặp tác nhân) của API Claude, mỗi phản hồi API bao gồm trường `stop_reason` cho biết lý do mô hình ngừng tạo. Khi Claude muốn gọi một công cụ, phản hồi có `stop_reason: "tool_use"`. Ứng dụng điều phối phải kiểm tra trường này sau mỗi lệnh gọi API: miễn là `stop_reason` là `"tool_use"`, nó sẽ thực thi (các) công cụ được yêu cầu, gửi lại kết quả của công cụ dưới dạng thông báo người dùng mới và gọi lại API. Khi `stop_reason` thay đổi thành `"end_turn"` (hoặc một giá trị đầu cuối khác như `"max_tokens"` hoặc `"stop_sequence"`), Claude đã kết thúc lượt của mình và thoát khỏi vòng lặp. Việc kiểm tra sự hiện diện của khối văn bản là không đáng tin cậy vì Claude có thể phát ra văn bản cùng với khối tool_use trong cùng một phản hồi (ví dụ: giải thích hành động tiếp theo của nó) mà không có nghĩa là nó đã hoàn thành. Đặt `tool_choice` thành "không" là một cách để ngăn các cuộc gọi công cụ theo một yêu cầu cụ thể, không phải là tín hiệu dừng động và việc theo dõi số lượng cuộc gọi tối đa chỉ là giới hạn an toàn chứ không phải cơ chế điều khiển chính.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-59', 'cca-f', 59, 'You are building developer productivity tools with the Claude Agent SDK. The agent helps engineers explore unfamiliar codebases, understand legacy systems, generate boilerplate code, and automate repetitive tasks. It relies on the built-in tools (Read, Write, Bash, Grep, Glob) and also integrates with Model Context Protocol (MCP) servers.  
  
During testing, you notice that in extended exploration sessions lasting 30 or more minutes, the agent begins giving inconsistent answers about code structure it already discussed earlier. Engineers report having to re-explain context about modules they have already had the agent explore.  
  
What is the most effective approach to address this issue?', '[{"key":"A","text":"Implement automatic context clearing every 15 minutes to ensure the agent starts with fresh, uncontaminated context."},{"key":"B","text":"Switch to a higher-capacity model tier to provide more context window space for accumulated exploration data."},{"key":"C","text":"Create summaries of all source files before exploration begins, loading only these compressed representations into context."},{"key":"D","text":"Have the agent maintain a scratchpad file that records key findings, referencing it for subsequent questions."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Mẫu được đề xuất cho các tác nhân mã hóa chạy trong thời gian dài là đưa các phát hiện chính vào một tệp cố định (bảng ghi chép, tệp ghi chú hoặc kho lưu trữ được hỗ trợ bởi công cụ bộ nhớ) thay vì chỉ dựa vào lịch sử hội thoại trong ngữ cảnh ngày càng tăng. Khi tác nhân khám phá các mô-đun, nó ghi lại những gì đã học được—vị trí tệp, mối quan hệ mô-đun, quyết định kiến ​​trúc—vào tệp này và đọc lại tệp đó trước khi trả lời các câu hỏi tiếp theo. Điều này giúp các câu trả lời nhất quán trong một phiên dài và cho phép tác nhân khôi phục trạng thái chính xác ngay cả khi ngữ cảnh thô bị cắt bớt hoặc nén mà không cần phải khám phá lại cơ sở mã. Việc tích cực xóa bối cảnh theo lịch trình cố định (cứ sau 15 phút) sẽ loại bỏ sự hiểu biết tích lũy và tái tạo trực tiếp triệu chứng được báo cáo là các kỹ sư phải giải thích lại các mô-đun đã được khám phá. Việc chỉ nâng cấp lên mô hình ngữ cảnh lớn hơn sẽ gây chậm trễ nhưng không giải quyết được vấn đề cơ bản là thông tin không được theo dõi lâu dài và không đảm bảo tính nhất quán. Việc tóm tắt trước mọi tệp nguồn trước khi bắt đầu khám phá là không thực tế để khám phá các cơ sở mã lạ hoặc cũ mà mức độ liên quan không được biết trước và nó sẽ loại bỏ chi tiết mà tác nhân sẽ tự động thu thập trong quá trình khám phá. Mẫu sổ ghi chú/ghi chú này được Anthropic ghi lại dưới dạng ''ghi chú có cấu trúc'' và được chính thức hóa thông qua công cụ bộ nhớ, hỗ trợ rõ ràng việc xây dựng kiến ​​thức dự án theo thời gian và duy trì trạng thái trong suốt phiên mà không giữ mọi thứ trong cửa sổ ngữ cảnh đang hoạt động.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-60', 'cca-f', 60, 'You need to add a date validation check to ensure that event dates fall in the future. This change requires adding a conditional statement to one existing function within a single file. What is the most appropriate approach to make this change?', '[{"key":"A","text":"Enter plan mode first to create a detailed implementation strategy before making the change."},{"key":"B","text":"Enter plan mode to analyze how the validation might impact other parts of the reservation flow."},{"key":"C","text":"Use direct execution to make the change."},{"key":"D","text":"Start with extended thinking mode enabled to ensure thorough reasoning about the validation logic."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Chế độ kế hoạch của Claude Code được thiết kế cho các nhiệm vụ lớn hơn hoặc mơ hồ hơn — những nhiệm vụ liên quan đến nhiều tệp, quyết định kiến ​​trúc hoặc một số phương pháp triển khai hợp lệ cần được đánh giá trước khi viết bất kỳ mã nào. Việc thực thi trực tiếp nhằm mục đích dành cho các thay đổi có phạm vi rõ ràng, được hiểu rõ, chẳng hạn như thêm một kiểm tra có điều kiện duy nhất vào một hàm trong một tệp, trong đó phương pháp triển khai rõ ràng và không yêu cầu lập kế hoạch trước. Bởi vì thay đổi xác thực ngày này được giới hạn trong phạm vi hẹp đối với một điều kiện duy nhất trong một hàm/tệp hiện có, nên nó không đáp ứng ngưỡng có thể biện minh cho việc chuyển sang chế độ kế hoạch hoặc gọi chế độ tư duy mở rộng; nó có thể được thực hiện trực tiếp và hiệu quả.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-61', 'cca-f', 61, 'You want to implement a complex graph traversal algorithm that has specific performance requirements and must correctly handle edge cases such as disconnected nodes, cycles, and weighted edges. You want to structure your workflow so that you can efficiently and progressively refine the implementation with Claude across multiple iterations.  
  
Which approach would most effectively enable this kind of progressive improvement across iterations?', '[{"key":"A","text":"Have Claude extensively research the algorithm and create a detailed implementation plan using extended thinking, then implement the complete solution based on that plan."},{"key":"B","text":"Provide Claude with a reference implementation from documentation, then ask it to rewrite the code to match your codebase style and add the required edge case handling, comparing outputs against the reference."},{"key":"C","text":"Provide Claude with a detailed natural language specification of the algorithm, including all requirements and edge cases. Review each output manually and provide descriptive feedback on what behavior needs to change."},{"key":"D","text":"Write a test suite covering expected behavior, edge cases, and performance requirements before implementation. Ask Claude to write code that passes the tests, then iterate by sharing test failures with each refinement request."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc viết các bài kiểm tra trước khi triển khai sẽ thiết lập các tiêu chí thành công cụ thể, khách quan cho hành vi dự kiến ​​của thuật toán, các trường hợp biên bắt buộc (nút bị ngắt kết nối, chu trình, các cạnh có trọng số) và các yêu cầu về hiệu suất. Điều này cho phép Claude nhận được phản hồi chính xác, rõ ràng dưới dạng kết quả kiểm tra đạt/không đạt thay vì mô tả bằng ngôn ngữ tự nhiên chủ quan, cho phép Claude tự động lặp lại — chạy thử nghiệm, phân tích lỗi và điều chỉnh quá trình triển khai — cho đến khi đáp ứng tất cả các yêu cầu. Quy trình phát triển dựa trên thử nghiệm này (viết các bài kiểm tra → xác nhận chúng thất bại → triển khai → lặp lại các lỗi) là phương pháp hay nhất được ghi lại của Anthropic để mã hóa tác nhân bằng Claude Code, vì mỗi chu kỳ từ đỏ sang xanh lục cung cấp tín hiệu rõ ràng, có thể kiểm chứng giúp hướng dẫn hội tụ hiệu quả và cũng bảo vệ chống lại hành vi thay đổi âm thầm của Claude thay vì sửa lỗi triển khai, vì các thử nghiệm được cam kết trước đóng vai trò là một điểm kiểm tra ổn định.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-62', 'cca-f', 62, 'You have documented API error-handling conventions in a CLAUDE.md file at your project root, specifying that endpoint handlers should use a custom ApiError class. After several sessions, you notice that Claude Code sometimes follows these conventions and sometimes instead uses generic try/catch blocks with string messages. This inconsistency appears random across different coding sessions.  
  
What is the most efficient first diagnostic step to take?', '[{"key":"A","text":"Add a more detailed code examples to your CLAUDE.md showing the exact ApiError usage pattern for different endpoint types."},{"key":"B","text":"Run /memory to check which memory files are loaded and verify your CLAUDE.md is included."},{"key":"C","text":"Search for conflicting instructions in ~/.claude/CLauDe.md or ~/.claude/rules/ that might override your project conventions."},{"key":"D","text":"Create path-specific rules in .claude/rules/handlers.md with YAML frontmatter scoping the error handling instructions to your API handler files."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Lệnh /memory là công cụ Claude Code tích hợp sẵn để kiểm tra chính xác các tệp CLAUDE.md, CLAUDE.local.md và quy tắc hiện đang được tải trong một phiên, cùng với thứ tự tải của chúng. Do việc tải bộ nhớ Claude Code phụ thuộc vào các yếu tố như thư mục làm việc hiện tại, duyệt đệ quy lên cây thư mục và tải tệp thư mục con theo yêu cầu, nên hành vi không nhất quán giữa các phiên được chẩn đoán hiệu quả nhất bằng cách trước tiên xác nhận xem dự án CLAUDE.md có thực sự được tải hay không, thay vì suy đoán về các tệp quy tắc xung đột, không đủ chi tiết hoặc cần các tệp quy tắc trong phạm vi đường dẫn mới.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-63', 'cca-f', 63, 'Your team has connected a custom MCP server that provides DevOps workflow templates. This server exposes several MCP prompts (such as deploy_checklist and incident_response) in addition to tools.  
  
How do these MCP prompts become accessible within Claude Code?', '[{"key":"A","text":"They are surfaced as @ -mentionable resources alongside files, fetched and attached to your message when referenced."},{"key":"B","text":"They are automatically prepended to every conversation as additional system-level context, influencing Claude’s behavior throughout the session."},{"key":"C","text":"They are added to Claude Code’s tool registry alongside the server’s tools, invoked automatically by the model when relevant to the task."},{"key":"D","text":"They appear as slash commands (e.g., mcp_servername_deploy_checklist) that you can invoke, with arguments passed after the command name."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Máy chủ MCP có thể hiển thị lời nhắc dưới dạng một trong ba loại nguyên thủy MCP (công cụ, tài nguyên và lời nhắc). Trong Claude Code, lời nhắc MCP hiển thị dưới dạng lệnh gạch chéo bằng cách sử dụng quy ước đặt tên /mcp__servername__promptname — ví dụ: /mcp__devops__deploy_checklist — và bất kỳ tham số nào mà lời nhắc xác định đều được cung cấp dưới dạng đối số được nhập sau tên lệnh, giống như các đối số được truyền cho lệnh dấu gạch chéo tùy chỉnh. Điều này khác với các tài nguyên MCP, thay vào đó được hiển thị dưới dạng các mục có thể đề cập @ được tìm nạp và đính kèm vào thư, đồng thời khác với các công cụ MCP, nằm trong sổ đăng ký công cụ và được mô hình tự động gọi trong khi thực hiện một tác vụ. Vì lời nhắc có thể tái sử dụng, các mẫu được kích hoạt rõ ràng bởi người dùng (không phải lệnh gọi công cụ tự động hoặc ngữ cảnh hệ thống được chèn), Claude Code hiển thị chúng thông qua giao diện lệnh gạch chéo thay vì tự động gọi hoặc tự động chèn chúng.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-64', 'cca-f', 64, 'You''re implementing a new payment processing module that needs to follow your project''s established patterns for database transactions, error handling, and audit logging. You''ve identified three existing modules that exemplify these patterns:  
  
- db_utils.py  
- error_handlers.py  
- audit_logger.py  
  
This is a one-off integration task, and these patterns are already well documented in your team wiki, so they don''t need additional project-level documentation. What is the most effective approach?', '[{"key":"A","text":"Add documentation of each pattern to your CLAUDE.md file, establishing them as project conventions that Claude will apply automatically."},{"key":"B","text":"Describe the patterns from the three modules in natural language in your prompt, explaining the transaction handling approach, error format, and logging conventions Claude should follow."},{"key":"C","text":"Ask Claude to explore your codebase to find and understand the transaction, error handling, and logging patterns before generating the new module."},{"key":"D","text":"Use @ references to include the three modules directly in your prompt, giving Claude concrete code examples of the patterns to follow."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Hướng dẫn chính thức của Claude Code khuyên bạn nên sử dụng tham chiếu tệp `@` để kéo trực tiếp nội dung chính xác của các tệp có liên quan vào lời nhắc để Claude có mã cụ thể để làm theo, thay vì mô tả vị trí tồn tại của mã hoặc chức năng của mã. Điều này được nêu rõ ràng trong phần ''Cung cấp nội dung phong phú'' của các phương pháp hay nhất của Claude Code: ''Tệp tham chiếu có @ thay vì mô tả vị trí tồn tại của mã. Claude đọc hồ sơ trước khi trả lời.” Vì nhiệm vụ này là tích hợp một lần và nhà phát triển đã biết chính xác ba mô-đun nào minh họa cho các mẫu được yêu cầu nên no cần thêm thông tin này vào CLAUDE.md — CLAUDE.md dành cho các quy ước liên tục, trên toàn dự án nên áp dụng trong mọi phiên (theo hướng dẫn của Anthropic, một chỉnh sửa CLAUDE.md được đảm bảo cho một quy ước định kỳ hoặc lỗi lặp đi lặp lại, không phải một lần sửa chữa). Yêu cầu Claude khám phá cơ sở mã (option C) sẽ lãng phí bối cảnh và thời gian để khám phá lại các tệp mà nhà phát triển đã xác định. Việc mô tả các mẫu bằng ngôn ngữ tự nhiên (option B) kém chính xác và đáng tin cậy hơn so với việc cung cấp mã thực tế, vì Claude hoạt động tốt hơn khi đưa ra các ví dụ cụ thể thay vì mô tả các quy ước được diễn giải. Việc bao gồm trực tiếp ba tệp thông qua tham chiếu @ mang lại cho Claude khả năng xử lý giao dịch, định dạng lỗi và quy ước ghi nhật ký kiểm tra chính xác để phản ánh khi tạo mô-đun xử lý thanh toán mới.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-65', 'cca-f', 65, 'Your team has three requirements for how Claude Code should behave in your project:  
  
1. Claude must never modify files in the `db/migrations/` directory.  
2. Claude should prefer your custom logging module over `console.log`.  
3. All TypeScript files must be auto-formatted with Prettier after every edit.  
  
All three requirements are currently written as instructions inside your project''s CLAUDE.md file. During a complex refactoring session, a developer discovers that Claude edited a migration file, violating requirement #1.  
  
How should you restructure these requirements across Claude Code''s configuration mechanisms?', '[{"key":"A","text":"Add Edit(./db/migrations/**) to permissions.deny in the project settings, keep the logging preference in CLAUDE.md, and add a PostToolUse hook on the Edit tool that runs Prettier on changed TypeScript files."},{"key":"B","text":"Move all three requirements into .claude/rules/ as path-scoped rules: one targeting db/migrations/** that forbids editing those files, and others targeting **/*.ts for the logging convention and formatting instruction."},{"key":"C","text":"Rewrite all three requirements in CLAUDE.md using stronger directive language and add few-shot examples that demonstrate Claude refusing to edit migration files and running Prettier after edits."},{"key":"D","text":"Configure hooks for all three: a PreToolUse hook script that blocks Edit calls targeting db/migrations/,a PreToolUse hook script that adds logging convention context before edits, and a PostToolUse hook that runs Prettier after TypeScript edits."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Nội dung CLAUDE.md được tải vào ngữ cảnh của mô hình dưới dạng hướng dẫn tư vấn, do đó, mô hình vẫn có thể đi chệch khỏi bối cảnh đó—đặc biệt là trong các phiên dài và phức tạp—đó chính xác là lý do tại sao tệp di chuyển đã được chỉnh sửa bất chấp hướng dẫn. Tài liệu chính thức của Claude Code phân biệt các lớp thực thi xác định với hướng dẫn theo ngữ cảnh: các quy tắc cấp phép (permissions.deny trong settings.json) được đánh giá bởi chính bộ khai thác Claude Code và chặn lệnh gọi công cụ phù hợp (ví dụ: Edit(./db/migrations/**)) trước khi nó có thể chạy, đưa ra một ranh giới cứng được đảm bảo, trong khi CLAUDE.md được ghi rõ ràng là ''không phải là ranh giới bảo mật cứng''. Tài liệu về hook nêu rõ hơn rằng đối với việc chặn dựa trên đường dẫn tĩnh, bạn nên "sử dụng hệ thống cấp phép thay vì hook để thực thi một sự cho phép hoặc từ chối cứng nhắc", vì hook là nỗ lực tốt nhất trong khi các quy tắc cấp phép mang tính quyết định và được thực thi bằng phán quyết no LLM có liên quan. Trong khi đó, tùy chọn mô-đun ghi nhật ký là một quy ước về phong cách rất phù hợp với CLAUDE.md, nơi mô hình có thể áp dụng phán đoán. Yêu cầu định dạng Prettier là một hành động chỉnh sửa sau có thể lặp lại, xác định, là trường hợp sử dụng tiêu chuẩn cho hook PostToolUse (khớp với các công cụ Chỉnh sửa/Ghi) gọi Prettier trên tệp đã thay đổi—Hướng dẫn hook của Claude Code đưa ra mẫu chính xác này làm ví dụ điển hình. Ánh xạ này—hạn chế cứng đối với Pers.deny, ưu tiên mềm đối với CLAAUDE.md, tự động hóa xác định đối với PostToolUse hook—giải quyết chính xác lỗi tuân thủ đã được chứng minh bằng cách chuyển quy tắc quan trọng về an toàn sang một cơ chế thực thi mà hành vi của mô hình không thể bỏ qua.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-66', 'cca-f', 66, 'You''ve asked Claude to write a data migration script, but the initial output doesn''t correctly handle records with null values in required fields. What is the most effective way to iterate toward a working solution?', '[{"key":"A","text":"Manually edit the generated code to fix the null handling, then continue working with Claude on other parts."},{"key":"B","text":"Add “think harder about edge cases” to your prompt and request a complete rewrite of the migration logic."},{"key":"C","text":"Describe the null value problem in detail and ask Claude to regenerate the entire script with improved edge case handling."},{"key":"D","text":"Provide a test case with example input containing null values and the expected output, then ask Claude to fix it."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc cung cấp một trường hợp kiểm thử cụ thể — đầu vào cụ thể chứa các giá trị null cùng với đầu ra dự kiến ​​— mang lại cho Claude một mục tiêu chính xác, có thể kiểm chứng để gỡ lỗi. Cách tiếp cận dựa trên thử nghiệm này cho phép Claude suy luận về tình trạng lỗi chính xác và xác nhận cách khắc phục đã giải quyết được nó, thay vì dựa vào các hướng dẫn mơ hồ (chẳng hạn như ''nghĩ kỹ hơn''), mô tả vấn đề chỉ bằng lời nói có nguy cơ tái tạo không hoàn chỉnh hoặc bỏ qua Claude để vá mã theo cách thủ công, điều này làm mất đi lợi ích của việc yêu cầu trợ lý hiểu và sửa lỗi logic của chính nó.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-67', 'cca-f', 67, 'You have a rough idea for implementing a caching layer for API responses to speed up the `/products` endpoint — using Redis with a 5-minute TTL — but you are new to production caching and are not sure what other considerations a robust implementation requires.  
  
What is the most effective way to start your iterative workflow?', '[{"key":"A","text":"Start with a minimal request: “Add Redis caching to /products with 5-minute TTL.” Add features and fix issues through follow-up prompts as problems surface during testing."},{"key":"B","text":"Write a specification with your known requirements and “TBD” markers for uncertain areas, having Claude propose solutions for each TBD as it implements."},{"key":"C","text":"Ask Claude to interview you about the caching requirements before implementing, surfacing considerations like invalidation strategies, cache layers, consistency guarantees, and failure modes."},{"key":"D","text":"Use plan mode to analyze the current/products endpoint implementation, then provide your caching requirements once Claude explains how the existing code is structured."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Khi bạn thiếu kiến ​​thức chuyên môn về miền để biết một giải pháp mạnh mẽ cần cân nhắc những gì — chẳng hạn như chiến lược vô hiệu hóa bộ nhớ đệm, nhiều lớp bộ nhớ đệm, đảm bảo tính nhất quán và chế độ lỗi/dự phòng cho lớp bộ nhớ đệm — bước đầu tiên hiệu quả nhất là yêu cầu Claude chủ động đặt các câu hỏi làm rõ (một ''cuộc phỏng vấn'') trước khi viết bất kỳ thông số kỹ thuật hoặc mã nào. Điều này làm nổi bật những điều chưa biết mà bạn chưa thể tự trình bày rõ ràng, đảm bảo kế hoạch kết quả và việc triển khai giải quyết các mối quan ngại ở cấp độ sản xuất ngay từ đầu, thay vì bị phát hiện một cách phản ứng thông qua việc lặp lại thử và sai, được đoán thông qua các điểm đánh dấu TBD chưa được giải quyết hoặc bị bỏ qua bằng cách chỉ tập trung vào cấu trúc mã của điểm cuối hiện có.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-68', 'cca-f', 68, 'Your team wants Claude to follow a detailed code review checklist (8 items covering API changes, test coverage, documentation, security, etc.) whenever it reviews pull requests. The team also relies on Claude extensively for other tasks, including:  
  
- Writing new features  
- Debugging production issues  
- Generating documentation  
  
Currently, developers manually paste the checklist at the start of each review session.  
  
Which approach best addresses this workflow need?', '[{"key":"A","text":"Create a /review slash command containing the checklist, invoked when starting reviews."},{"key":"B","text":"Create a dedicated review subagent with the checklist embedded in its configuration."},{"key":"C","text":"Configure plan mode as the default for code review sessions."},{"key":"D","text":"Add the checklist to the project’s CLAUDE.md file under a “Code Review” section."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các lệnh gạch chéo tùy chỉnh trong Claude Code là các mẫu lời nhắc có thể sử dụng lại được lưu trữ dưới dạng tệp đánh dấu (ví dụ: trong.claude/commands/) được gọi theo yêu cầu bằng cách nhập lệnh như /review. Điều này cho phép nhóm mã hóa toàn bộ danh sách kiểm tra gồm 8 mục một lần và chỉ đưa nó vào ngữ cảnh khi phiên đánh giá được bắt đầu một cách rõ ràng, thay thế bước sao chép-dán thủ công. Ngược lại, nội dung được đặt trong CLAUDE.md được tải tự động vào ngữ cảnh của mỗi phiên bất kể loại nhiệm vụ, do đó, việc đưa danh sách kiểm tra dành riêng cho đánh giá vào đó sẽ đưa nó vào các công việc không liên quan như phát triển tính năng, gỡ lỗi hoặc tạo tài liệu một cách không cần thiết. Tác nhân phụ chuyên dụng hoặc cài đặt chế độ kế hoạch mặc định không phù hợp với nhu cầu đơn giản là chỉ kích hoạt danh sách kiểm tra tĩnh cụ thể cho các phiên đánh giá, khiến lệnh gạch chéo trở thành giải pháp hiệu quả và có mục tiêu nhất.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-69', 'cca-f', 69, 'You are building developer productivity tools using the Claude Agent SDK. The agent helps engineers explore unfamiliar codebases, understand legacy systems, generate boilerplate code, and automate repetitive tasks. It uses the built-in tools (Read, Write, Bash, Grep, Glob) and integrates with Model Context Protocol (MCP) servers.  
  
An engineer encounters an unfamiliar error message, "SYNC_CONFLICT: entity version mismatch detected," in the production logs, but does not know which of the 12 services in the codebase produces it. They ask the agent to help find the source of this error.  
  
Which exploration approach will most efficiently locate the responsible code?', '[{"key":"A","text":"Use Glob to find files in directories commonly associated with error handling (such as errors/, exceptions/,or handlers/) across all services, then Read each matching file."},{"key":"B","text":"Read the project’s README and service configuration files to understand the architecture, then systematically Read source files in each service directory."},{"key":"C","text":"Use Grep to search for distinctive text from the error message (like “SYNC_CONFLICT” or “entity version mismatch”), then Read the matching files to understand context."},{"key":"D","text":"Use Grep to find all files that import the project’s error handling module, then Read those files to locate custom error definitions."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Grep cung cấp khả năng tìm kiếm nhanh, dựa trên nội dung trên toàn bộ cơ sở mã, do đó, việc tìm kiếm một chuỗi ký tự đặc biệt từ thông báo lỗi (chẳng hạn như "SYNC_CONFLICT" hoặc "phiên bản thực thể không khớp") sẽ trực tiếp hiển thị (các) tệp chính xác nơi lỗi đó được xác định hoặc phát sinh, bất kể lỗi đó nằm trong dịch vụ hoặc thư mục nào. Điều này hiệu quả hơn nhiều so với việc giả định một quy ước thư mục (có thể không nhất quán trên tất cả 12 dịch vụ), đọc các tệp trên phạm vi rộng trong toàn bộ dự án hoặc tìm kiếm gián tiếp để nhập một hoạt động xử lý lỗi mô-đun. Sau khi Grep xác định được (các) tệp trùng khớp, việc Đọc chúng sẽ cung cấp ngữ cảnh xung quanh cần thiết để hiểu và khắc phục sự cố. Điều này phản ánh thực tiễn mã hóa tác nhân tiêu chuẩn để tìm kiếm văn bản đặc biệt, duy nhất trước khi mở rộng tìm kiếm.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-70', 'cca-f', 70, 'You are building developer productivity tools using the Claude Agent SDK. The agent helps engineers explore unfamiliar codebases, understand legacy systems, generate boilerplate code, and automate repetitive tasks. It uses built-in tools (Read, Write, Bash, Grep, Glob) and integrates with Model Context Protocol (MCP) servers.  
  
A developer asks the agent to investigate why a specific API endpoint intermittently returns 500 errors. The codebase contains 200+ files, and the developer does not know which components are involved. The agent must trace the error through the routing, middleware, business logic, and database layers.  
  
Which task decomposition approach would be most effective?', '[{"key":"A","text":"Have the agent dynamically generate investigation subtasks based on what it discovers at each step, adapting its exploration plan as new information about the error path emerges."},{"key":"B","text":"Have the agent first create a comprehensive plan mapping all code paths through the endpoint before beginning any file exploration or code reading."},{"key":"C","text":"Run parallel worker agents that simultaneously investigate all four layers, then synthesize their findings to identify where the error originates."},{"key":"D","text":"Define a fixed sequence of investigation steps upfront – grep for error patterns, then read error handlers, then check database queries, then examine middleware – executing each step regardless of intermediate findings."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Khi không thể biết trước phạm vi của một cuộc điều tra — chẳng hạn như việc truy tìm một lỗi không liên tục thông qua một cơ sở mã nhiều lớp, không quen thuộc — thì cách tiếp cận hiệu quả nhất là phân tách nhiệm vụ thích ứng: tác nhân tạo và tinh chỉnh các nhiệm vụ phụ điều tra dựa trên nội dung mà mỗi bước khám phá phát hiện (ví dụ: lần truy cập grep, nhật ký lỗi, đường dẫn mã đáng ngờ), thay vì cam kết thực hiện một kế hoạch hoặc trình tự bước cứng nhắc trước khi bất kỳ hoạt động khám phá nào diễn ra. Điều này phản ánh hướng dẫn của Anthropic dành cho hệ thống tác nhân: tránh chỉ định quá mức các nhiệm vụ ngay từ đầu, để tác nhân lặp lại và tự sửa, đồng thời sử dụng lý luận xen kẽ sau mỗi kết quả của công cụ để đánh giá kết quả phát hiện, xác định các lỗ hổng và quyết định hành động tiếp theo. Không thể tạo ra một bản đồ được lập kế hoạch trước đầy đủ về tất cả các đường dẫn mã trước khi khám phá mã, một chuỗi cố định cứng nhắc bỏ qua bằng chứng được thu thập trong quá trình thực hiện (lãng phí nỗ lực vào các lớp không liên quan) và việc điều tra song song cả bốn lớp là không hiệu quả vì các lớp bị xâu chuỗi theo nguyên nhân (một lỗi trong một lớp thường tạo ra triệu chứng được quan sát thấy ở lớp khác), làm cho một dấu vết thích ứng duy nhất hiệu quả hơn so với các phát hiện song song được tổng hợp độc lập.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-71', 'cca-f', 71, 'You are building developer productivity tools with the Claude Agent SDK. The agent helps engineers explore unfamiliar codebases, understand legacy systems, generate boilerplate code, and automate repetitive tasks. It relies on the built-in tools (Read, Write, Bash, Grep, Glob) and also integrates with Model Context Protocol (MCP) servers.  
  
An engineer asks the agent to identify untested code paths in a legacy payment processing module that spans 45 files. After the agent has read the first 8 source files, its responses start becoming noticeably less accurate: it is forgetting code patterns discussed earlier, and it still hasn''t located all the relevant test files or traced the critical payment flows.  
  
What is the most effective approach to complete this investigation?', '[{"key":"A","text":"Switch to using Grep to search for specific function names instead of reading full files, reducing the content loaded into context for remaining exploration."},{"key":"B","text":"Spawn subagents to investigate specific questions (e.g., “find all test files for payment processing,” “trace refund flow dependencies”) while the main agent coordinates findings and preserves high-level understanding."},{"key":"C","text":"Document all current findings in a summary report, clear context completely, then use that report as the sole reference for continuing the investigation."},{"key":"D","text":"Clear context with /clear, then selectively re-read only the most critical files discovered so far, writing key findings to a scratchpad file that persists between context resets."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc ủy ​​quyền các câu hỏi phụ tập trung cho các tác nhân phụ cho phép mỗi tác nhân khám phá bằng cửa sổ ngữ cảnh rõ ràng của riêng mình (ví dụ: một tác nhân phụ định vị tất cả các tệp thử nghiệm để xử lý thanh toán, một tác nhân khác theo dõi các phụ thuộc của luồng hoàn tiền), trong khi tác nhân chính/điều phối chỉ giữ lại những phát hiện tổng hợp và hiểu biết cấp cao thay vì nội dung thô của mỗi tệp. Điều này ngăn chặn tình trạng xuống cấp ngữ cảnh do tích lũy lượng lớn nội dung tệp trong một cửa sổ ngữ cảnh duy nhất và cho phép công việc khám phá còn lại tiến hành một cách hiệu quả và song song, giải quyết trực tiếp cả hai hiện tượng được mô tả: độ chính xác giảm sút do quá tải ngữ cảnh và việc phát hiện không đầy đủ các tệp thử nghiệm cũng như dấu vết luồng thanh toán.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-72', 'cca-f', 72, 'You are developing developer productivity tools with the Claude Agent SDK. The agent assists engineers in exploring unfamiliar codebases, understanding legacy systems, generating boilerplate code, and automating repetitive tasks. It relies on the built-in tools (Read, Write, Bash, Grep, Glob) and can integrate with Model Context Protocol (MCP) servers.  
  
An engineer asks the agent to locate every file in the monorepo that imports the `@company/auth` package, in order to understand how authentication is used across services.  
  
Which built-in tool is most suitable for this task?', '[{"key":"A","text":"Read, starting with package.json files to trace dependency declarations"},{"key":"B","text":"Glob, to find files with “auth” in their filename or path"},{"key":"C","text":"Grep, to search for the import statement pattern across file contents"},{"key":"D","text":"Bash, to execute find. –type d –name “*auth*” and explore matching directories"}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc xác định các tệp nhập một gói cụ thể yêu cầu tìm kiếm nội dung văn bản của tệp để tìm mẫu câu lệnh nhập (ví dụ: `import. from ''@company/auth''` hoặc `require(''@company/auth'')`), chứ không chỉ khớp với tên tệp hoặc thư mục. Công cụ Grep được xây dựng có mục đích để tìm kiếm nội dung nhanh chóng, dựa trên mẫu trên nhiều tệp, khiến công cụ này trở thành lựa chọn thích hợp cho loại tác vụ khám phá cách sử dụng mã này. Glob chỉ khớp với đường dẫn/tên tệp, Đọc sẽ yêu cầu kiểm tra từng tệp riêng lẻ mà không có cơ chế tìm kiếm và lệnh find của Bash chỉ định vị các tệp/thư mục theo tên thay vì kiểm tra nội dung của chúng.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-73', 'cca-f', 73, 'You are building a multi-agent research system with the Claude Agent SDK. A coordinator agent delegates to specialized subagents: one that searches the web, one that analyzes documents, one that synthesizes findings, and one that generates reports. The system researches topics and produces comprehensive, cited reports.  
  
In production, you observe the following:  
  
- Simple fact-checking queries (e.g., "What year was the Paris Climate Agreement signed?") traverse all four subagents sequentially, consuming 40+ seconds and significant tokens per query.  
- Complex comparative research benefits from running the full pipeline.  
- Your query distribution is diverse and continually evolving as users discover new applications.  
  
What is the most effective approach to optimize the system for this varying query complexity?', '[{"key":"A","text":"Create a fast-path for factual questions that bypasses subagents entirely, routing all other queries through the complete pipeline to ensure research thoroughness."},{"key":"B","text":"Implement pattern-based routing that categorizes queries by structure (single-fact vs. comparative vs. analytical) and maps each category to a predefined subagent combination."},{"key":"C","text":"Train a query complexity classifier on labeled historical data to predict optimal subagent combinations, retraining periodically as query patterns evolve."},{"key":"D","text":"Have the coordinator analyze each query and dynamically decide which subagents to invoke based on its assessment of query requirements."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Mẫu điều phối/điều phối viên-nhân viên của Claude Agent SDK được thiết kế sao cho tác nhân điều phối tự suy luận về từng truy vấn đến và tự động xác định tác nhân phụ nào thực sự cần thiết, thay vì dựa vào một bộ quy tắc, danh mục được mã hóa cứng cố định hoặc một trình phân loại được đào tạo riêng biệt. Các phương pháp tiếp cận tĩnh — phân chia đường dẫn nhanh/đường dẫn đầy đủ nhị phân, ánh xạ từ mẫu đến tác nhân phụ được xác định trước hoặc trình phân loại độ phức tạp được đào tạo lại định kỳ — tất cả đều yêu cầu bảo trì thủ công liên tục và phải vật lộn để theo kịp phân phối truy vấn đa dạng và liên tục phát triển khi người dùng tìm thấy các trường hợp sử dụng mới. Việc cho phép điều phối viên đánh giá các yêu cầu truy vấn trong thời gian chạy và chỉ gọi các tác nhân phụ cần thiết (ví dụ: bỏ qua phân tích và tổng hợp tài liệu để tra cứu thực tế đơn giản, nhưng chạy chuỗi báo cáo-phân tích-tổng hợp-tổng hợp tìm kiếm đầy đủ cho nghiên cứu so sánh) sẽ duy trì cả hiệu quả cho các truy vấn đơn giản và tính kỹ lưỡng cho các truy vấn phức tạp, đồng thời nó tự động tổng quát hóa thành các loại truy vấn mới mà không yêu cầu thiết kế lại quy tắc định tuyến hoặc đào tạo lại mô hình. Điều này phản ánh hướng dẫn của Anthropic rằng việc ra quyết định động, dựa trên mô hình được ưu tiên hơn so với các quy trình công việc cứng nhắc được xác định trước khi tính đa dạng của nhiệm vụ và tính khó đoán trước cao.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-74', 'cca-f', 74, 'You are building a multi-agent research system with the Claude Agent SDK. A coordinator agent delegates work to specialized subagents: one for web search, one for document analysis, one for synthesizing findings, and one for generating reports. The system researches topics and produces comprehensive, cited reports.  
  
When the system analyzes complex legal cases that cite multiple precedents, the document-analysis subagent currently processes each precedent sequentially. For a landmark case citing 12 precedents, this takes over 3 minutes to complete.  
  
What is the most effective way to reduce this latency while still preserving the coordinator''s ability to monitor and debug the system?', '[{"key":"A","text":"Create a recursive agent hierarchy where analysis agents subdivide work among child agents until reaching single-precedent granularity"},{"key":"B","text":"Have the coordinator spawn parallel document analysis subagents, each handling a subset of precedents, then aggregate results before synthesis"},{"key":"C","text":"Enable the document analysis subagent to spawn its own specialized subagents dynamically when it encounters cases with many citations"},{"key":"D","text":"Implement a message queue where precedent analysis tasks are processed asynchronously by a pool of worker agents"}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Bởi vì 12 tiền lệ có thể được phân tích độc lập với nhau, đây là trường hợp điển hình cho mẫu điều phối-worker (fan-out/fan-in): bản thân điều phối viên sinh ra nhiều tác nhân phụ phân tích tài liệu song song, phân tách các tiền lệ giữa chúng và sau đó tổng hợp kết quả đầu ra của chúng trước khi chuyển sang bước tổng hợp. Giữ điều phối viên làm thực thể sinh ra và theo dõi các tác nhân phụ (thay vì để tác nhân phụ sinh ra tác nhân con của chính nó, xây dựng hệ thống phân cấp đệ quy sâu hoặc phân phối nhiệm vụ sang hàng đợi bên ngoài) duy trì một điểm hiển thị tập trung, duy nhất đối với tất cả các tác nhân đang hoạt động, điều này cần thiết để theo dõi tiến trình và gỡ lỗi — trong khi vẫn đạt được mức giảm độ trễ khi thực thi song song.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-75', 'cca-f', 75, 'You are expanding a multi-agent research system beyond its original single web search agent by adding specialized data sources:  
  
- A **financial API agent** that returns structured JSON containing revenue, margins, and growth rates  
- A **news monitoring agent** that returns prose summaries of recent developments  
- A **patent analysis agent** that returns structured lists of technology areas  
  
The synthesis agent combines the outputs from these subagents into executive briefings. Currently, the synthesis agent converts everything into bullet points, which causes:  
  
- Financial comparisons to lose their tabular clarity  
- News summaries to lose their narrative flow  
  
What change would most improve the quality of the briefings?', '[{"key":"A","text":"Update the synthesis agent to render each content type appropriately – financial data as tables, news as prose"},{"key":"B","text":"Standardize all subagent outputs to prose summaries with inline citations"},{"key":"C","text":"Standardize all subagent outputs to JSON with fields for claim, evidence, source, and confidence"},{"key":"D","text":"Add a format conversion layer between subagents and synthesis that transforms all outputs to a common intermediate representation"}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Vấn đề được mô tả là một định dạng đầu ra thống nhất duy nhất (dấu đầu dòng) đang được áp dụng cho các loại nội dung khác nhau về cơ bản, phá hủy các đặc điểm cấu trúc giúp mỗi loại trở nên hữu ích — các bảng truyền tải những so sánh định lượng (doanh thu, tỷ suất lợi nhuận, tốc độ tăng trưởng) tốt hơn nhiều so với các đầu dòng, trong khi văn xuôi vẫn duy trì dòng tường thuật về diễn biến tin tức. Cách khắc phục chính xác là làm cho tác nhân tổng hợp nhận biết được định dạng: hiển thị từng loại nội dung trong cách trình bày phù hợp nhất với nó (bảng dành cho dữ liệu tài chính/bằng sáng chế có cấu trúc, văn xuôi cho tin tức tường thuật) thay vì làm phẳng mọi thứ thành một định dạng chung. Việc tiêu chuẩn hóa tất cả các tác nhân phụ thành một định dạng đầu ra duy nhất (văn xuôi hoặc JSON) chỉ chuyển vấn đề không khớp thay vì giải quyết nó, vì nó sẽ buộc dữ liệu tài chính chuyển sang dạng tường thuật (mất độ chính xác/khả năng so sánh) hoặc tin tức vào các trường có cấu trúc cứng nhắc (mất luồng tường thuật). Việc chèn một lớp biểu diễn chung trung gian cũng không giải quyết được vấn đề cơ bản vì bước tổng hợp vẫn cần logic để quyết định cách hiển thị từng loại nội dung một cách thích hợp — cách khắc phục nằm trong chính logic tổng hợp/kết xuất, điều chỉnh định dạng đầu ra cho phù hợp với loại nội dung.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-76', 'cca-f', 76, 'Production logs indicate that, when the agent manages complex billing disputes requiring 6+ tool calls, it sometimes reaches its `max_turns` limit after collecting data but before resolving the issue or escalating it. The team wants to guarantee that every customer interaction ends in either a completed resolution or a human handoff, regardless of how the agent loop ends. Which approach provides this guarantee?', '[{"key":"A","text":"Add system prompt instructions telling the agent to call escalate_to_human with a summary of its findings whenever it determines it cannot complete resolution within its remaining actions."},{"key":"B","text":"Split the workflow into two sequential agent invocations – a first agent gathers information via get_customer and lookup_order, then a second agent receives that data and handles process_refund or escalate_to_human, each with separate turn budgets."},{"key":"C","text":"Add orchestration-layer code that checks the agent’s outcome after each loop termination – if the loop ended without a completed resolution or escalation, programmatically call escalate_to_human with the accumulated conversation context and tool results."},{"key":"D","text":"Implement a pre-tool-use hook that counts tool invocations and terminates the loop with an automatic escalation once the agent reaches 80% of its max_turns limit."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Kiểm tra trạng thái đầu cuối của lớp điều phối xác định có thể xử lý cả kết thúc vòng lặp bình thường và đặc biệt. Khi no đã hoàn tất quá trình giải quyết hoặc báo cáo trước đó được ghi lại, nó có thể tạo ra sự chuyển giao của con người theo chương trình với bối cảnh hội thoại đã thu thập và kết quả của công cụ. Việc vượt quá giới hạn `max_turns` của một lần chạy tổng đài viên sẽ tạo ra ngoại lệ `MaxTurnsExceeded`, do đó, hành vi dựa trên lời nhắc hoặc chỉ riêng ngân sách chuyển lượt tổng đài viên riêng biệt không thể đảm bảo kết quả cuối cùng được yêu cầu.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-77', 'cca-f', 77, 'You are developing developer-productivity tools with the Claude Agent SDK. The agent assists engineers in exploring unfamiliar codebases, understanding legacy systems, generating boilerplate code, and automating repetitive tasks. It uses the built-in tools (Read, Write, Bash, Grep, Glob) and integrates with Model Context Protocol (MCP) servers.  
  
An engineer asks the agent to understand how the caching layer functions before adding a new cache-invalidation trigger. After initial Grep searches, the agent has determined that caching logic spans 15 files—including decorators, middleware, and service classes—covering approximately 8,000 lines total. What is the most effective next step to build understanding while managing context constraints?', '[{"key":"A","text":"Use the Read tool to sequentially load all 15 files, building complete understanding across the full caching implementation."},{"key":"B","text":"Use Glob to find files matching common caching patterns (cache.py, caching/), prioritize the largest files by reading them first, then check smaller files for gaps."},{"key":"C","text":"Analyze imports and class hierarchies to identify the base cache class, Read that file to understand the interface, then trace specific invalidation implementations."},{"key":"D","text":"Use Grep to search for “invalidate” and “expire” patterns across all files, then Read only those specific line ranges with minimal surrounding context."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc truy tìm từ lớp bộ đệm cơ sở sẽ thiết lập giao diện bộ đệm, trách nhiệm của nó và các mối quan hệ mà việc triển khai cụ thể phải tuân theo. Sau đó, tác nhân chỉ có thể kiểm tra các hoạt động triển khai vô hiệu hóa quan trọng, duy trì bối cảnh trong khi vẫn giữ lại thông tin kiến ​​trúc cần thiết để thêm trình kích hoạt chính xác.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-78', 'cca-f', 78, 'You are creating developer-productivity tools with the Claude Agent SDK. The agent assists engineers in exploring unfamiliar codebases, understanding legacy systems, generating boilerplate code, and automating repetitive work. It uses the built-in tools (Read, Write, Bash, Grep, Glob) and integrates with Model Context Protocol (MCP) servers.  
  
Your codebase-exploration tool saves session IDs so engineers can continue investigations across work sessions. Yesterday, an engineer spent an hour analyzing a legacy authentication module and building context about its architecture and dependencies. They want to continue today. The session ID is valid, but version control indicates that a teammate''s merge modified 3 of the 12 files the agent previously read overnight. Which approach best balances efficiency and accuracy?', '[{"key":"A","text":"Start fresh session to ensure the agent works with current codebase state without stale assumptions"},{"key":"B","text":"Resume the session and inform the agent which specific files changed for targeted re-analysis"},{"key":"C","text":"Resume the session and immediately have the agent re-read all 12 previously analyzed files"},{"key":"D","text":"Resume the session without informing the agent about the changed files"}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các phiên Claude được tiếp tục sẽ lưu giữ lịch sử cuộc trò chuyện của họ, do đó, việc giữ lại bản phân tích trước đó sẽ tránh được công việc trùng lặp. Những thay đổi đã biết đối với ba tệp đã đọc trước đó chỉ có thể làm mất hiệu lực ngữ cảnh hoặc kết luận phụ thuộc vào các tệp đó; việc xác định rõ ràng chúng cho phép tác nhân đọc lại và đánh giá lại các khu vực bị ảnh hưởng trong khi vẫn duy trì phân tích hợp lệ của chín tệp còn lại. Điều này cân bằng độ chính xác của mã hiện tại với việc tái sử dụng ngữ cảnh phiên một cách hiệu quả.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-79', 'cca-f', 79, 'You are developing developer-productivity tools with the Claude Agent SDK. The agent assists engineers in exploring unfamiliar codebases, understanding legacy systems, generating boilerplate code, and automating repetitive tasks. It uses the built-in tools (Read, Write, Bash, Grep, Glob) and integrates with Model Context Protocol (MCP) servers.  
  
Your agent must insert a new helper function into the middle of a 150-line utility module, between two existing functions. The Edit tool fails because its `old_string` parameter cannot locate unique text to match—the file contains repetitive docstrings, variable names, and structural patterns. What is the most reliable way to perform this insertion?', '[{"key":"A","text":"Use Edit with an extremely long old_string capturing 30+ lines of context to guarantee uniqueness"},{"key":"B","text":"Use Bash to append the function definition to the end of the file using heredoc syntax"},{"key":"C","text":"Use Edit’s replace_all parameter to target a common pattern and embed the new function in the replacement text"},{"key":"D","text":"Use Read to load the file, add the function at the appropriate location, then Write the updated file"}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Công cụ chỉnh sửa tác nhân được quản lý thực hiện thay thế chuỗi và thường yêu cầu `old_string` xảy ra chính xác một lần. Khi tồn tại neo duy nhất đáng tin cậy no, việc tải tệp hoàn chỉnh bằng Đọc, chèn trình trợ giúp vào vị trí được yêu cầu trong nội dung và thay thế tệp thông qua Ghi sẽ tạo ra kết quả xác định. Công cụ Viết chấp nhận nội dung tệp đầy đủ, trong khi `replace_all` sẽ ảnh hưởng đến mọi lần xuất hiện trùng khớp.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-80', 'cca-f', 80, 'The infrastructure-as-code repository contains Terraform modules (`/terraform/`), Kubernetes manifests (`/kubernetes/`), and CI/CD pipeline scripts (`/pipelines/`). Each needs distinct conventions, yet the single root `CLAUDE.md` has grown beyond 500 lines. When developers work on Kubernetes files, Terraform-specific rules are unnecessarily loaded into context and consume tokens.  
  
What is the best way to reorganize this so that only relevant guidance loads when editing particular file types?', '[{"key":"A","text":"Split content into subdirectory CLAUDE.md files (/terraform/CLAUDE.md, /kubernetes/CLAUDE.md), so Claude loads directory-specific guidance."},{"key":"B","text":"Keep the root CLAUDE.md and use @path/to/import syntax to modularly include tool-specific guidance files from separate documents."},{"key":"C","text":"Restructure the root CLAUDE.md into clearly labeled sections with headers (e.g, “## Terraform Conventions”), improving organization and readability."},{"key":"D","text":"Create files in .claude/rules/ with YAML frontmatter path-scoping (e.g., paths: [“terraform/**/*”]), loading rules only when editing matching files."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Claude Code hỗ trợ các quy tắc Markdown trong `.claude/rules/` với `paths` YAML frontmatter, đưa từng quy tắc vào các tệp phù hợp. Điều này giữ cho các hướng dẫn dành riêng cho Terraform-, Kubernetes- và quy trình nằm ngoài ngữ cảnh trừ khi Claude đang làm việc với các đường dẫn áp dụng. Việc nhập `@` cải thiện tổ chức nhưng được mở rộng và tải khi khởi động, do đó chúng không làm giảm bối cảnh không liên quan.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-81', 'cca-f', 81, 'You are developing developer-productivity tools with the Claude Agent SDK. The agent assists engineers in exploring unfamiliar codebases, understanding legacy systems, generating boilerplate code, and automating repetitive tasks. It uses the built-in tools (Read, Write, Bash, Grep, Glob) and integrates with Model Context Protocol (MCP) servers.  
  
After you add an MCP server containing specialized code-refactoring tools (`extract_function`, `rename_variable`, `inline_function`), you notice the agent still performs refactoring through basic text manipulation using Write and Bash `sed` commands. The MCP server is connected and healthy. On reviewing the configuration, you find that every MCP tool has only a minimal description, such as “extract_function: Extracts a function from code.”  
  
What is the most effective way to increase adoption of the MCP refactoring tools?', '[{"key":"A","text":"Implement a request classifier that detects refactoring intent and automatically routes those requests to the MCP server before the agent processes them."},{"key":"B","text":"Remove the Write tool from the agent’s configuration for refactoring sessions so it must use the MCP tools for code modifications."},{"key":"C","text":"Accept this as expected behavior since simpler tools like sed are more predictable than specialized refactoring tools."},{"key":"D","text":"Enhance the MCP tool descriptions to explain when each tool is preferable to text manipulation and clarify expected inputs and outputs."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Mô tả công cụ là phần chính của định nghĩa công cụ LLM: chúng phải giải thích công cụ này làm gì, khi nào nên sử dụng và cách thức hoạt động của công cụ đó. Các mô tả giúp phân biệt tái cấu trúc ngữ nghĩa với thao tác văn bản chung và chỉ định đầu vào và đầu ra dự kiến ​​sẽ cung cấp cho mô hình bối cảnh cần thiết để chọn các công cụ MCP chuyên dụng một cách thích hợp.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-82', 'cca-f', 82, '$36', '[{"key":"A","text":"Create .claude/rules/ files for each standard with YAML frontmatter paths listing every package directory where that standard should apply."},{"key":"B","text":"Put all standards in the root CLAUDE.md with override instructions like “ignore security-rules.md when working in packages that don’t handle user data.”"},{"key":"C","text":"Create a shared-stendards.md that uses @imports to combine all three standards, then have each package’s CLAUDE.md import that combined file."},{"key":"D","text":"Use @imports in each package’s CLAUDE.md to reference only the specific standard files relevant to that package, based on the maintainer’s domain knowledge."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các tệp `CLAUDE.md` theo gói cục bộ có thể sử dụng `@imports` để chỉ bao gồm các tiêu chuẩn chung áp dụng cho gói đó. Điều này bảo toàn một nguồn thông tin chính xác duy nhất cho từng tiêu chuẩn, tránh các hướng dẫn không liên quan và cho phép người bảo trì áp dụng kiến ​​thức về miền của họ trong đó đường dẫn thư mục không tiết lộ liệu gói có xử lý dữ liệu người dùng hay hiển thị API hay không.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-83', 'cca-f', 83, 'You are creating developer-productivity tools with the Claude Agent SDK. The agent assists engineers in exploring unfamiliar codebases, understanding legacy systems, generating boilerplate code, and automating repetitive work. It uses the built-in tools (Read, Write, Bash, Grep, Glob) and integrates with Model Context Protocol (MCP) servers.  
  
Your agent has spent 25 minutes examining a game engine’s rendering subsystem—reading shader code, buffer management, and frame-synchronization logic. An engineer now asks it to understand how the physics engine integrates with rendering for collision debug overlays. You notice that recent responses refer to “typical rendering patterns” rather than to the specific VulkanPipeline and FrameGraph classes it found earlier.  
  
What is the most effective approach?', '[{"key":"A","text":"Continue in the current context with more targeted prompts referencing the specific classes by name."},{"key":"B","text":"Summarize key rendering findings, then spawn a sub-agent for physics exploration with that summary in its initial context."},{"key":"C","text":"Spawn a sub-agent to explore physics independently, then manually synthesize its findings with the rendering knowledge accumulated in the main conversation."},{"key":"D","text":"Use /clear to reset context completely, then start fresh with physics exploration using file paths from the project''s CLAUDE.md."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Bản tóm tắt tập trung chuyển các thông tin kết xuất cần thiết để điều tra việc tích hợp lớp phủ va chạm, trong khi tác nhân phụ thực hiện khám phá vật lý mới trong cửa sổ ngữ cảnh của chính nó. Điều này hạn chế nhiễu thăm dò bổ sung trong bối cảnh chính và giữ lại các chi tiết hiển thị cụ thể cần thiết để kết nối hai hệ thống con. Anthropic ghi lại các tác nhân phụ như một cách để bảo toàn ngữ cảnh bằng cách tách riêng hoạt động khám phá và chỉ trả về một bản tóm tắt.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-84', 'cca-f', 84, 'After integrating a local MCP server that provides code-analysis tools (`analyze_dependencies`, `find_dead_code`, `calculate _complexity`), you confirm that the server is healthy and that the tools appear in the `tools/list` response. However, the agent consistently uses Grep to search for import statements instead of calling `analyze_dependencies`—even when users explicitly ask about “code dependencies.”  
  
Reviewing the tool definitions shows:  
  
- MCP: `analyze_ dependencies` – “Analyzes dependency graph”  
- Built-in: Grep – “Search file contents for a pattern using regular expressions. Returns matching lines with line numbers and surrounding context.”  
  
What is the most effective way to improve the agent’s selection of MCP tools?', '[{"key":"A","text":"Add routing instructions to the system prompt specifying that dependency-related questions should use MCP tools rather than Grep."},{"key":"B","text":"Remove Grep from available tools when the MCP server is connected to eliminate functional overlap."},{"key":"C","text":"Split analyze_dependencies into granular tools ( list_imports, resolve_transitive_deps, detect_circular_deps) so each has a focused purpose less likely to overlap with Grep."},{"key":"D","text":"Expand MCP tool descriptions to detail capabilities and outputs – e.g., “Builds dependency graph showing direct imports, transitive dependencies, and cycles.”"}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Mô tả công cụ hướng dẫn mô hình quyết định thời điểm và cách thức gọi một công cụ. Mô tả rằng `analyze_dependencies` xây dựng biểu đồ phụ thuộc và trả về các thao tác nhập trực tiếp, phụ thuộc bắc cầu và chu trình giúp phân biệt rõ ràng nó với một công cụ tìm kiếm văn bản và cho phép lựa chọn phù hợp cho các yêu cầu phân tích phụ thuộc.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-85', 'cca-f', 85, 'You are developing a multi-agent research system with the Claude Agent SDK. A coordinator agent assigns work to specialized subagents: one searches the web, one analyzes documents, one synthesizes findings, and one produces reports. The system researches topics and generates comprehensive, cited reports.  
  
While researching “renewable energy adoption,” the web-search agent returns recent statistics (2024: 35% adoption), while the document-analysis agent extracts data from internal reports (2021: 18% adoption). The synthesis agent mistakenly identifies these as conflicting sources instead of recognizing that the data indicates growth over time. What change would best allow the synthesis agent to correctly interpret these temporal differences?', '[{"key":"A","text":"Instruct the synthesis agent to always treat the most recent data as authoritative and place older findings in a separate historical appendix."},{"key":"B","text":"Add a conflict resolution agent that automatically discards older data when newer data exists for the same metric."},{"key":"C","text":"Require subagents to include publication or data collection dates in their structured outputs."},{"key":"D","text":"Configure the web search agent to only return results from the past 6 months."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Ngày tháng là siêu dữ liệu xuất xứ cần thiết cho các phát hiện định lượng. Việc đưa ngày xuất bản hoặc ngày thu thập dữ liệu của mỗi nguồn vào đầu ra tác nhân phụ có cấu trúc cho phép quá trình tổng hợp phân biệt các quan sát từ các giai đoạn khác nhau, sắp xếp chúng theo thứ tự thời gian và xác định sự thay đổi theo thời gian thay vì mâu thuẫn. Đầu ra có cấu trúc Claude hỗ trợ các trường do lược đồ xác định, bao gồm các trường chuỗi được định dạng ngày, cho phép siêu dữ liệu này được yêu cầu một cách nhất quán.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-86', 'cca-f', 86, 'You are using Claude Code to speed up software development. Your team uses it for code generation, refactoring, debugging, and documentation. You need to incorporate it into your development workflow with custom slash commands, `CLAUDE.md` configurations, and an understanding of when to use plan mode versus direct execution.  
  
You have asked Claude Code to create a PDF report-generation feature. The initial implementation queries the database correctly, but its output has formatting problems: table columns are too narrow and truncate content, dates are displayed without proper formatting, and page-break handling is wrong. You have noticed that these issues interact—altering column widths affects date rendering, and page breaks depend on content height.  
  
What is the most effective approach for iterating toward a working solution?', '[{"key":"A","text":"Show Claude an example of a correctly formatted report and ask it to match that output, rather than listing the specific technical issues."},{"key":"B","text":"Address the column width issue first with specific measurements, verify it works, then fix date formatting within the corrected columns, then adjust page breaks – testing after each change."},{"key":"C","text":"Provide all three issues in a single detailed message with exact specifications for each, allowing Claude to address them together in one update."},{"key":"D","text":"Start fresh with a detailed prompt specifying all formatting requirements upfront."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các vấn đề về bố cục phụ thuộc phải được giải quyết theo thứ tự phụ thuộc và được xác thực sau mỗi thay đổi. Việc sửa độ rộng cột trước tiên sẽ thiết lập không gian sẵn có cho việc định dạng ngày tháng; chiều cao nội dung thu được sau đó có thể được sử dụng để điều chỉnh ngắt trang. Thử nghiệm gia tăng sẽ tách biệt nguồn của từng hồi quy và tránh kết hợp các thay đổi tương tác thành một bản cập nhật đơn lẻ không rõ ràng.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-87', 'cca-f', 87, 'You are using Claude Code to speed up software development. Your team uses it for code generation, refactoring, debugging, and documentation. You need to incorporate it into your development workflow with custom slash commands, `CLAUDE.md` configurations, and an understanding of when to use plan mode versus direct execution.  
  
You have been tasked with adding real-time updates to the application. This could use WebSockets, Server-Sent Events, or polling, each with different complexity, browser support, and infrastructure requirements.  
  
What is the most effective way to start this task?', '[{"key":"A","text":"Use direct execution with a prompt asking Claude to analyze all approaches and implement the one it determines is best."},{"key":"B","text":"Use direct execution to implement polling first, then evaluate whether to upgrade to WebSockets later."},{"key":"C","text":"Enter plan mode to explore the architecture, evaluate trade-offs, and present options for team approval before implementing."},{"key":"D","text":"Start direct execution with WebSockets, then refactor if infrastructure issues arise."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Chế độ kế hoạch cho phép Claude Code phân tích cơ sở mã và phát triển kế hoạch triển khai mà không cần sửa đổi tệp hoặc chạy lệnh. Khi lựa chọn trong số các kiến ​​trúc giao tiếp thời gian thực có sự đánh đổi đáng kể, việc sử dụng kiến ​​trúc đó để khám phá kiến ​​trúc và đưa ra các giải pháp thay thế để nhóm phê duyệt sẽ thiết lập thiết kế trước khi bắt đầu triển khai.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-88', 'cca-f', 88, 'You are using Claude Code to speed up software development. Your team uses it for code generation, refactoring, debugging, and documentation. You need to incorporate it into your development workflow with custom slash commands, `CLAUDE.md` configurations, and an understanding of when to use plan mode versus direct execution.  
  
A security audit requires upgrading your authentication library from v2 to v3. The migration guide describes breaking changes: `authenticate()` now returns a Promise rather than accepting a callback, the `User` type has reorganized fields, and three deprecated methods have been removed. Grep indicates that the library is imported in 45 files across several modules.  
  
What is the most effective approach?', '[{"key":"A","text":"Update the dependency version, run the test suite, and use Claude Code to fix each failure as it appears."},{"key":"B","text":"Paste the migration guide''s breaking changes into your prompt and use direct execution to update all usages across the 45 files."},{"key":"C","text":"Create a custom slash command encapsulating the migration transformations, then execute it against each file without prior codebase exploration."},{"key":"D","text":"Enter plan mode to explore library usage across modules, map affected code paths, then create a migration strategy before implementing."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Để di chuyển thư viện xác thực trên diện rộng với các thay đổi về API, loại và phương thức bị xóa không đồng bộ, hãy phân tích cơ sở mã trước khi chỉnh sửa để xác định mọi cách sử dụng, ranh giới mô-đun bị ảnh hưởng và đường dẫn thời gian chạy. Chiến lược di chuyển dựa trên khoảng không quảng cáo đó hỗ trợ các chuyển đổi nhất quán và xác thực có mục tiêu, bao gồm cả các đường dẫn mà bộ thử nghiệm có thể không bao gồm. Chế độ kế hoạch Claude Code phù hợp cho giai đoạn phân tích này vì nó có thể kiểm tra cơ sở mã mà không cần sửa đổi tệp hoặc thực thi lệnh.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-89', 'cca-f', 89, 'You are creating developer-productivity tools with the Claude Agent SDK. The agent assists engineers with exploring unfamiliar codebases, understanding legacy systems, generating boilerplate code, and automating repetitive tasks. It uses the built-in tools (Read, Write, Bash, Grep, Glob) and integrates with Model Context Protocol (MCP) servers.  
  
An engineer asks the agent to add comprehensive tests to a legacy codebase containing 200 files and very little existing test coverage. The engineer has not indicated which modules should be prioritized.  
  
How should the agent break down this open-ended task?', '[{"key":"A","text":"Start writing tests for the first module alphabetically, using test failures and imports to discover related files organically."},{"key":"B","text":"Use Glob and Grep to map codebase structure, identify heavily-coupled modules, create a prioritized plan for high-impact areas, and revise as dependencies are discovered."},{"key":"C","text":"Systematically read all 200 files to create a complete function inventory before writing any tests, ensuring the testing plan accounts for every function before beginning."},{"key":"D","text":"Create a fixed testing schedule upfront based on directory structure, allocating equal effort to each top-level directory regardless of code complexity or business importance."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Đối với một cơ sở mã kế thừa lớn có mức độ ưu tiên đã nêu của no, nhân viên hỗ trợ nên khám phá kho lưu trữ để hiểu cấu trúc và các phần phụ thuộc của nó, xác định các mô-đun có tính kết hợp cao hoặc có tác động cao, đồng thời tạo một kế hoạch thử nghiệm gia tăng có thể được cập nhật khi tìm hiểu thêm. Glob và Grep hỗ trợ việc khám phá kho lưu trữ hiệu quả, trong khi kế hoạch có thể sửa đổi sẽ tránh được việc phân bổ tùy tiện hoặc có tỷ trọng bằng nhau mà bỏ qua rủi ro kỹ thuật và tác động kinh doanh.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-90', 'cca-f', 90, 'You are developing developer-productivity tools with the Claude Agent SDK. The agent assists engineers in exploring unfamiliar codebases, understanding legacy systems, generating boilerplate code, and automating repetitive work. It uses the built-in tools (Read, Write, Bash, Grep, Glob) and integrates with Model Context Protocol (MCP) servers.  
  
You have configured your Claude agent with three MCP servers: one for git operations, one for Jira ticket management, and one for documentation search.  
  
When a user asks the agent to “create a branch for JIRA-123 and add documentation links to the ticket,” how does the agent access tools across these servers?', '[{"key":"A","text":"Tools from all configured MCP servers are discovered at connection time and available simultaneously to the agent."},{"key":"B","text":"The agent automatically selects the most relevant server based on the request and loads only that server''s tools."},{"key":"C","text":"The agent queries each server sequentially to determine which handles each tool, routing calls based on tool name prefixes."},{"key":"D","text":"You must specify which MCP server to use for each turn, and the agent can only access one server''s tools at a time."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các máy chủ MCP đã định cấu hình có thể được kết nối trong một yêu cầu bằng bộ công cụ MCP cho mỗi máy chủ. Các công cụ được kích hoạt của họ có sẵn cho tác nhân, tác nhân này sẽ chọn các công cụ git và Jira có khả năng được mô tả phù hợp với công việc được yêu cầu; nó không bị giới hạn ở một máy chủ duy nhất trong một lượt.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-91', 'cca-f', 91, 'You are creating developer-productivity tools with the Claude Agent SDK. The agent helps engineers explore unfamiliar codebases, understand legacy systems, generate boilerplate code, and automate repetitive work. It uses the built-in tools (Read, Write, Bash, Grep, Glob) and integrates with Model Context Protocol (MCP) servers.  
  
An engineer’s exploration subagent spent 30 minutes analyzing a legacy payment system, read 47 files, and documented data flows. The session was interrupted when the engineer’s connection dropped. During the absence, a teammate merged a PR that renamed two utility functions. The engineer wants to continue the same exploration.  
  
What is the most effective approach?', '[{"key":"A","text":"Resume the subagent from its previous transcript without mentioning the changes – the architecture understanding remains valid."},{"key":"B","text":"Launch a fresh subagent and include the prior transcript in the initial prompt for context."},{"key":"C","text":"Launch a fresh subagent with a summary of prior findings."},{"key":"D","text":"Resume the subagent from its previous transcript and inform it about the renamed functions."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc nối lại phiên sẽ giữ lại bối cảnh khám phá được tích lũy trên 47 tệp và luồng dữ liệu được ghi lại. Các chức năng tiện ích được đổi tên là một thay đổi kho lưu trữ có liên quan, do đó, tác nhân được tiếp tục cần có bản cập nhật đó trong lời nhắc tiếp tục để kiểm tra lại các tham chiếu bị ảnh hưởng dựa trên cơ sở mã hiện tại. Tài liệu CLI và SDK của Anthropic hỗ trợ tiếp tục cuộc trò chuyện theo ID phiên cho công việc nhiều lượt.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-92', 'cca-f', 92, 'You are developing developer-productivity tools with the Claude Agent SDK. The agent helps engineers explore unfamiliar codebases, understand legacy systems, generate boilerplate code, and automate repetitive tasks. It uses the built-in tools (Read, Write, Bash, Grep, Glob) and integrates with Model Context Protocol (MCP) servers.  
  
An engineer used Claude Code yesterday to investigate authentication flows in a legacy monolith, accumulating significant context during a 2-hour session. Today, she wants to continue that same investigation. She has worked on three other codebases since then and knows the session was named `auth-deep-dive`.  
  
How should she resume?', '[{"key":"A","text":"Use `--resume auth-deep-dive` to load that specific session by name"},{"key":"B","text":"Use `--continue` to pick up where the most recent conversation left off"},{"key":"C","text":"Start fresh and re-read the same files"},{"key":"D","text":"Use `--session-id` with the UUID from yesterday''s session transcript file"}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Claude Code hỗ trợ tiếp tục một phiên cụ thể trước đó bằng tên hiển thị của nó với `claude --resume <name>`. Do đó, phiên có tên `auth-deep-dive` có thể được tiếp tục trực tiếp với `--resume auth-deep-dive`. Thay vào đó, `--continue` tải cuộc hội thoại gần đây nhất trong thư mục hiện tại, do đó, nó sẽ không chọn cuộc điều tra xác thực trước đó một cách đáng tin cậy.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-93', 'cca-f', 93, 'You are developing developer-productivity tools with the Claude Agent SDK. The agent assists engineers in exploring unfamiliar codebases, understanding legacy systems, generating boilerplate code, and automating repetitive work. It uses the built-in tools (Read, Write, Bash, Grep, Glob) and integrates with Model Context Protocol (MCP) servers.  
  
An engineer asks the agent to locate every caller of a function before it is removed. The function is defined in a core library, but it is also exposed through wrapper modules that rename the function for domain-specific usage (for example, `calculateTax` in the library becomes `computeOrderTax` in the orders module).  
  
Which exploration strategy will most reliably identify all callers?', '[{"key":"A","text":"Search for the function name in project documentation to understand intended usage patterns and navigate to documented integration points."},{"key":"B","text":"Use Grep to find all files that import from the library or wrapper modules, then read each file to check whether it uses the function."},{"key":"C","text":"Use Grep to search for the function''s original name across the codebase."},{"key":"D","text":"Read the library and wrapper modules to identify all exposed names for the function, then Grep for each name across the codebase."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Tất cả tên công khai đề cập đến cùng một cách triển khai phải được xác định trước khi tìm kiếm cách sử dụng. Mô-đun trình bao bọc có thể đổi tên hàm, do đó, việc tìm kiếm giới hạn ở mã định danh ban đầu có thể bỏ sót người gọi bằng bí danh dành riêng cho tên miền. Đọc thư viện và trình bao bọc để liệt kê các tên được hiển thị, sau đó là tìm kiếm trên toàn cơ sở mã cho từng tên, bao gồm các trang web gọi trực tiếp và dựa trên trình bao bọc.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-94', 'cca-f', 94, 'You are developing a structured data-extraction system with Claude. The system extracts information from unstructured documents, validates the output with JavaScript Object Notation (JSON) schemas, and maintains high accuracy. It must gracefully handle edge cases and integrate with downstream systems.  
  
Your extraction pipeline processes restaurant menus and must produce structured JSON containing item names, descriptions, prices, and dietary tags. Some menus have inconsistent formatting—for example, prices may appear as "$12" or "12.00", and dietary information may be represented by icons or text.  
  
What is the most reliable approach?', '[{"key":"A","text":"Define a strict output schema and include format normalization rules in your prompt."},{"key":"B","text":"Extract data as-is and normalize formats in post-processing code after Claude returns."},{"key":"C","text":"Use separate extraction calls for each field to ensure consistent handling of each type."},{"key":"D","text":"Request multiple extraction attempts per document and select the most common format."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Lược đồ đầu ra nghiêm ngặt thực thi các trường và loại JSON bắt buộc, đồng thời các quy tắc chuẩn hóa rõ ràng trong lời nhắc trích xuất sẽ thiết lập một cách trình bày chuẩn cho các dữ liệu đầu vào không nhất quán như giá cả và nhãn chế độ ăn uống. Điều này tạo ra dữ liệu đã được xác thực, sẵn sàng xuôi dòng tại điểm trích xuất.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-95', 'cca-f', 95, 'You are developing a structured data-extraction system with Claude. The system pulls information from unstructured documents, validates output with JavaScript Object Notation (JSON) schemas, and preserves high accuracy. It must gracefully handle edge cases and integrate with downstream systems.  
  
Your system has operated with 100% human review for 3 months. Analysis indicates that extractions with model confidence ≥90% achieve 97% accuracy overall. To lower reviewer workload, you intend to automate high-confidence extractions.  
  
Before deployment, which validation step is most critical?', '[{"key":"A","text":"Verify that 97% accuracy meets requirements for all downstream systems that consume the extracted data."},{"key":"B","text":"Analyze accuracy by document type and field to verify high-confidence extractions perform consistently across all segments, not just in aggregate."},{"key":"C","text":"Compare accuracy at different confidence thresholds (85%, 90%, 96%) to find the optimal cutoff that maximizes automation while minimizing errors."},{"key":"D","text":"Run a two-week pilot routing 25% of high-confidence extractions directly to downstream systems and monitor error reports."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Độ chính xác tổng hợp không chứng minh được rằng ngưỡng tin cậy là đáng tin cậy cho mọi loại tài liệu, trường được trích xuất và phân đoạn trường hợp biên. Tỷ lệ tổng thể cao có thể che giấu các lỗi tập trung trong một phân đoạn mà các hệ thống hạ nguồn có thể phụ thuộc vào, do đó, hiệu suất phải được đánh giá bởi các phân đoạn đó trước khi tự động hóa các đầu ra có độ tin cậy cao. Hướng dẫn đánh giá của Anthropic nhấn mạnh vào việc thử nghiệm trên các tình huống và xem xét kết quả qua các trường hợp thử nghiệm để tìm ra các mẫu hiệu suất.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-96', 'cca-f', 96, 'You are developing a structured-data extraction system with Claude. The system pulls information from unstructured documents, validates its output with JavaScript Object Notation (JSON) schemas, and preserves high accuracy. It must manage edge cases gracefully and integrate with downstream systems.  
  
Your schema contains a `skills: string[]` field. Production monitoring identifies three consistency problems:  
  
1. Compound phrases such as "Python and SQL" are sometimes retained as a single entry and sometimes split.  
2. Implied but unmentioned skills occasionally appear in extracted results.  
3. Similar documents yield dramatically different array lengths (5–10 versus 40+ entries).  
  
Your prompt currently states, "Extract all skills mentioned."  
  
What is the most effective improvement?', '[{"key":"A","text":"Add few-shot examples demonstrating compound phrase handling, explicit mention criteria, and appropriate entry granularity."},{"key":"B","text":"Add post-extraction normalization that maps skills to a canonical taxonomy and deduplicates similar entries."},{"key":"C","text":"Enrich the schema to `{skill: string, confidence: float, source_quote: string}[]` to capture extraction metadata."},{"key":"D","text":"Add constraints: \"Extract 10-20 skills maximum, one skill per entry, only explicitly named skills.\""}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các ví dụ Few-shot thiết lập chính sách trích xuất dự định bằng cách hiển thị cách trình bày các kỹ năng kết hợp, yêu cầu đề cập bằng văn bản rõ ràng và minh họa mức độ chi tiết mục nhập thích hợp. Các ví dụ đa dạng, có liên quan—bao gồm cả các trường hợp đặc biệt—cải thiện độ chính xác và tính nhất quán trong trích xuất của Claude một cách đáng tin cậy hơn so với chỉ một hướng dẫn mơ hồ. Số lượng tối đa tùy ý không xác định ranh giới trích xuất chính xác và có thể loại trừ các kỹ năng hợp lệ.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-97', 'cca-f', 97, 'You are developing a structured data-extraction system using Claude. The system pulls information from unstructured documents, validates its output with JavaScript Object Notation (JSON) schemas, and preserves high accuracy. It must gracefully handle edge cases and integrate with downstream systems.  
  
Your system extracts event metadata (date, location, organizer, attendee_count) from news articles by using a JSON schema in which every field is nullable. During evaluation, you find that the model often produces plausible but incorrect values for fields that are not mentioned in the article—for example, returning "500" for attendee_count when the source has no attendance information.  
  
What is the most effective approach to reduce these false extractions?', '[{"key":"A","text":"Add prompt instructions to return null for any field where information is not directly stated in the source."},{"key":"B","text":"Make all schema fields required (non-nullable) with strict validation rules to ensure the model only outputs verifiable data."},{"key":"C","text":"Add a post-processing step using a second LLM call to verify each extracted value exists in the source document."},{"key":"D","text":"Upgrade to a more capable model tier with improved instruction-following to reduce hallucination tendencies."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Một hướng dẫn rõ ràng để trả về `null` bất cứ khi nào nguồn không nêu trực tiếp giá trị trường sẽ thiết lập quy tắc bỏ phiếu trắng đối với bằng chứng bị thiếu và sử dụng lược đồ có thể rỗng như dự định. Điều này làm giảm các trích xuất không được hỗ trợ mà không buộc phải tạo ra giá trị khác null. Anthropic khuyến nghị hạn chế Claude trong phạm vi thông tin có trong tài liệu được cung cấp và cho phép Claude thể hiện sự không chắc chắn để giảm ảo giác.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-98', 'cca-f', 98, 'You are developing a structured data-extraction system with Claude. The system pulls information from unstructured documents, validates its output with JavaScript Object Notation (JSON) schemas, and preserves high accuracy. It must gracefully handle edge cases and integrate with downstream systems.  
  
Your system has operated for 3 weeks, and human reviewers have corrected 847 extractions. Analysis identifies a recurring pattern: when recipes contain informal measurements such as “a handful” or “a splash,” the model either fabricates specific quantities or leaves fields blank—representing 23% of all corrections.  
  
How should this feedback be used to improve extraction accuracy?', '[{"key":"A","text":"Update your JSON schema to add a \"measurement_type\" enum field (precise/informal)."},{"key":"B","text":"Implement a post-processing layer that uses pattern matching to detect informal measurement phrases in source text and automatically populate values when the extraction is empty."},{"key":"C","text":"Add few-shot examples to your prompt demonstrating correct handling of informal measurements – extracting them verbatim rather than converting or omitting them."},{"key":"D","text":"Fine-tune the model on the 847 corrected extractions."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các ví dụ Few-shot cho thấy các phép đo không chính thức được trích xuất nguyên văn cung cấp sự điều chỉnh trực tiếp, có mục tiêu cho mẫu lỗi được quan sát trong khi vẫn lưu giữ thông tin nguồn. Hướng dẫn nhắc nhở của Anthropic nêu rõ rằng các ví dụ đa dạng, phù hợp sẽ cải thiện độ chính xác và tính nhất quán, đặc biệt là khi chúng bao gồm các trường hợp khó khăn.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-99', 'cca-f', 99, 'You are creating a structured-data extraction system with Claude. The system extracts information from unstructured documents, validates its output with JavaScript Object Notation (JSON) schemas, and preserves high accuracy. It must gracefully handle edge cases and integrate with downstream systems.  
  
Your pipeline uses a tool named `extract_metadata` with a JSON schema for paper details. You have also defined `lookup_citations` and `verify_doi` tools for enrichment. During testing, you observe that when users make requests such as “extract the metadata and tell me how cited it is,” Claude sometimes calls `lookup_citations` first, which fails because it requires the DOI that `extract_metadata` would supply.  
  
What is the most effective way to ensure structured metadata extraction occurs first?', '[{"key":"A","text":"Set `tool_choice` to `{\"type\": \"tool\", \"name\": \"extract_metadata\"}` for every API call in the pipeline, ensuring Claude always extracts metadata before any enrichment can occur."},{"key":"B","text":"Set `tool_choice` to `{\"type\": \"tool\", \"name\": \"extract_metadata\"}` and process the enrichment requests in subsequent turns after receiving the extracted metadata."},{"key":"C","text":"Set `tool_choice` to `\"auto\"` and reorder the tool definitions so `extract_metadata` appears first in the tools array, since Claude prioritizes earlier-listed tools."},{"key":"D","text":"Set `tool_choice` to `\"any\"` so Claude must use a tool, combined with system prompt instructions prioritizing `extract_metadata`."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Lựa chọn công cụ được đặt tên bắt buộc đảm bảo rằng `extract_metadata` được gọi cho yêu cầu trích xuất. Sau khi kết quả công cụ của nó cung cấp DOI, lượt tiếp theo có thể thực hiện tra cứu trích dẫn hoặc xác minh DOI với đầu vào được yêu cầu. `tool_choice` có tên áp dụng cho yêu cầu API riêng lẻ của nó, trong khi `auto` cho phép Claude chọn và `any` chỉ yêu cầu một số công cụ chứ không phải công cụ trích xuất. [Anthropic’s tool-use documentation](https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools) tuyên bố rằng `tool` buộc một công cụ cụ thể, trong khi `auto` và `any` không bắt buộc một công cụ cụ thể.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-100', 'cca-f', 100, 'You are developing a structured data-extraction system using Claude. The system extracts information from unstructured documents, validates output with JavaScript Object Notation (JSON) schemas, and preserves high accuracy. It must gracefully handle edge cases and integrate with downstream systems.  
  
Testing shows that when source documents lack certain specifications, the model invents plausible-sounding values to fulfill your schema’s required fields. For example, a document that mentions only dimensions is returned with a fabricated `"weight: 2.3 kg"` in the extraction output.  
  
Which schema-design change most effectively addresses this hallucination behavior?', '[{"key":"A","text":"Change fields that may not exist in source documents from required to optional, allowing the model to omit them"},{"key":"B","text":"Add explicit instructions to the prompt stating \"only extract information explicitly stated in the document; use placeholder text for missing values\""},{"key":"C","text":"Add a \"confidence\" field alongside each specification where the model self-reports its certainty, then filter out low-confidence extractions"},{"key":"D","text":"Implement semantic validation that verifies each extracted value appears in or can be inferred from the source document text"}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các thông số kỹ thuật có thể không có trong tài liệu nguồn phải là tùy chọn thay vì bắt buộc. Điều này cho phép đầu ra trích xuất bỏ qua thông tin không có sẵn thay vì buộc mô hình chỉ tạo ra một giá trị hợp lý để đáp ứng xác thực lược đồ.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-101', 'cca-f', 101, 'You are developing a structured data-extraction system using Claude. The system pulls information from unstructured documents, validates outputs with JavaScript Object Notation (JSON) schemas, and preserves high accuracy. It must gracefully handle edge cases and integrate with downstream systems.  
  
Your extraction pipeline validates outputs against JSON schemas, but limited reviewer capacity means human reviewers can handle approximately 5% of the total extraction volume.  
  
What is the most effective basis for choosing which extractions to send for human review?', '[{"key":"A","text":"Randomly sample 5% of extractions for review."},{"key":"B","text":"Route extractions where the model indicates low confidence or where source documents contain ambiguous or contradictory information."},{"key":"C","text":"Route extractions for review only when downstream systems report data quality issues or processing failures."},{"key":"D","text":"Route extractions containing specific high-priority entity types (e.g., financial figures, dates) for human review, regardless of extraction confidence."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc đánh giá của con người có giá trị nhất khi hướng tới các hồ sơ có rủi ro trích xuất không chính xác được ước tính cao nhất. Độ tin cậy của mô hình thấp và tài liệu nguồn không rõ ràng hoặc mâu thuẫn là những chỉ báo trực tiếp về sự không chắc chắn, do đó, việc định tuyến các mục đó sẽ tập trung khả năng xem xét hạn chế vào các trường hợp mà nó có thể cải thiện độ chính xác nhất và giải quyết các trường hợp khó khăn một cách an toàn.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-102', 'cca-f', 102, 'You are developing a structured data-extraction system with Claude. The system pulls information from unstructured documents, validates its output with JavaScript Object Notation (JSON) schemas, and preserves high accuracy. It must gracefully handle edge cases and integrate with downstream systems.  
  
The system must extract candidate information—name, contact details, skills, work experience, and education—from uploaded resumes. The extracted data must strictly conform to a predefined JSON schema, because missing required fields or incorrect data types will cause downstream validation failures.  
  
What is the most dependable approach for ensuring Claude’s output consistently conforms to the schema?', '[{"key":"A","text":"Make two separate API calls – first extracting information as text, then asking Claude to format that text as JSON."},{"key":"B","text":"Define a tool with an input schema matching your required JSON structure and extract the data from Claude''s tool_use response."},{"key":"C","text":"Parse Claude''s text response with regex patterns to extract JSON objects, using retry logic for malformed responses."},{"key":"D","text":"Include detailed JSON formatting instructions and a template example in the system prompt, asking Claude to output only valid JSON."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Claude tool use chấp nhận `input_schema` được biểu thị dưới dạng Lược đồ JSON và trả về các đối số công cụ trong khối `tool_use`. Việc xác định lược đồ đó cho bản ghi ứng cử viên sẽ cung cấp tải trọng trích xuất có cấu trúc để ứng dụng sử dụng, tránh việc phân tích cú pháp dễ vỡ của văn bản mô hình dạng tự do.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-103', 'cca-f', 103, 'You are developing a structured-data extraction system with Claude. The system pulls information from unstructured documents, validates its output with JavaScript Object Notation (JSON) schemas, and maintains high accuracy. It must gracefully handle edge cases and integrate with downstream systems.  
  
The system sends documents with extraction confidence below 85% for human review. A quarterly audit finds that 12% of high-confidence extractions (≥85%) also contain errors, in which the model identifies plausible but incorrect values. Sources of error differ: comparison tables that display competitor specifications, appendices that refer to other product variants, and ambiguous wording that the model misunderstands. You need a sustainable method to identify these high-confidence errors and determine over time whether improvements reduce the error rate.  
  
What approach is most effective?', '[{"key":"A","text":"Add a verification pass that re-extracts from each high-confidence document, flagging cases where the two extraction attempts produce different results"},{"key":"B","text":"Lower the confidence threshold from 85% to 70%, routing a larger volume of extractions to human review."},{"key":"C","text":"Implement stratified random sampling reviewing a fixed percentage of high-confidence extractions weekly, enabling error rate measurement and novel pattern detection."},{"key":"D","text":"Implement heuristic rules that flag documents containing comparison tables or appendices for review regardless of confidence score."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc lấy mẫu ngẫu nhiên phân tầng của các trích xuất có độ tin cậy cao tạo ra một tập hợp đánh giá của con người mang tính đại diện, có thể lặp lại để ước tính tỷ lệ lỗi còn lại và theo dõi tỷ lệ đó theo thời gian. Việc xem xét các mẫu đó cũng cho thấy các chế độ lỗi không được dự đoán trước bởi các quy tắc cố định, bao gồm các trích xuất hợp lý nhưng không chính xác mà việc chấm điểm độ tin cậy không nắm bắt được.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-104', 'cca-f', 104, 'You are developing a structured data-extraction system with Claude. The system pulls information from unstructured documents, validates its output with JavaScript Object Notation (JSON) schemas, and preserves high accuracy. It must gracefully handle edge cases and integrate with downstream systems.  
  
Your extraction pipeline processes invoices and extracts line items, subtotals, tax amounts, and grand totals. During evaluation, you find that in 18% of extractions, the total of extracted line-item amounts does not match the extracted grand total—sometimes because of OCR errors in the source document and sometimes because of model extraction errors. Downstream accounting systems reject records whose totals do not match.  
  
What is the most effective way to improve extraction reliability?', '[{"key":"A","text":"Add few-shot examples demonstrating invoices where extracted line items sum correctly to the stated total, encouraging the model to produce mathematically consistent extractions."},{"key":"B","text":"Add a \"calculated-total\" field where the model sums extracted line items alongside a \"stated_total\" field. Flag records for human review when values differ."},{"key":"C","text":"Extract line items and totals independently, then use a separate validation model to reconcile discrepancies by determining which extracted values are most likely correct."},{"key":"D","text":"Implement post-processing that automatically adjusts line item amounts proportionally when their sum doesn''t match the stated total."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Có thể so sánh tổng số được tính toán xác định từ các mục hàng được trích xuất với tổng số được nêu riêng được trích xuất. Việc giữ lại cả giá trị và sự khác biệt về định tuyến để con người đánh giá sẽ phát hiện cả lỗi OCR và lỗi trích xuất trong khi bảo toàn bằng chứng nguồn và tránh các điều chỉnh tài chính bịa đặt trước khi hồ sơ đến hệ thống kế toán.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-105', 'cca-f', 105, 'You are developing a structured data-extraction system with Claude. The system extracts information from unstructured documents, validates output with JavaScript Object Notation (JSON) schemas, and maintains high accuracy. It must gracefully handle edge cases and integrate with downstream systems.  
  
Your extraction pipeline processes contracts that commonly include amendments. When a contract contains both original terms and later amendments (e.g., an original clause specifies "30-day payment terms" while Amendment 1 changes this to "45 days"), the model inconsistently extracts either value without indicating which one applies.  
  
What is the most effective approach for improving extraction accuracy for documents containing amendments?', '[{"key":"A","text":"Preprocess documents with a classifier that identifies and removes superseded sections before the main extraction step."},{"key":"B","text":"Implement post-extraction validation using pattern matching to detect amendments and flag those extractions for manual review"},{"key":"C","text":"Redesign the schema so amended fields capture multiple values, each with source location and effective date."},{"key":"D","text":"Add prompt instructions to always extract the most recent amendment value and ignore superseded original terms."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các hợp đồng sửa đổi yêu cầu trình bày cả điều khoản ban đầu và điều khoản đã sửa đổi, cùng với bối cảnh xuất xứ và thời gian. Việc thu thập nhiều giá trị trường cùng với vị trí nguồn và ngày hiệu lực của chúng sẽ lưu giữ lịch sử sửa đổi, hỗ trợ xác định điều khoản áp dụng và cung cấp đầu ra có cấu trúc có thể kiểm tra được cho các hệ thống hạ nguồn. Khả năng trích dẫn của Claude hỗ trợ trả về vị trí nguồn cho các phát biểu được trích xuất từ ​​tài liệu được cung cấp.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-106', 'cca-f', 106, 'You are developing a structured data-extraction system with Claude. The system pulls information from unstructured documents, validates its output with JavaScript Object Notation (JSON) schemas, and preserves high accuracy. It must gracefully handle edge cases and integrate with downstream systems.  
  
Monitoring indicates that 12% of extractions fail Pydantic validation with specific errors such as "expected float for quantity, got ''2 to 3''". Retrying these requests unchanged results in the same failures.  
  
What is the most effective method to recover from these validation failures?', '[{"key":"A","text":"Send a follow-up request including the validation error, asking the model to correct its output"},{"key":"B","text":"Implement a secondary pipeline using a larger model tier to reprocess documents that fail validation"},{"key":"C","text":"Pre-process source documents to standardize problematic formats before sending them for extraction"},{"key":"D","text":"Set temperature to 0 to eliminate output variability and ensure consistent formatting"}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Phản hồi về lỗi xác thực cung cấp cho mô hình ràng buộc bị vi phạm chính xác và cho phép mô hình sửa kết quả đầu ra có cấu trúc trước đó. Việc thử lại không thay đổi không có khả năng khắc phục được lỗi diễn giải hoặc loại xác định, chẳng hạn như trả về một phạm vi số lượng trong đó lược đồ yêu cầu số float.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-107', 'cca-f', 107, 'You are developing a structured-data extraction system with Claude. The system pulls information from unstructured documents, validates its output with JavaScript Object Notation (JSON) schemas, and preserves high accuracy. It must gracefully handle edge cases and integrate with downstream systems.  
  
Your system needs to extract event details from calendar invitations and produce JSON that strictly conforms to a schema containing fields for title, date, time, location, and attendees. Downstream systems reject any malformed or non-conformant JSON.  
  
Which approach delivers the most reliable schema compliance?', '[{"key":"A","text":"Include detailed JSON formatting instructions and the target schema in your prompt, then parse Claude''s text response as JSON."},{"key":"B","text":"Define a tool with your target schema as input parameters and have Claude call it with the extracted data."},{"key":"C","text":"Append instructions like \"Output only valid JSON matching the schema exactly\" and implement retry logic to re-prompt when JSON parsing fails."},{"key":"D","text":"Pre-fill Claude''s response with an opening brace to force JSON output, then complete and parse the response."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Định nghĩa công cụ chấp nhận `input_schema` được biểu thị dưới dạng Lược đồ JSON, do đó, Claude trả về các trường được trích xuất dưới dạng đầu vào của công cụ có cấu trúc thay vì dựa vào việc tạo văn bản không bị ràng buộc. Điều này đáng tin cậy hơn đối với các hệ thống hạ nguồn yêu cầu JSON tuân thủ lược đồ hơn là nhắc, phân tích cú pháp, thử lại hoặc điền trước đầu ra văn bản.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-108', 'cca-f', 108, 'You are developing a structured data-extraction system using Claude. The system extracts information from unstructured documents, validates output with JavaScript Object Notation (JSON) schemas, and maintains high accuracy. It must gracefully handle edge cases and integrate with downstream systems.  
  
Your extraction uses tool use with a JSON schema in which `property_type` is defined as an enum: `[''house'', ''apartment'', ''condo'', ''townhouse'']`. After deployment, 8% of extractions fail schema validation. Investigation shows that listings mention many uncommon property types—"studio", "loft", "duplex", "mobile home", "tiny house", "converted warehouse"—and new types continue to appear regularly.  
  
What is the most effective long-term solution?', '[{"key":"A","text":"Continuously expand the enum to include newly observed property types and add monitoring for additional edge cases."},{"key":"B","text":"Change `property_type` from an enum to a free-form string and implement a normalization step in post-processing."},{"key":"C","text":"Add an \"other\" value to your enum with a separate `property_type_detail` string field for specifics when \"other\" is selected."},{"key":"D","text":"Add few-shot examples to your prompt demonstrating how to map unexpected property types to the closest existing enum value."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Giá trị enum `other` với trường chi tiết đi kèm giữ `property_type` trong một tập hợp ổn định, hợp lệ theo lược đồ cho người tiêu dùng tiếp theo trong khi vẫn duy trì loại thuộc tính cụ thể không được nhận dạng. Điều này xử lý một tập hợp các giá trị hợp pháp có kết thúc mở, đang phát triển mà không buộc phải ánh xạ không chính xác hoặc liên tục mở rộng enum được kiểm soát. Các lược đồ công cụ Claude xác định hình dạng đầu vào có cấu trúc dự kiến, do đó thiết kế này vẫn giữ được các lợi ích của đầu ra bị ràng buộc bởi lược đồ trong khi vẫn đáp ứng được các trường hợp biên.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-109', 'cca-f', 109, 'You are developing a structured data-extraction system with Claude. The system pulls information from unstructured documents, validates its output with JavaScript Object Notation (JSON) schemas, and preserves high accuracy. It must gracefully manage edge cases and integrate with downstream systems.  
  
Your extraction system uses `tool_use` with a JSON schema that has 12 fields and detailed descriptions, totaling about 2,500 tokens for the full tool definition. Processing documents below 150K tokens achieves 98% accuracy. For documents from 175–190K tokens, accuracy falls to 71%, and information in the final third is consistently missed. The model has a 200K-token context window.  
  
What is the most likely cause?', '[{"key":"A","text":"The model distributes attention proportionally across input length, causing fields mentioned only once near the document''s end to receive insufficient processing focus."},{"key":"B","text":"Very long documents exceed the model''s effective attention span regardless of context limits, causing accuracy degradation for content farther from the prompt instructions."},{"key":"C","text":"Schemas exceeding 8-10 fields increase decision complexity during parameter generation, reducing extraction accuracy independent of document length."},{"key":"D","text":"Tool definitions consume input context tokens. Combined with system prompts and document content, the total approaches the context limit, degrading end-of-document processing."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Định nghĩa công cụ—bao gồm tên, mô tả và lược đồ—là mã thông báo đầu vào và Claude cũng thêm mã thông báo nhắc hệ thống sử dụng công cụ. Các mã thông báo đó, cùng với các hướng dẫn hệ thống, nội dung tài liệu và đầu ra được tạo, sẽ tiêu tốn dung lượng ngữ cảnh hữu hạn của mô hình. Do đó, một tài liệu dài có thể đạt đến giới hạn 200K mã thông báo ngay cả khi chỉ riêng mã thông báo tài liệu của nó xuất hiện dưới ngưỡng đó, khiến thông tin tài liệu đến muộn có khả năng bị mất hoặc bị cắt bớt một cách không tương xứng.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-110', 'cca-f', 110, 'You are creating a structured data-extraction system with Claude. The system extracts information from unstructured documents, validates its output with JavaScript Object Notation (JSON) schemas, and preserves high accuracy. It must gracefully handle edge cases and integrate with downstream systems.  
  
After the daily batch of 10,000 documents finishes, 300 documents (3%) fail with `context_length_exceeded` errors. The results file identifies every failed item by `custom_id`.  
  
What is the most cost-effective way to process these failures?', '[{"key":"A","text":"Resubmit only the 300 failed documents after chunking them into smaller pieces, then combine the partial extractions"},{"key":"B","text":"Reprocess the entire batch with prompt caching enabled to reduce the cost of retrying requests with identical system prompts"},{"key":"C","text":"Increase the max_tokens parameter for the 300 failed documents and resubmit them in a new batch"},{"key":"D","text":"Resubmit the entire 10,000 document batch using a model tier with a larger context window"}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Lỗi về độ dài ngữ cảnh được giải quyết bằng cách giảm kích thước của từng yêu cầu bị ảnh hưởng, chẳng hạn như bằng cách chia nhỏ các tài liệu bị lỗi và kết hợp việc trích xuất một phần của chúng. Chỉ gửi lại các yêu cầu được xác định bởi `custom_id` sẽ tránh xử lý lại 9.700 tài liệu thành công. Việc tăng `max_tokens` không thu hẹp ngữ cảnh quá khổ, trong khi prompt caching chỉ giảm chi phí cho nội dung lời nhắc có thể sử dụng lại và tầng mô hình ngữ cảnh lớn hơn có thể phải chịu thêm chi phí ngữ cảnh dài.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-111', 'cca-f', 111, 'You are creating a structured data-extraction system with Claude. The system extracts information from unstructured documents, validates output with JavaScript Object Notation (JSON) schemas, and maintains high accuracy. It must gracefully handle edge cases and integrate with downstream systems.  
  
Your extraction system handles two document types: standard monthly reports, which are archived after processing, and urgent exception reports, which must trigger business alerts within 30 minutes of receipt. Both use the same JSON schema. You want to minimize API costs while satisfying latency requirements.  
  
How should you design the processing pipeline?', '[{"key":"A","text":"Submit all documents to the Batch API with custom_ids for tracking. When results arrive, immediately process urgent documents and trigger delayed alerts for exceptions."},{"key":"B","text":"Queue all documents and submit hourly batches, flagging urgent documents for expedited handling when batch results return."},{"key":"C","text":"Submit all documents to the real-time Messages API to ensure consistent processing latency across document types."},{"key":"D","text":"Route standard reports to the Batch API for 50% cost savings, and route urgent exception reports to the real-time Messages API."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }API hàng loạt của Anthropic được thiết kế để xử lý không đồng bộ, không nhạy cảm về thời gian và cung cấp mức giảm giá 50% cho cả mã thông báo đầu vào và đầu ra. Báo cáo tiêu chuẩn hàng tháng có thể sử dụng nó để giảm chi phí. Báo cáo ngoại lệ khẩn cấp phải được xử lý thông qua API tin nhắn theo thời gian thực để việc tạo cảnh báo có thể đáp ứng yêu cầu 30 phút.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-112', 'cca-f', 112, 'You are developing a structured data-extraction system with Claude. The system extracts information from unstructured documents, validates its output with JavaScript Object Notation (JSON) schemas, and preserves high accuracy. It must gracefully handle edge cases and integrate with downstream systems.  
  
Your extraction system processes e-commerce product descriptions to pull specifications, such as dimensions, weight, and materials, into JSON. Although the schema is well defined, the model extracts the `"materials"` field inconsistently—sometimes returning `"cotton blend"`, at other times `"Cotton/Polyester mix"`, and occasionally leaving out the field when material information is clearly present in the source.  
  
What is the most effective method to improve extraction consistency?', '[{"key":"A","text":"Add few-shot examples showing 2-3 complete input-output pairs with standardized material description formats"},{"key":"B","text":"Switch to a more capable model tier since inconsistent extraction indicates insufficient model capability"},{"key":"C","text":"Make the \"materials\" field required instead of optional in the schema to force the model to always extract a value"},{"key":"D","text":"Set temperature to 0 to eliminate randomness and ensure deterministic outputs"}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các ví dụ Few-shot ghép văn bản sản phẩm đại diện với các giá trị tài liệu chuẩn bắt buộc sẽ dạy trực tiếp quy ước trích xuất và chuẩn hóa. Điều này giải quyết cả cách diễn đạt biến thể và các trường hợp thông tin quan trọng sẽ được đưa vào trường. Lược đồ JSON xác thực cấu trúc nhưng không thiết lập ánh xạ ngữ nghĩa từ cách diễn đạt nguồn đến giá trị được tiêu chuẩn hóa. Hướng dẫn kỹ thuật nhắc nhở của Anthropic lưu ý rằng Claude chú ý đến các ví dụ và chi tiết của chúng, vì vậy các ví dụ phải phản ánh nhất quán hành vi được khuyến khích.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-113', 'cca-f', 113, 'You are developing a structured-data extraction system using Claude. The system extracts information from unstructured documents, validates its output with JavaScript Object Notation (JSON) schemas, and maintains high accuracy. It must gracefully handle edge cases and integrate with downstream systems.  
  
After you implement tool use with strict schema definitions, JSON syntax errors are eliminated, but 5% of extractions still produce valid JSON containing empty arrays or null values for required fields such as citations and methodology. Spot checks show that the source documents contain this information, but in varied forms—inline citations versus bibliographies, and methodology sections versus details embedded in introductions.  
  
What is the most effective way to address these failures?', '[{"key":"A","text":"Build a regex-based post-processing layer that scans source documents for citation patterns and methodology keywords, populating empty fields when the model fails to extract."},{"key":"B","text":"Implement retry logic that re-sends requests when validation detects empty required fields."},{"key":"C","text":"Add few-shot examples demonstrating extractions from documents with varied structures – showing how to identify citations in different formats and locate methodology details across section types."},{"key":"D","text":"Modify your schema to make citations and methodology optional, and flag incomplete records for manual review rather than failing validation."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các ví dụ Few-shot bao gồm nhiều cấu trúc tài liệu dạy mô hình cách nhận biết các trích dẫn và phương pháp khi cùng một thông tin xuất hiện ở các định dạng hoặc phần khác nhau. Điều này giải quyết lỗ hổng trích xuất ngữ nghĩa trong khi vẫn duy trì xác thực lược đồ nghiêm ngặt để có dữ liệu xuôi dòng hoàn chỉnh, có cấu trúc đáng tin cậy.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-114', 'cca-f', 114, 'You are developing a structured data-extraction system with Claude. The system pulls information from unstructured documents, validates its output with JavaScript Object Notation (JSON) schemas, and preserves high accuracy. It must gracefully handle edge cases and integrate with downstream systems.  
  
Following deployment, you discover that 12% of extractions have semantic errors that still pass JSON schema validation (for example, a duration such as "30 minutes" is incorrectly entered in an ingredient-quantity field). Human reviewers can examine only 20% of extractions.  
  
Which approach most effectively directs reviewer attention?', '[{"key":"A","text":"Prioritize review of all extractions where required fields are empty or explicitly marked as not found."},{"key":"B","text":"Have the model output field-level confidence scores, then calibrate review thresholds using a labeled validation set."},{"key":"C","text":"Review all extractions from documents with formatting anomalies such as unusual layouts or mixed content types."},{"key":"D","text":"Randomly sample 20% of extractions for review, using corrections to track accuracy and identify error patterns."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Xác thực lược đồ JSON có thể xác minh cấu trúc của đầu ra và các loại dữ liệu được phép, nhưng nó không chứng minh được rằng giá trị hợp lệ về mặt cú pháp phù hợp về mặt ngữ nghĩa cho trường của nó. Việc hiệu chỉnh điểm tin cậy ở cấp độ trường do mô hình tạo dựa trên tập hợp xác thực được gắn nhãn làm cho những điểm đó có ý nghĩa đối với xếp hạng rủi ro, do đó, ngưỡng đánh giá có thể ưu tiên các trích xuất có nhiều khả năng chứa lỗi ngữ nghĩa nhất trong khi vẫn tôn trọng khả năng đánh giá 20%. Hướng dẫn đánh giá của Anthropic hỗ trợ sử dụng các trường hợp thử nghiệm và đánh giá chất lượng để đánh giá kết quả đầu ra và cải thiện lời nhắc.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-115', 'cca-f', 115, 'You are developing a multi-agent research system with the Claude Agent SDK. A coordinator agent delegates work to specialized subagents: one performs web searches, one analyzes documents, one synthesizes findings, and one produces reports. The system researches topics and generates comprehensive, cited reports.  
  
Production monitoring indicates that the research phase is taking longer than anticipated. Analysis shows that the coordinator calls the web-search subagent and waits for its response, then calls the document-analysis subagent and waits again. These tasks are independent—neither needs the other’s output.  
  
How should you change the system so these subagents run concurrently?', '[{"key":"A","text":"Create an async orchestration layer outside the agent that spawns parallel threads, each running a separate coordinator-subagent pair, then aggregates results."},{"key":"B","text":"Add detailed instructions to the coordinator''s system prompt explaining the performance benefits of parallel execution and requesting it invoke both subagents at the same time."},{"key":"C","text":"Switch both subagents to use a Haiku-tier model instead of Sonnet to reduce their individual execution time."},{"key":"D","text":"Structure the coordinator to emit both Task tool calls (for web search and document analysis) in a single response message rather than across separate conversation turns."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các tác vụ của công cụ độc lập hoặc tác nhân phụ có thể chạy đồng thời khi các lệnh gọi của chúng được đưa vào cùng nhau trong một phản hồi trợ lý duy nhất. Việc phát ra cả hai lệnh gọi Tác vụ trong cùng một phản hồi cho phép thời gian chạy tác nhân thực hiện công việc tìm kiếm trên web và phân tích tài liệu song song và trả về kết quả của chúng để tổng hợp sau này.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-116', 'cca-f', 116, 'You are integrating Claude Code into your Continuous Integration/Continuous Deployment (CI/CD) pipeline. The system conducts automated code reviews, generates test cases, and gives feedback on pull requests. You must design prompts that deliver actionable feedback while minimizing false positives.  
  
Your CI pipeline conducts security-focused code reviews on approximately 50 PRs each day, currently costing $150/day with the synchronous API. Reviews are non-blocking—developers merge once tests pass and address findings in follow-up commits. You are evaluating the Message Batches API for its 50% cost reduction.  
  
Which factor most determines whether batch processing is suitable for this use case?', '[{"key":"A","text":"Whether review feedback arriving up to 24 hours after PR creation remains actionable."},{"key":"B","text":"Whether your result processing can handle reviews arriving in a different order than submitted."},{"key":"C","text":"Whether you can structure each review as a single request without multi-turn refinement."},{"key":"D","text":"Whether reducing per-review latency from 30-60 seconds to near-instant matters for your workflow."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Message Batches API xử lý các yêu cầu một cách không đồng bộ; mặc dù hầu hết các lô hoàn thành trong vòng chưa đầy một giờ, quá trình xử lý có thể kéo dài cho đến hết 24 giờ. Việc xử lý hàng loạt chỉ phù hợp khi phản hồi đánh giá vẫn có thể thực hiện được sau sự chậm trễ có thể xảy ra đó. Kết quả có thể được so khớp với `custom_id` mặc dù phân phối không theo thứ tự và các yêu cầu hàng loạt hỗ trợ các cuộc hội thoại nhiều lượt.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-117', 'cca-f', 117, 'You are integrating Claude Code into your Continuous Integration/Continuous Deployment (CI/CD) pipeline. The system performs automated code reviews, generates test cases, and provides pull-request feedback. You must design prompts that deliver actionable feedback while minimizing false positives.  
  
Your pipeline runs:  
  
```  
PROMPT="You are a code reviewer."  
PROMPT="$PROMPT Analyze the provided diff"  
PROMPT="$PROMPT for bugs, security issues,"  
PROMPT="$PROMPT and style violations." claude -p \ -- dangerously-skip-permissions \ --system-prompt "$PROMPT" \ < diff.txt  
```  
  
The reviews finish and return feedback, but Claude comments only on the diff text piped in—it never reads surrounding files in the checked-out repository to gain broader context, even when the diff changes a function called by many other modules.  
  
Which invocation change will make Claude read related repository files while still applying your custom review instructions?', '[{"key":"A","text":"Replace `--system-prompt` with `--append-system-prompt` so your review instructions are added to Claude Code''s default prompt instead of overwriting the built-in guidance for using file-reading and code navigation tools."},{"key":"B","text":"Stop piping the diff via stdin and instead embed the diff contents inside the prompt string, so Claude Code treats the invocation as an agentic session rather than a stream-processing one."},{"key":"C","text":"Remove `--system-prompt` entirely and place the review instructions in a `CLAUDE.md` file at the repo root, since `--system-prompt` is incompatible with tool use under `-p`."},{"key":"D","text":"Keep `--system-prompt` and add `-allowedTools \"Read,Glob,Grep\"` so that the non-interactive `-p` mode permits file system tools that it otherwise disables."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }`--append-system-prompt` thêm hướng dẫn tùy chỉnh vào lời nhắc hệ thống mặc định của Claude Code, trong khi `--system-prompt` thay thế nó. Việc giữ lại lời nhắc mặc định sẽ duy trì hướng dẫn tích hợp của Claude Code để sử dụng các công cụ đọc tệp và điều hướng mã, cho phép kiểm tra bối cảnh kho lưu trữ trong quá trình xem xét. Anthropic ghi lại cả hai cờ cho chế độ in và phân biệt việc thêm vào lời nhắc hệ thống mặc định với việc thay thế nó.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-118', 'cca-f', 118, 'You are integrating Claude Code into your Continuous Integration/Continuous Deployment (CI/CD) pipeline. The system performs automated code reviews, generates test cases, and provides feedback on pull requests. You need to design prompts that deliver actionable feedback while minimizing false positives.  
  
Your pipeline reviews every PR with a single API call using a static prompt that contains the diff and the full text of every changed file; unchanged files are excluded. Reviews are posted asynchronously and do not block PR creation. Developers report that reviews repeatedly miss bugs involving cross-file interactions—for example, when a PR renames a function''s parameters, the review does not flag callers in unchanged files that still use the old argument order. Evaluation shows that cross-file bugs make up 35% of production incidents from reviewed PRs.  
  
What is the most effective change to your review design?', '[{"key":"A","text":"Redesign the review as a turn-limited agentic task where the model can read files and search the codebase via tools, following references to verify cross-file findings."},{"key":"B","text":"Run parallel review passes per changed file with direct dependents included in each pass, then aggregate and deduplicate findings using a final summarization call."},{"key":"C","text":"Add chain-of-thought instructions asking the model to list all external references in the diff, then reason step-by-step about how each change might affect callers in other files."},{"key":"D","text":"Use static analysis to build a dependency graph of changed code, then expand the prompt to include all files within two dependency hops of any changed file."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Một quá trình đánh giá tác nhân có giới hạn có thể sử dụng các công cụ tìm kiếm và đọc kho lưu trữ để theo dõi các ký hiệu đã thay đổi thành các tệp người gọi không thay đổi và xác thực hành vi trên nhiều tệp trước khi báo cáo phát hiện. Điều này cung cấp bối cảnh còn thiếu đằng sau các sự cố sản xuất được quan sát, trong khi giới hạn lần lượt sẽ hạn chế việc điều tra. Claude Code hỗ trợ tự động hóa không tương tác trong các đường dẫn CI và các quyền của công cụ có thể định cấu hình, bao gồm các công cụ đọc và ra lệnh, giúp thiết kế này phù hợp với quy trình đánh giá tự động.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-119', 'cca-f', 119, 'You are incorporating Claude Code into your Continuous Integration/Continuous Deployment (CI/CD) pipeline. The system performs automated code reviews, creates test cases, and gives feedback on pull requests. You must design prompts that deliver actionable feedback while minimizing false positives.  
  
A developer uses Claude Code to refactor a function during a development session. Before committing, they ask that same Claude session to review the code for issues. Later, an independent automated CI review finds several bugs that the same-session review missed.  
  
What most effectively explains this discrepancy?', '[{"key":"A","text":"The CI review uses a more specific prompt tailored for catching bugs, while the developer''s request was too general"},{"key":"B","text":"The extended session length caused the context window to fill with conversation history, leaving less room for thorough analysis"},{"key":"C","text":"The CI environment has access to the full codebase context while the local session only sees the current file"},{"key":"D","text":"Claude retains context about its prior reasoning in the session, making it less likely to question its own decisions"}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc đánh giá được thực hiện trong cùng một phiên sẽ đưa ra bối cảnh triển khai và lý do trước đó. Bối cảnh trước đó có thể gắn mô hình vào các lựa chọn của chính nó, khiến nó ít có khả năng thách thức các quyết định đó một cách độc lập và xác định các khiếm khuyết. Quá trình đánh giá CI riêng biệt bắt đầu từ bối cảnh độc lập, có thể phát hiện ra các lỗi bị bỏ sót trong quá trình tự đánh giá. Claude Code hỗ trợ tiếp tục các phiên cụ thể để duy trì bối cảnh hội thoại.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-120', 'cca-f', 120, 'You are incorporating Claude Code into your Continuous Integration/Continuous Deployment (CI/CD) pipeline. The system performs automated code reviews, creates test cases, and gives feedback on pull requests. You need to craft prompts that deliver actionable feedback while minimizing false positives.  
  
Your pipeline has a release-notes-generation step that classifies and summarizes approximately 200 commits at the end of each weekly release cycle. Each commit is presently sent as an individual Messages API call using a Sonnet-tier Claude model. The release notes are not required until the following morning (results can have approximately 12 hours of latency). Your team must lower the per-token API cost for this step while retaining the same model and prompts (with no change to model tier or output quality).  
  
Which approach meets all of these constraints?', '[{"key":"A","text":"Issue the 200 Messages API requests in parallel using concurrent connections, since concurrency lowers the per-token price charged by the API."},{"key":"B","text":"Concatenate all 200 commit messages into a single Messages API request and have the model return all summaries in one response, since fewer requests always reduces total token cost."},{"key":"C","text":"Submit the 200 requests to the Message Batches API with unique custom_ids and retrieve results once the batch ends, which applies a 50% discount to all input and output tokens."},{"key":"D","text":"Switch the summarization calls from the Sonnet-tier model to a Haiku-tier model to take advantage of Haiku''s lower per-token rates."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Anthropic của Message Batches API xử lý không đồng bộ khối lượng lớn yêu cầu và áp dụng giảm giá 50% cho cả mã thông báo đầu vào và đầu ra. Việc gửi từng cam kết dưới dạng yêu cầu hàng loạt với `custom_id` duy nhất sẽ duy trì mô hình Sonnet hiện tại và lời nhắc trong khi điều chỉnh khối lượng công việc có thể chấp nhận được kết quả bị trì hoãn.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-121', 'cca-f', 121, 'You are integrating Claude Code into your Continuous Integration/Continuous Deployment (CI/CD) pipeline. The system performs automated code reviews, creates test cases, and gives feedback on pull requests. You need to design prompts that deliver actionable feedback while minimizing false positives.  
  
After deploying automated code review, developers report that roughly 35% of flagged findings are false positives with recurring patterns: style recommendations conflict with team conventions, security warnings concern patterns that are safe in your deployment context, and performance recommendations would harm your particular use case. You want to lower false positives while retaining the ability to identify genuine issues.  
  
Which approach best allows the model to generalize its judgment to new code patterns it has not encountered before?', '[{"key":"A","text":"Create a comprehensive written specification of all patterns that should not be flagged, then include this full documentation in the system prompt."},{"key":"B","text":"Implement post-processing that uses keyword matching to filter out findings containing terms like \"convention,\" \"context-dependent,\" or \"trade-off.\""},{"key":"C","text":"Include few-shot examples in your prompt showing annotated code snippets that distinguish acceptable patterns from genuine issues in each category."},{"key":"D","text":"Add instructions to your system prompt to \"be conservative,\" \"only flag definite issues,\" and \"consider that some patterns may be intentional.\""}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các ví dụ Few-shot với mã có vấn đề và có thể chấp nhận được chú thích sẽ dạy cho mô hình ranh giới quyết định theo ngữ cảnh cho từng danh mục đánh giá. Các ví dụ đa dạng, phù hợp sẽ cải thiện độ chính xác và tính nhất quán, cho phép mô hình áp dụng những điểm khác biệt đã học được vào các mẫu tương tự chưa được nhìn thấy thay vì chỉ đơn thuần loại bỏ các phạm trù phát hiện rộng lớn.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-122', 'cca-f', 122, 'You are integrating Claude Code into your Continuous Integration/Continuous Deployment (CI/CD) pipeline. The system performs automated code reviews, creates test cases, and gives feedback on pull requests. You need to design prompts that give actionable feedback and reduce false positives.  
  
Your automated review produces many findings per PR, but developer feedback indicates that about half are dismissed as “not worth addressing.” Analysis shows that dismissed findings are frequently technically accurate, but concern minor style preferences or patterns that are acceptable in your codebase.  
  
Before introducing infrastructure complexity, which prompt-design change would most effectively reduce dismissals while preserving detection of genuine issues?', '[{"key":"A","text":"Add explicit criteria defining which issues to report (bugs, security) versus skip (minor style, local patterns)"},{"key":"B","text":"Add instructions asking Claude to rate each finding''s confidence (1-10) and only include findings rated 8 or higher"},{"key":"C","text":"Append instructions to \"only report findings you are highly confident are genuine problems\""},{"key":"D","text":"Implement a secondary classification model that filters Claude''s findings based on predicted developer acceptance"}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các tiêu chí báo cáo rõ ràng và bỏ qua sẽ điều chỉnh kết quả đánh giá phù hợp với định nghĩa của nhóm về một vấn đề có thể xử lý được. Chúng tiếp tục báo cáo các lỗi và vấn đề bảo mật trong khi loại trừ các tùy chọn kiểu có giá trị về mặt kỹ thuật nhưng không thể thực hiện được và các mẫu cục bộ được chấp nhận. Hướng dẫn Claude Code hỗ trợ xác định các tiêu chuẩn mã hóa, tiêu chí đánh giá và quy tắc dành riêng cho dự án để tùy chỉnh hành vi đánh giá.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-123', 'cca-f', 123, 'You are integrating Claude Code into your Continuous Integration/Continuous Deployment (CI/CD) pipeline. The system performs automated code reviews, generates test cases, and gives feedback on pull requests. You need to design prompts that deliver actionable feedback and reduce false positives.  
  
Your test-generation process creates unit tests for new code, but reviews show that 55% are low-value: trivial assertions that merely confirm functions do not throw exceptions, tests that duplicate existing coverage, or tests that disregard your team’s fixture conventions.  
  
How can you reduce the rate of low-value tests being generated in the first place?', '[{"key":"A","text":"Document testing standards in CLAUDE.md including valuable test criteria, available fixtures with intended use cases, and examples distinguishing meaningful behavioral tests from trivial assertions."},{"key":"B","text":"Restrict test generation to directories where historical quality metrics show higher acceptance rates, disabling it for areas where generated tests consistently require heavy editing."},{"key":"C","text":"Implement a two-phase generation where a second Claude call scores each test against quality criteria, filtering out low-scoring tests before presenting results to developers."},{"key":"D","text":"Add post-generation coverage analysis that automatically filters out any generated test that doesn''t increase line coverage beyond what existing tests provide."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Kho lưu trữ `CLAUDE.md` cung cấp các hướng dẫn được chia sẻ, dành riêng cho dự án mà Claude Code tải dưới dạng ngữ cảnh. Việc ghi lại các tiêu chí chất lượng thử nghiệm cụ thể, các thiết bị cố định đã được phê duyệt và mục đích sử dụng của chúng cũng như các ví dụ về các thử nghiệm hành vi có ý nghĩa sẽ cung cấp cho mô hình hướng dẫn cần thiết để tránh các thử nghiệm tầm thường, trùng lặp hoặc vi phạm quy ước trong quá trình tạo. Anthropic khuyên bạn nên sử dụng `CLAUDE.md` để có hướng dẫn dự án được chia sẻ theo nhóm cũng như hướng dẫn cụ thể về các quy ước và quy trình làm việc.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-124', 'cca-f', 124, 'You are integrating Claude Code into a Continuous Integration/Continuous Deployment (CI/CD) pipeline. The system performs automated code reviews, generates test cases, and gives feedback on pull requests. You need to design prompts that deliver actionable feedback while minimizing false positives.  
  
During initial testing of the automated review pipeline, you find that reviews of large PRs (50+ changed files) sometimes require more than 20 minutes and cost $8-12 per run because of extensive agentic loops – Claude reads files, runs analysis tools, and iterates repeatedly. Your team requires each invocation to abort when it reaches a fixed iteration count and a fixed dollar amount, enforced by Claude Code itself rather than by the surrounding job runner.  
  
Which configuration change directly enforces both per-invocation caps?', '[{"key":"A","text":"Set `--permission-mode dontAsk` to auto-deny any tool permission requests not in the explicitly allowed set."},{"key":"B","text":"Add `--max-turns 10 --max-budget-usd 2.00` to the `claude -p` invocation to cap iterations and spend."},{"key":"C","text":"Switch the `--model` flag to a smaller, cheaper model so each iteration uses fewer tokens and lower per-call cost."},{"key":"D","text":"Set `timeout-minutes: 5` on the GitHub Actions job step and monitor per-run costs via the Anthropic Console usage dashboard."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Trong chế độ in Claude Code, `--max-turns` giới hạn số lần quay và thoát tác nhân khi đạt đến giới hạn đó, trong khi `--max-budget-usd` đặt mức chi tiêu lệnh gọi API tối đa trước khi dừng thực thi. Việc áp dụng cả hai cờ cho cùng một lệnh gọi `claude -p` sẽ thực thi giới hạn số lần lặp và đô la trong Claude Code.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-125', 'cca-f', 125, 'You are integrating Claude Code into your Continuous Integration/Continuous Deployment (CI/CD) pipeline. The system performs automated code reviews, generates test cases, and provides feedback on pull requests. You need to design prompts that give actionable feedback and minimize false positives.  
  
The automated review repeatedly flags patterns that your team intentionally uses—force-unwrapping optionals in test files, using large coordinator classes that follow your established architecture, and importing internally maintained modules marked as deprecated in the public SDK. Developers dismiss approximately 30% of all findings as project-specific false positives.  
  
Which approach prevents the model from producing these findings in the first place by providing the project’s conventions as persistent context on every review?', '[{"key":"A","text":"Have developers add inline suppress-comments at flagged lines and preprocess diffs to exclude suppressed lines before sending code to the model."},{"key":"B","text":"Build post-processing keyword filters that suppress findings containing terms like \"force unwrap,\" \"large class,\" or \"deprecated import\" before results reach developers."},{"key":"C","text":"Document the team''s accepted patterns and intentional conventions in the project''s CLAUDE.md file so the model receives this context during every review."},{"key":"D","text":"Configure the review to analyze only the changed lines in the diff without surrounding file context, reducing the amount of code the model evaluates per review."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }`CLAUDE.md` cấp dự án cung cấp các hướng dẫn dùng chung, chẳng hạn như tiêu chuẩn mã hóa, tiêu chí đánh giá, quy tắc dành riêng cho dự án và các mẫu ưa thích, dưới dạng bối cảnh dự án liên tục. Việc ghi lại các quy ước có chủ ý được chấp nhận ở đó cho phép Claude Code phân biệt chúng với các vấn đề thực sự trước khi tạo ra kết quả đánh giá.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-126', 'cca-f', 126, 'You are incorporating Claude Code into your Continuous Integration/Continuous Deployment (CI/CD) pipeline. The system performs automated code reviews, produces test cases, and gives feedback on pull requests. You must design prompts that deliver actionable feedback while minimizing false positives.  
  
Your automated review CI jobs require 18 seconds to initialize before Claude starts analyzing code. Profiling shows that the delay results from auto-discovery of hooks, MCP servers, plugins, skills, and multiple nested CLAUDE.md files across your monorepo. You need to reduce startup time while ensuring reviews continue to enforce your team''s coding standards, which are documented in your root-level CLAUDE.md file.  
  
What is the most effective approach?', '[{"key":"A","text":"Replace the default prompt entirely using --system-prompt-file ./CLAUDE.md, which bypasses default prompt assembly and loads only your project rules."},{"key":"B","text":"Run with --bare mode and pass --append-system-prompt-file ./CLAUDE.md to explicitly load your project standards while skipping all auto-discovery."},{"key":"C","text":"Run with --bare mode and specify all review criteria directly in the -p prompt argument for each CI invocation, without referencing any external files."},{"key":"D","text":"Keep the default initialization and add --exclude-dynamic-system-prompt-sections to reduce per-machine prompt variability and improve prompt cache hit rates across runners."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Chế độ `--bare` của Claude Code bỏ qua tính năng tự động phát hiện các hook, kỹ năng, lệnh tùy chỉnh, tác nhân phụ, plugin, máy chủ MCP, bộ nhớ tự động và tệp CLAUDE.md, giảm chi phí khởi tạo. Việc thêm CLAUDE.md gốc với `--append-system-prompt-file` cung cấp rõ ràng các tiêu chuẩn mã hóa của nhóm trong khi vẫn giữ nguyên hướng dẫn mặc định theo lời nhắc của hệ thống.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-127', 'cca-f', 127, 'You are incorporating Claude Code into your Continuous Integration/Continuous Deployment (CI/CD) pipeline. The system performs automated code reviews, creates test cases, and gives feedback on pull requests. You must design prompts that deliver actionable feedback while minimizing false positives.  
  
Your automated code review is failing to report genuine bugs in pull requests. An investigation shows that the review prompt says: “Only flag critical issues that would definitely cause production failures. Ignore minor concerns and anything you''re uncertain about.” Developers confirm that some missed bugs are real logic errors that the model investigated but decided not to report. The team requires review output to remain structured, with each finding tagged with metadata, and actionable.  
  
Which prompt modification both eliminates the cause of the suppressed findings and retains structured, tagged output for downstream filtering?', '[{"key":"A","text":"Add a second review pass that re-reads the diff using the same prompt, looking for anything the first pass may have missed."},{"key":"B","text":"Enable extended thinking and instruct the model to reason step-by-step about each code change before producing its review."},{"key":"C","text":"Remove all severity-related instructions from the prompt and let the model use its default judgment about what to report."},{"key":"D","text":"Instruct the model to report all findings with a confidence level and severity tag, deferring filtering to a downstream step."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Chính sách báo cáo yêu cầu sự chắc chắn và tác động quan trọng đến hoạt động sẽ ngăn chặn những phát hiện hợp lệ theo thiết kế. Việc đưa ra tất cả các phát hiện với siêu dữ liệu đáng tin cậy và mức độ nghiêm trọng sẽ bảo tồn từng lỗi tiềm ẩn để xem xét đồng thời cho phép hệ thống hạ nguồn áp dụng các ngưỡng và bộ lọc của riêng nó. Claude Code hỗ trợ đầu ra JSON có cấu trúc để tự động hóa theo chương trình.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-128', 'cca-f', 128, 'You are integrating Claude Code into your Continuous Integration/Continuous Deployment (CI/CD) pipeline. The system performs automated code reviews, generates test cases, and supplies feedback on pull requests. You need to design prompts that deliver actionable feedback while minimizing false positives.  
  
In addition to your CI pipeline, your organization has enabled Claude''s managed Code Review (via the Claude GitHub App) for this repository, and reviews run automatically on each PR. Reviews average 18 findings per PR. Developer feedback identifies three categories of unwanted noise:  
  
1. Style and formatting issues that your linter already enforces in CI  
2. Findings on auto-generated template code under `src/gen/`  
3. Rendering helper patterns that are intentional project conventions but are flagged because they resemble common anti-patterns  
  
Only about 4 findings per PR are real logic bugs.  
  
What is the most effective way to reduce this noise while preserving detection of real issues?', '[{"key":"A","text":"Create a REVIEW.md at the repository root with skip rules for CI-enforced checks and generated files, and a verification requirement that rendering-related findings must cite a specific line demonstrating incorrect behavior."},{"key":"B","text":"Add custom review instructions to a GitHub Actions workflow file, using the action''s prompt parameter to suppress lint-duplicate findings, ignore generated template code, and apply stricter evidence requirements for rendering-related issues."},{"key":"C","text":"Add detailed explanations to the project''s CLAUDE.md describing which patterns are intentional, that linting is handled separately by CI, and that the src/gen/ directory contains autogenerated template code."},{"key":"D","text":"Configure separate GitHub Action workflow files for each code area, one for generated code with findings suppressed, one for rendering code with custom review instructions, and a general workflow for everything else."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Đánh giá Claude Code được quản lý sử dụng `REVIEW.md` gốc kho lưu trữ để hướng dẫn chỉ dành cho đánh giá. Nó hỗ trợ bỏ qua các quy tắc cho đường dẫn và tìm kiếm danh mục, bao gồm mã được tạo và các bước kiểm tra đã được CI thực thi, đồng thời nó có thể yêu cầu bằng chứng `file:line` nguồn trước khi phát hiện liên quan đến hành vi được đăng. Các quy tắc nhắm mục tiêu này sẽ ngăn chặn tiếng ồn đã xác định trong khi vẫn duy trì việc xem xét các vấn đề về tính chính xác thực sự. [Claude Code Code Review documentation](https://code.claude.com/docs/en/code-review)', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-129', 'cca-f', 129, 'You are integrating Claude Code into your Continuous Integration/Continuous Deployment (CI/CD) pipeline. The system performs automated code reviews, creates test cases, and gives feedback on pull requests. You must design prompts that deliver actionable feedback while minimizing false positives.  
  
Your automated reviewer uses one prompt for security issues, API design, and business-logic correctness. Your evaluation suite shows strong recall for API-design findings (82%) but weak recall for business-logic edge cases in quiz scoring (34%). After you add few-shot examples of logic bugs to the prompt, logic recall rises to 41% but API-design recall falls to 68%.  
  
How should you address this trade-off to improve detection across both categories?', '[{"key":"A","text":"Provide the full repository as context instead of just the changed files and surrounding code, giving the model deeper visibility into business logic patterns."},{"key":"B","text":"Split the review into separate focused prompts – one for security and API design, another for business logic – each with dedicated examples, then consolidate findings before posting."},{"key":"C","text":"Upgrade to a more capable model tier, since its stronger reasoning will handle both concern types in a single prompt and eliminate the recall tradeoff."},{"key":"D","text":"Replace the few-shot examples with a detailed checklist of specific logic edge cases to verify, such as division-by-zero in score calculations and boundary conditions in grading thresholds."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các phương diện đánh giá độc lập được hưởng lợi từ lời nhắc đánh giá tập trung với hướng dẫn dành riêng cho từng nhiệm vụ và ví dụ tiêu biểu. Việc chạy các đánh giá logic nghiệp vụ và bảo mật/thiết kế API và logic nghiệp vụ riêng biệt sẽ ngăn các ví dụ logic nghiệp vụ mới chuyển sự chú ý khỏi thiết kế API; việc hợp nhất các kết quả đầu ra của họ sẽ duy trì một quy trình phản hồi yêu cầu kéo duy nhất. Hướng dẫn đánh giá của Anthropic hỗ trợ so sánh các biến thể nhanh chóng với các trường hợp thử nghiệm để xác định và lặp lại những khác biệt về hiệu suất đó.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-130', 'cca-f', 130, 'You are incorporating Claude Code into your Continuous Integration/Continuous Deployment (CI/CD) pipeline. The system performs automated code reviews, creates test cases, and gives feedback on pull requests. You must design prompts that deliver actionable feedback while minimizing false positives.  
  
Your automated review invokes the Claude API for each PR, using `tool_use` with a `report_findings` tool that returns a JSON array of finding objects (each containing `file_path`, `line_number`, `severity`, `category`, and `description`). During testing of a large PR that changes 30+ files, the response reaches the `max_tokens` limit and is truncated in the middle of the JSON, causing the pipeline parser to fail.  
  
What is the most effective way to address this?', '[{"key":"A","text":"Split the review into multiple API calls that each analyze a subset of the changed files, then merge the resulting findings arrays."},{"key":"B","text":"Add retry logic that detects truncated JSON and re-sends the request with instructions to report only critical and high severity findings."},{"key":"C","text":"Switch from tool_use to prompting Claude to return findings as a markdown list."},{"key":"D","text":"Increase `max_tokens` to the model''s maximum and instruct Claude to keep finding descriptions under 50 words each."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc phân vùng một yêu cầu kéo lớn thành các tập hợp con tệp nhỏ hơn sẽ giới hạn từng phản hồi `report_findings` có cấu trúc, tránh JSON không đầy đủ trong khi vẫn giữ lại các phát hiện trên toàn bộ PR. Các mảng kết quả có thể được hợp nhất sau mỗi phản hồi của công cụ hợp lệ. Điểm dừng `max_tokens` có thể cắt bớt khối sử dụng công cụ chưa hoàn chỉnh, do đó, một phản hồi có cấu trúc quá khổ duy nhất không phải là một thiết kế đáng tin cậy.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-131', 'cca-f', 131, 'You are creating developer-productivity tools with the Claude Agent SDK. The agent assists engineers in exploring unfamiliar codebases, understanding legacy systems, generating boilerplate code, and automating repetitive tasks. It uses the built-in tools (Read, Write, Bash, Grep, Glob) and integrates with Model Context Protocol (MCP) servers.  
  
During reviews, engineers often ask the agent to cross-reference code changes against Jira tickets—checking ticket descriptions, acceptance criteria, and recent comments. At present, this requires manually copying and pasting content into conversations. The team wants the agent to access this standard Jira ticket data directly.  
  
What is the most effective approach?', '[{"key":"A","text":"Integrate an existing Jira MCP server that exposes tickets, comments, and metadata through discoverable tool interfaces."},{"key":"B","text":"Use the Bash tool with `curl` to call Jira''s REST API, including authentication headers and parsing JSON responses inline."},{"key":"C","text":"Build a custom MCP server wrapping Jira''s API with tools designed specifically for this team''s code review workflow."},{"key":"D","text":"Export Jira tickets to markdown files in the repository that the agent accesses using the Read tool."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }MCP chuẩn hóa cách tác nhân kết nối với các nguồn dữ liệu và công cụ bên ngoài, thể hiện các khả năng thông qua các giao diện có thể khám phá. Máy chủ Jira MCP hiện tại cung cấp quyền truy cập trực tiếp vào vé, nhận xét và siêu dữ liệu tiêu chuẩn cần thiết, đồng thời tránh việc triển khai riêng, xử lý xác thực, phân tích cú pháp JSON và bảo trì liên tục theo yêu cầu của tích hợp REST tùy chỉnh hoặc máy chủ tùy chỉnh.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-132', 'cca-f', 132, 'You are creating developer-productivity tools with the Claude Agent SDK. The agent assists engineers in exploring unfamiliar codebases, understanding legacy systems, generating boilerplate code, and automating repetitive work. It uses the built-in tools (Read, Write, Bash, Grep, Glob) and connects with Model Context Protocol (MCP) servers.  
  
An engineer who has just joined the team asks the agent to help them understand the authentication and authorization architecture before making security improvements. The codebase contains 800+ files across multiple services.  
  
Which exploration strategy will most effectively build understanding, considering Claude built-in tools and context limits?', '[{"key":"A","text":"Read all files containing \"auth\", \"login\", \"permission\", or \"token\" in their content or filename."},{"key":"B","text":"Use Grep to find authentication entry points, read those files, then follow imports and function calls to map the auth flow incrementally."},{"key":"C","text":"Launch parallel subagents to explore different services simultaneously, then synthesize their findings into an architectural overview."},{"key":"D","text":"Read any CLAUDE.md and README files first, then ask the engineer to specify which 10-15 files are most important for understanding the auth system."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Cấu trúc xác thực được hiểu rõ nhất bằng cách định vị các điểm nhập xác thực thực bằng tìm kiếm được nhắm mục tiêu, đọc các hoạt động triển khai đó và theo dõi quá trình nhập cũng như lệnh gọi hàm của chúng thông qua hệ thống. Điều này dần dần tuân theo luồng xác thực thực thi trong khi hạn chế nội dung tệp không liên quan và duy trì ngữ cảnh cho các mối quan hệ quan trọng. Tài liệu SDK của Anthropic hỗ trợ sử dụng theo chương trình các công cụ có sẵn, bao gồm quy trình làm việc theo định hướng tìm kiếm và đọc tệp.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-133', 'cca-f', 133, '$36', '[{"key":"A","text":"Add an orchestrator that routes questions to a single server based on keywords"},{"key":"B","text":"Expose each server''s content catalog as MCP resources – issue summaries, documentation hierarchy, database schemas"},{"key":"C","text":"Consolidate all three servers into a unified MCP server with cross-referencing capabilities"},{"key":"D","text":"Add a prepare_investigation tool to each server that accepts a natural language question and returns relevant content summaries"}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Tài nguyên MCP cho phép máy chủ hiển thị dữ liệu theo ngữ cảnh để khách hàng khám phá, liệt kê và đọc. Việc cung cấp danh mục tóm tắt vấn đề, cấu trúc tài liệu và lược đồ cơ sở dữ liệu giúp hiển thị nội dung có liên quan trước khi chọn lệnh gọi công cụ hướng hành động, giảm các lệnh gọi khám phá và sử dụng ngữ cảnh không cần thiết trong khi vẫn giữ được quyền truy cập vào cả ba hệ thống.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published'),
  ('cca-134', 'cca-f', 134, 'You are creating developer-productivity tools with the Claude Agent SDK. The agent helps engineers explore unfamiliar codebases, understand legacy systems, generate boilerplate code, and automate repetitive work. It uses the built-in tools (Read, Write, Bash, Grep, Glob) and integrates with Model Context Protocol (MCP) servers.  
  
You are building a security-scanning workflow.  
  
When engineers must find every occurrence of a dangerous function such as `eval()` throughout a large codebase, which tool should the agent use to search file contents?', '[{"key":"A","text":"Use Glob with a pattern like `**/*eval*` to find files, then Read each matching file."},{"key":"B","text":"Use Bash to run `Is -R | grep eval` to recursively list files containing eval."},{"key":"C","text":"Read the project''s main entry file and follow import statements to trace where eval might be used."},{"key":"D","text":"Use Grep to search for the pattern \"eval(\" across all files in the codebase."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Grep tìm kiếm nội dung của các tệp theo mẫu được chỉ định trên cơ sở mã, biến nó thành công cụ tích hợp thích hợp để định vị mọi hoạt động sử dụng `eval(`. Glob khớp với đường dẫn tệp, trong khi Đọc dùng để kiểm tra các tệp đã chọn.', 'General', ARRAY['CCA-F', 'General']::text[], NULL, 'published')
